window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0173", [{"word":"supply","ipa_uk":"/səˈplaɪ/","ipa_us":"/səˈplaɪ/","definition_zh":"供应；提供；补给；供给量；（supplies）补给品","definition_en":"to give or make available what is needed, or the amount of something that is available","core_image":"仓库门口不断递出的货箱，正好填满对面伸过来的空手","scene":"面包房每天清晨把新出炉的面包送到街角几家小店。Every morning the bakery must supply three corner shops with fresh bread.","sceneCN":"面包房每天清晨把新出炉的面包送到街角几家小店；句中的 supply 指「持续把所需之物交到需要的人手里」（第 1 个义项：按需要提供）。图中可辨识物件：面包箱、送货推车、卷帘门、清晨的天色。","pos":[{"tag":"vt.","zh":"供应；提供；（用 supplies 形式）补给"},{"tag":"vi.","zh":"临时替补（替他人代职）"},{"tag":"n.","zh":"供给量；供应（体系）；（复数）补给品"}],"collocations":[{"phrase":"supply chain","zh":"供应链"},{"phrase":"water supply","zh":"供水"},{"phrase":"power supply","zh":"电源；电力供应"},{"phrase":"in short supply","zh":"供应不足；稀缺"},{"phrase":"supply sb with sth","zh":"向某人提供某物"},{"phrase":"supply and demand","zh":"供给与需求"}],"forms":[{"label":"三单（he/she/it）","form":"supplies"},{"label":"过去式","form":"supplied"},{"label":"过去分词","form":"supplied"},{"label":"现在分词","form":"supplying"},{"label":"名词（供应；供给量）","form":"supply"},{"label":"名词复数（补给品）","form":"supplies"}],"derivatives":[{"word":"supplier","pos":"n.","zh":"供应商；供货方"},{"word":"supplies","pos":"n.","zh":"补给品；用品"},{"word":"supply-side","pos":"adj.","zh":"供给面的（经济学用语）"},{"word":"oversupply","pos":"v./n.","zh":"供应过多；过剩供应"},{"word":"undersupply","pos":"n./v.","zh":"供应不足"}],"senses":[{"no":"01","title":"Provide what someone needs","titleCN":"把所需之物持续提供给某人或某处","definition":"to give a person or a place the things they need, usually regularly","definitionCN":"持续地把某人或某处需要的东西给过去","example":"The bakery supplies three corner shops with fresh bread every morning.","exampleCN":"面包房每天清晨向三家街角小店供应新鲜面包。","why":"The Latin source means to fill up from below, so providing is pictured as filling a gap that is already there.","whyCN":"拉丁词源意为「从下往上填满」，因此「提供」被设想成填上原本就存在的空缺。"},{"no":"02","title":"Sell goods to a market","titleCN":"作为业务向市场供货","definition":"to make goods available to buyers as a regular commercial activity","definitionCN":"作为常规商业活动把货物提供给买方","example":"The mill supplies parts to three carmakers.","exampleCN":"这家工厂向三家汽车制造商供应零件。","why":"Once providing became a trade, the word named the seller's side of the market.","whyCN":"当「提供」变成一门生意，这个词就用来指市场中卖方这一边。"},{"no":"03","title":"Make up for a deficiency","titleCN":"补上欠缺的部分","definition":"to provide the thing that is missing so that a gap is closed","definitionCN":"把缺失的东西补上，使缺口闭合","example":"A late grant supplied the funds the project still lacked.","exampleCN":"一笔迟到的拨款补上了项目仍然缺少的资金。","why":"Filling a gap is the oldest image of the word, and here what gets filled is not a hand but a deficit.","whyCN":"填补缺口是这个词最古老的意象，这里被填上的不是手，而是一处亏空。"},{"no":"04","title":"The amount available","titleCN":"可供使用的数量；供给量","definition":"the quantity of something that is available to be used or bought","definitionCN":"可供使用或购买的数量","example":"The supply of clean water fell sharply after the drought.","exampleCN":"干旱之后，清洁水的供给量急剧下降。","why":"The noun turns the act of providing into the stock that results from it.","whyCN":"名词把「提供」这个动作转成由它产生的存量。"},{"no":"05","title":"The system that delivers a service","titleCN":"输送服务的整套系统","definition":"the network or service through which something such as power or water is delivered","definitionCN":"电力、水等得以输送的管网或服务体系","example":"Electricity supply was restored two hours after the storm.","exampleCN":"暴风雨过后两小时，电力供应恢复了。","why":"A whole delivery system is spoken of as one supplying thing, so the act becomes an institution.","whyCN":"整套输送系统被当作一个「供应者」来说，动作因此变成了机构。"},{"no":"06","title":"The economic quantity offered","titleCN":"经济学意义上的供给量","definition":"the amount of a good that sellers are willing to offer at a particular price","definitionCN":"在某一价格下卖方愿意提供的货物数量","example":"At higher prices, the supply of coffee beans increases.","exampleCN":"价格越高，咖啡豆的供给量越大。","why":"Political economy narrowed the general stock to the quantity sellers put forward at a given price.","whyCN":"政治经济学把泛指的存量收窄为卖方在给定价格下报出的数量。"},{"no":"07","title":"Provisions for a journey","titleCN":"出行携带的补给品","definition":"food, equipment and other goods carried for a particular purpose","definitionCN":"为特定目的携带的食物、装备等物资","example":"The expedition packed its supplies before the first snow.","exampleCN":"考察队在初雪之前收拾好了补给。","why":"Concrete goods supplied to people became a plural noun for the stores themselves.","whyCN":"发给人的具体物资，转成了指这些物资本身的复数名词。"},{"no":"08","title":"A temporary substitute","titleCN":"临时替补者","definition":"a person who fills another's place for a time, especially a teacher","definitionCN":"暂时顶替他人职位的人，尤指代课教师","example":"A retired teacher supplies for the department whenever a colleague is away.","exampleCN":"系里有同事请假时，一位退休教师就来代课。","why":"Someone who fills a post temporarily is literally filling an empty place, which keeps the original image.","whyCN":"临时顶上职位的人，字面上就是在填一个空位，这保留了最初的意象。"}],"etymology":{"intro":{"en":"Supply comes from Latin supplere 'to fill up, complete', through Old French. It first meant filling a deficiency and only later named goods and market quantities.","cn":"supply 经古法语来自拉丁 supplere「填满、补齐」，最初指把缺的东西补上，后来才指货物与市场供给量。"},"items":[{"era":"LATIN PLERE","en":"Plere meant 'to fill'. Its Indo-European ancestor is a reconstruction, and in classical use the short verb appears mostly inside compounds.","cn":"plere 意为「填满」。其印欧语祖先属重构形式，在古典用法中这个短动词多出现在复合词里。"},{"era":"LATIN SUPPLERE","en":"Sub- 'up from below' plus plere gave supplere, 'to fill up, make complete, make good a lack'.","cn":"sub-「从下往上」加 plere 构成 supplere，意为「填满、补齐、弥补欠缺」。"},{"era":"OLD FRENCH","en":"Old French suppleer and souploier brought the verb into Middle English in the fourteenth century, at first in the sense of filling a deficiency.","cn":"古法语 suppleer 与 souploier 在十四世纪把这个动词带入中古英语，最初指填补欠缺。"},{"era":"MILITARY STORES","en":"From the fifteenth century armies were said to be supplied with food and equipment, and the plural noun for those stores followed.","cn":"从十五世纪起，军队被说成获得粮食与装备的供应，指这些物资的复数名词随后出现。"},{"era":"POLITICAL ECONOMY","en":"Eighteenth- and nineteenth-century political economy gave the word its technical sense: the quantity sellers offer at a given price.","cn":"十八、十九世纪的政治经济学赋予这个词技术义：卖方在给定价格下愿意提供的数量。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper Indo-European root of plere is a reconstruction rather than a recorded form, and the first date of the economic sense is approximate.","cn":"来源不确定：plere 更早的印欧词根是重构形式，并非有记录的形式；经济义的最早年代也只是约数。"}]},"similar":{"note":{"en":"Group one holds words that look or sound like supply; group two holds verbs with a close meaning but a different picture.","cn":"第一组是形音上与 supply 相近的词；第二组是意思接近但意象不同的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"supplement","ipa":"/ˈsʌplɪmənt/","tag":"same Latin source","definition":"Built on the same Latin verb, but as a noun it means something added to complete a whole, not the act of delivering goods.","definitionCN":"同出拉丁动词，但作名词指补足整体的附加物，不是持续交货的动作。"},{"word":"supple","ipa":"/ˈsʌpəl/","tag":"different root","definition":"From Latin supplex, 'bending the knees', and means pliant; the shared first syllable is accidental.","definitionCN":"来自拉丁 supplex「屈膝」，意为柔韧；相同的首音节只是巧合。"},{"word":"apply","ipa":"/əˈplaɪ/","tag":"different root","definition":"From Latin applicare, 'to fold toward', built on plicare 'to fold', so it is not related to supply.","definitionCN":"来自拉丁 applicare「向…折拢」，由 plicare「折」构成，与 supply 不同源。"},{"word":"supplant","ipa":"/səˈplɑːnt/","tag":"different root","definition":"From Latin supplantare, 'to trip up', built on planta 'sole of the foot'; it means to displace, not to provide.","definitionCN":"来自拉丁 supplantare「绊倒」，由 planta「脚掌」构成；意为取代，不是提供。"}]},{"heading":"NEAR MEANING","entries":[{"word":"provide","ipa":"/prəˈvaɪd/","tag":"general verb","definition":"The neutral verb for making something available; it carries no image of filling a gap.","definitionCN":"使某物可用的中性动词，不含「填补空缺」的意象。"},{"word":"furnish","ipa":"/ˈfɜːnɪʃ/","tag":"supply in quantity","definition":"To supply a room or a person with a full set of things, often furniture or information.","definitionCN":"为房间或人配齐一整套东西，常指家具或信息。"},{"word":"deliver","ipa":"/dɪˈlɪvə/","tag":"carry to a place","definition":"To bring goods to a destination; it stresses transport, while supply stresses the ongoing relation.","definitionCN":"把货物送到目的地，强调运输；supply 强调持续的供应关系。"},{"word":"stock","ipa":"/stɒk/","tag":"keep on hand","definition":"To keep a supply of goods in a shop or warehouse; the focus is storage, not the act of giving.","definitionCN":"在店铺或仓库备货；重点是储存，不是交付。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives.","cn":"正常联想：真实的构词成分、真实的固定搭配与真实的同族词。"},"normal":[{"en":"Sub- 'up from below' plus plere 'to fill': a supply fills the empty space under demand.","cn":"sub-「从下往上」加 plere「填满」：供给填满需求下方的空位。"},{"en":"The family runs supply, supplier, supplies, oversupply and undersupply.","cn":"同族词有 supply、supplier、supplies、oversupply 与 undersupply。"},{"en":"Fixed phrases mark the everyday sense: water supply, power supply, in short supply.","cn":"固定说法标出日常义：供水、电源、供应不足。"},{"en":"The same Latin verb gives supplement and complete, both about making a whole.","cn":"同一拉丁动词还给出 supplement 与 complete，都表示凑成完整。"},{"en":"Economics pairs it with demand: supply curves rise with price.","cn":"经济学把它与需求配对：供给曲线随价格上升。"}],"abstract":[{"en":"Picture a bucket under a leaking roof, catching exactly what the dry room lacks.","cn":"想象屋顶漏水处放着一只桶，接住的正是干燥房间所缺的水。"},{"en":"Picture a shelf that refills itself overnight, so no one ever sees it empty.","cn":"想象一只夜里自动补满的货架，谁也没见过它空着。"},{"en":"Picture a queue where every empty hand is matched by something falling into it.","cn":"想象一支队伍，每只空手都有东西落进去。"}]},"examples":[{"en":"Local farms supply the school kitchens with vegetables all year.","cn":"本地农场全年向学校食堂供应蔬菜。"},{"en":"The report supplies the evidence that the earlier study lacked.","cn":"这份报告补上了先前研究缺失的证据。"},{"en":"Water supply to the northern districts was cut for six hours.","cn":"北部城区的供水被中断了六小时。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「sup（在下面）+ ply（填满）」——从下面把空缺填满，就是供应与补给","word":"supply"},"root":"拉丁 supplere「填满、补齐」= sub-（从下往上）+ plere「填满」；更早的印欧词根为重构形式。","sensesIntro":{"en":"Eight senses follow one gesture, filling an empty place: a hand, a market, a deficit, a stock, a service network, a price-based offer, a traveller's stores and finally an empty post.","cn":"八个义项围绕同一个动作——把空处填上：空着的手、市场、亏空、库存、服务网络、按价报出的数量、旅人的物资，最后是一个空缺的职位。"},"semanticMap":{"core":{"en":"CORE IMAGE: a container being filled from below until nothing is missing.","cn":"核心意象：一只容器从下方被填满，直到不再缺什么。"},"chain":["FILL A GAP","PROVIDE GOODS","MEET A DEFICIT","STOCK AVAILABLE","DELIVERY NETWORK","QUANTITY OFFERED"],"branches":[{"senses":"01 · 08","en":"EMPTY PLACE: a hand and a vacant post are both holes that someone fills.","cn":"空位：空着的手与空缺的职位，都是被人填上的洞。"},{"senses":"02 · 03","en":"DEFICIT: selling to a market and covering a shortfall are both closing what is missing.","cn":"亏空：向市场供货与弥补短缺，都是把缺的部分合上。"},{"senses":"04 · 05","en":"SYSTEM: the stock on hand grows into the network that keeps delivering it.","cn":"系统：手头的库存扩大为持续送货的网络。"},{"senses":"06","en":"PRICE OFFER: economics turns the filled container into a quantity offered at a price.","cn":"报价：经济学把被填满的容器化为按价报出的数量。"},{"senses":"07","en":"GOODS CARRIED: travellers' stores are the filling made portable.","cn":"随身物资：旅人的补给是「填满」变得可携带。"}]},"affixes":{"intro":{"en":"Supply is a Latin verb built from a prefix and a filling root, and that root also builds several common English words.","cn":"supply 是由前缀与「填满」词根构成的拉丁动词，这个词根还构成若干常用英语词。"},"latinIntro":{"en":"Latin plere gives supply, supplement, complete and deplete; sub- adds the direction of filling from below.","cn":"拉丁 plere 衍生 supply、supplement、complete 与 deplete；sub- 增添「从下往上填」的方向。"},"items":[{"word":"sub-","structure":"Latin prefix","meaning":"under; up from below","meaningCN":"在下；从下往上","example":"The prefix pictures the filling rising into the empty space.","exampleCN":"这个前缀把「填」画成从下往空处升起。"},{"word":"plere","structure":"Latin verb, second conjugation","meaning":"to fill","meaningCN":"填满","example":"The root supplies the core idea of fullness.","exampleCN":"这个词根提供「满」的核心意思。"},{"word":"supply","structure":"sub- + plere","meaning":"to fill up, provide","meaningCN":"补齐；供应","example":"The bakery supplies three corner shops.","exampleCN":"面包房向三家街角小店供货。"},{"word":"supplier","structure":"supply + -er (one who does)","meaning":"a company or person that supplies","meaningCN":"供应商；供货方","example":"The supplier missed the spring deadline.","exampleCN":"供应商错过了春季的交货期限。"},{"word":"supplies","structure":"supply + -s (plural)","meaning":"goods provided for a purpose","meaningCN":"补给品；用品","example":"The climbers carried extra supplies.","exampleCN":"登山者带了额外的补给。"},{"word":"supplement","structure":"sub- + plere + -ment (result)","meaning":"something added to complete a whole","meaningCN":"补充物；增刊","example":"A vitamin supplement cannot replace a meal.","exampleCN":"维生素补充剂不能代替一餐。"},{"word":"complete","structure":"com- + plere","meaning":"to make whole","meaningCN":"使完整","example":"One more page will complete the file.","exampleCN":"再加一页，这份文件就完整了。"},{"word":"deplete","structure":"de- + plere","meaning":"to empty out","meaningCN":"耗尽；取空","example":"The long drought depleted the reservoir.","exampleCN":"长期干旱耗尽了水库。"},{"word":"oversupply","structure":"over- + supply","meaning":"to supply too much","meaningCN":"供应过多","example":"Cheap loans oversupplied the housing market.","exampleCN":"廉价贷款使房市供应过剩。"}],"latinEntries":[{"word":"supplere","structure":"supplere, supplevi, suppletum (verb, second conjugation)","meaning":"to fill up, complete, make good","meaningCN":"填满；补齐；补足"},{"word":"plere","structure":"plere, plevi, pletum (verb, second conjugation)","meaning":"to fill","meaningCN":"填满"},{"word":"supplementum","structure":"supplementum, supplementi (n., second declension)","meaning":"a filling up, a supplement","meaningCN":"补充；补足之物"}],"derivatives":[{"word":"supplier","pos":"n.","zh":"供应商；供货方"},{"word":"supplies","pos":"n.","zh":"补给品；用品"},{"word":"oversupply","pos":"v./n.","zh":"供应过多；过剩供应"},{"word":"undersupply","pos":"n./v.","zh":"供应不足"},{"word":"supply-side","pos":"adj.","zh":"供给面的"}]}},{"word":"demand","ipa_uk":"/dɪˈmɑːnd/","ipa_us":"/dɪˈmænd/","definition_zh":"要求；强求；需要；需求；需求量；（法律）请求权","definition_en":"to ask for something forcefully, or to need something; also the amount that buyers want at a given price","core_image":"一只手伸到柜台前，掌心朝上，要求对方立刻把东西交出来","scene":"罢工的工人把一份写满条件的清单放在桌上，要求管理层当天下班前答复。The strikers demanded an answer from management before the end of the day.","sceneCN":"罢工工人把写满条件的清单放在桌上，要管理层当天下班前答复；句中的 demanded 指「以强硬态度要求对方作出回应」（第 1 个义项：提出不容推脱的要求）。图中可辨识物件：写满条款的清单、桌面、工会袖标、墙上的时钟。","pos":[{"tag":"vt.","zh":"要求（并期待对方服从）；需要"},{"tag":"vi.","zh":"提出要求；需求"},{"tag":"n.","zh":"要求；需求；需求量；催款通知"}],"collocations":[{"phrase":"in demand","zh":"抢手；需求旺盛"},{"phrase":"on demand","zh":"按需；一经要求即提供"},{"phrase":"demand for sth","zh":"对某物的需求"},{"phrase":"meet demand","zh":"满足需求"},{"phrase":"consumer demand","zh":"消费者需求"},{"phrase":"demand that","zh":"要求（后接从句，常用虚拟语气）"}],"forms":[{"label":"三单（he/she/it）","form":"demands"},{"label":"过去式","form":"demanded"},{"label":"过去分词","form":"demanded"},{"label":"现在分词","form":"demanding"},{"label":"名词（要求；需求）","form":"demand"},{"label":"名词复数","form":"demands"},{"label":"形容词（苛求的；费力的）","form":"demanding"}],"derivatives":[{"word":"demanding","pos":"adj.","zh":"苛求的；耗费精力的"},{"word":"demand-side","pos":"adj.","zh":"需求面的（经济学用语）"},{"word":"on-demand","pos":"adj.","zh":"按需提供的"},{"word":"undemanding","pos":"adj.","zh":"要求不高的；轻松的"}],"senses":[{"no":"01","title":"Ask forcefully and expect obedience","titleCN":"强硬要求，指望对方照办","definition":"to ask for something in a way that shows one expects to be obeyed","definitionCN":"以显示出「必须照办」的方式提出要求","example":"The strikers demanded an answer from management before the end of the day.","exampleCN":"罢工工人要求管理层当天下班前给出答复。","why":"The Latin verb meant to put something into someone's hand as a charge, so the ask arrives with authority behind it.","whyCN":"拉丁动词意为把某事作为委托交到别人手里，因此这个要求自带权威。"},{"no":"02","title":"Require as a necessary condition","titleCN":"作为必要条件而需要","definition":"to need something if a person or plan is to succeed","definitionCN":"人或计划若要成功就离不开某物","example":"A long climb demands patience as much as strength.","exampleCN":"长途攀登既需要体力，也同样需要耐心。","why":"A requirement is a claim made by the situation rather than by a person, so the same verb covers both.","whyCN":"条件提出的要求来自处境而非某个人，同一个动词因此兼指两种「要求」。"},{"no":"03","title":"Claim something by right","titleCN":"依法或依权利索取","definition":"to claim something as one's due, especially in law","definitionCN":"把某物作为应得之物索取，尤指在法律上","example":"She demanded compensation for the damage to her shop.","exampleCN":"她要求赔偿店铺所受的损失。","why":"Once a request rests on a right, it stops being a favour asked and becomes a claim asserted.","whyCN":"当请求建立在权利之上，它就不再是求人情，而是主张权利。"},{"no":"04","title":"A forceful request","titleCN":"强硬的要求（名词）","definition":"a request made in a tone that leaves little room for refusal","definitionCN":"语气上几乎不留拒绝余地的请求","example":"Their demand for safer working hours was ignored for a year.","exampleCN":"他们关于更安全工作时段的要求被忽视了一年。","why":"The noun names the spoken request itself, before any legal right or market quantity enters.","whyCN":"这个名词指说出口的请求本身，尚未涉及法律权利或市场数量。"},{"no":"05","title":"The economic quantity wanted","titleCN":"经济学意义上的需求量","definition":"the amount of a good that buyers are willing to buy at a particular price","definitionCN":"在某一价格下买方愿意购买的数量","example":"Demand for housing rose sharply after the rate cut.","exampleCN":"降息之后，住房需求急剧上升。","why":"Political economy turned the general wanting into a measurable quantity tied to price.","whyCN":"政治经济学把泛泛的「想要」变成与价格挂钩、可测量的数量。"},{"no":"06","title":"Market need for goods or skills","titleCN":"市场对货物或技能的需要","definition":"the general need for a product or a kind of worker in a market","definitionCN":"市场对某种产品或某类劳动者的总体需要","example":"There is strong demand for skilled welders in the region.","exampleCN":"该地区对熟练焊工的需求很强。","why":"The technical quantity sense softened back into everyday talk about what people need.","whyCN":"技术性的数量义又软化为日常所说的「人们需要什么」。"},{"no":"07","title":"Claims on time and energy","titleCN":"对时间与精力的索取","definition":"the things that a job, family or situation requires of a person","definitionCN":"工作、家庭或处境要求一个人付出的事物","example":"The demands of a young family left him little time to read.","exampleCN":"年幼孩子的家庭事务占去了他读书的时间。","why":"What a situation asks of a person is a demand in the same sense as a claim, only the currency is time.","whyCN":"处境向人索取的东西与「索权」同义，只是交换的通货变成了时间。"},{"no":"08","title":"A written call for payment","titleCN":"书面催款通知","definition":"a formal notice requiring payment of money owed","definitionCN":"要求支付欠款的正式通知","example":"The landlord sent a final demand for the unpaid rent.","exampleCN":"房东寄来了未付房租的最后催款通知。","why":"A bill is a claim put on paper, so the legal sense hardened into a standard commercial document.","whyCN":"账单就是把主张写在纸上，法律义因此固化为一种标准商业文书。"}],"etymology":{"intro":{"en":"Demand comes from Latin demandare 'to entrust, charge', through Old French demander 'to ask'. The modern sense of asking insistently grew out of the idea of handing someone a charge.","cn":"demand 经古法语 demander「请求」来自拉丁 demandare「委托、责成」；现代「强硬要求」的意思是从「把任务交到别人手里」发展来的。"},"items":[{"era":"LATIN MANDARE","en":"Mandare meant 'to order, entrust', generally explained as manus 'hand' plus dare 'to give', that is, putting something into someone's hand.","cn":"mandare 意为「命令、委托」，一般解释为 manus「手」加 dare「给」，即把某物放到某人手中。"},{"era":"LATIN DEMANDARE","en":"De- plus mandare produced demandare, 'to entrust with, give in charge'. Whether de- here means 'away' or 'thoroughly' is debated.","cn":"de- 加 mandare 构成 demandare「委托、责成」。这里的 de- 究竟表示「离开」还是「彻底」，学界有不同看法。"},{"era":"OLD FRENCH","en":"Old French demander shifted the sense toward 'to ask, request', and Middle English took the verb in the fourteenth century.","cn":"古法语 demander 把词义转向「询问、请求」，中古英语在十四世纪接受了这个动词。"},{"era":"LEGAL CLAIM","en":"By the fifteenth and sixteenth centuries a demand could be a formal claim to money or property, which produced the written notice still used today.","cn":"到十五、十六世纪，demand 可指对钱财或财产的正式索取，由此产生了沿用至今的书面催款通知。"},{"era":"POLITICAL ECONOMY","en":"Eighteenth- and nineteenth-century economists fixed the technical sense: the quantity buyers will take at a given price.","cn":"十八、十九世纪的经济学家固定了技术义：买方在给定价格下愿意买走的数量。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the force of de- in demandare is unsettled, and the exact first date of the economic sense is approximate.","cn":"来源不确定：demandare 中 de- 的作用尚无定论，经济义的最早确切年代也只是约数。"}]},"similar":{"note":{"en":"Group one shares the Latin root that means putting something into someone's hand; group two are near verbs of softer or narrower force.","cn":"第一组共享「把某物交到某人手中」这一拉丁词根；第二组是语气更软或范围更窄的近义动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"command","ipa":"/kəˈmɑːnd/","tag":"same root, with authority","definition":"Com- plus mandare: to order with the weight of rank behind it, so the speaker must hold authority, which demand does not require.","definitionCN":"com- 加 mandare：带着职权的分量下令，说话者必须有权威，而 demand 不要求这一点。"},{"word":"mandate","ipa":"/ˈmændeɪt/","tag":"same root, noun","definition":"The noun from the same verb: an official authority or instruction given to someone, not a request for goods.","definitionCN":"同出这一动词的名词：授予某人的正式授权或指令，不是对货物的要求。"},{"word":"remand","ipa":"/rɪˈmɑːnd/","tag":"same root, legal","definition":"Re- 'back' plus mandare: to send a case or a prisoner back, a legal term with no sense of asking.","definitionCN":"re-「向后」加 mandare：把案件或囚犯送回，是法律术语，不含「请求」之意。"},{"word":"mandatory","ipa":"/ˈmændətəri/","tag":"same root, adjective","definition":"From the same root: required by rule, describing the obligation rather than the act of asking.","definitionCN":"同出这一词根：规则上必须做的，描述义务而非索取的动作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"require","ipa":"/rɪˈkwaɪə/","tag":"need, not ask","definition":"To make something necessary; it states the condition and never the spoken request.","definitionCN":"使某事成为必要；它陈述条件，从不用来说出口的请求。"},{"word":"request","ipa":"/rɪˈkwest/","tag":"polite ask","definition":"To ask for something politely; it lacks the pressure that demand carries.","definitionCN":"客气地请求；没有 demand 那种压力。"},{"word":"claim","ipa":"/kleɪm/","tag":"assert a right","definition":"To assert that something is owed to you; it matches the legal sense of demand but not the market sense.","definitionCN":"主张某物应归自己；与 demand 的法律义相符，但不含市场义。"},{"word":"need","ipa":"/niːd/","tag":"inner necessity","definition":"To require something for survival or proper function; it describes lack, not insistence.","definitionCN":"为生存或正常运转而必需；描述缺乏，不含强硬。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Latin pieces, the fixed phrases and the real word family.","cn":"正常联想：拉丁构词成分、固定搭配与真实的同族词。"},"normal":[{"en":"Manus 'hand' plus dare 'give': a demand places a charge in someone's hand.","cn":"manus「手」加 dare「给」：要求就是把一项任务放进对方手里。"},{"en":"The family runs demand, demanding, demand-side and undemanding.","cn":"同族词有 demand、demanding、demand-side 与 undemanding。"},{"en":"Fixed phrases: in demand, on demand, meet demand, consumer demand.","cn":"固定说法：抢手、按需、满足需求、消费者需求。"},{"en":"The same root appears in command, mandate, remand and mandatory.","cn":"同一词根出现在 command、mandate、remand 与 mandatory 中。"},{"en":"Economics pairs it with supply, and the pair sets price.","cn":"经济学把它与供给配对，这一对决定价格。"}],"abstract":[{"en":"Picture an open palm held out and nothing in it yet.","cn":"想象一只摊开的手掌伸出来，里面还空着。"},{"en":"Picture a written slip pressed into that palm and the fingers closing over it.","cn":"想象一张写好的字条被按进那只手心，手指随即合拢。"},{"en":"Picture an elastic band of wanting that pulls a shelf of goods toward it.","cn":"想象一条「想要」的橡皮筋，把一整架货物拉向自己。"}]},"examples":[{"en":"The union demanded that the safety report be published in full.","cn":"工会要求完整公布那份安全报告。"},{"en":"Repairing the roof will demand most of the summer budget.","cn":"修屋顶将用掉夏季预算的大部分。"},{"en":"Demand for electric cars has outpaced the supply of batteries.","cn":"电动汽车的需求已经超过电池的供给。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「de（加强）+ mand（命令，同 command）」——一再下命令，就是要求与需求","word":"demand"},"root":"拉丁 demandare「委托、命令」= de-（加强或离开）+ mandare「交到手中」，而 mandare = manus「手」+ dare「给」。","sensesIntro":{"en":"Eight senses follow one gesture, a claim pressed into a hand: an order, a condition, a legal right, the spoken request, a market quantity, a market need, the claims of daily life and finally a bill on paper.","cn":"八个义项围绕同一个动作——把一项主张按进别人手里：命令、条件、法定权利、说出口的请求、市场数量、市场需要、日常生活的索取，最后是纸上的催款单。"},"semanticMap":{"core":{"en":"CORE IMAGE: an open palm receiving a written charge that the other side must honour.","cn":"核心意象：一只摊开的手掌接过一张对方必须兑现的委托字条。"},"chain":["ASK FIRMLY","EXPECT COMPLIANCE","REQUIRE AS NEED","CLAIM BY RIGHT","AMOUNT WANTED","BILL FOR PAYMENT"],"branches":[{"senses":"01 · 02","en":"ASK AND NEED: a spoken order and a task's condition both press on someone.","cn":"要求与需要：说出口的命令与任务的条件，都对某人形成压力。"},{"senses":"03 · 08","en":"CLAIM BY RIGHT: a legal claim and a bill are the same assertion put in writing.","cn":"依权索取：法律主张与账单是同一项主张写成了文字。"},{"senses":"04","en":"SPOKEN REQUEST: the noun names the request itself, before any right or quantity exists.","cn":"口头请求：名词指请求本身，此时还没有权利或数量。"},{"senses":"05 · 06","en":"MARKET WANT: economics measures the wanting as a quantity and then loosens it back into general need.","cn":"市场想要：经济学把「想要」量化为数量，随后又松回泛指的需要。"},{"senses":"07","en":"BURDEN: the claims of family and work are demands paid in time rather than money.","cn":"负担：家庭与工作的索取，是用时间而非金钱支付的。"}]},"affixes":{"intro":{"en":"Demand is a Latin verb made of a prefix, a hand and a giving root, and the whole family can be read piece by piece.","cn":"demand 是由前缀、「手」与「给」两个词根构成的拉丁动词，整个词族可以逐块读出。"},"latinIntro":{"en":"Latin mandare and manus give demand, command, mandate, remand and mandatory.","cn":"拉丁 mandare 与 manus 衍生 demand、command、mandate、remand 与 mandatory。"},"items":[{"word":"de-","structure":"Latin prefix","meaning":"away; thoroughly","meaningCN":"离开；彻底","example":"The prefix adds force or direction to the charge.","exampleCN":"这个前缀给「委托」增添力度或方向。"},{"word":"mandare","structure":"Latin verb, first conjugation","meaning":"to order, entrust","meaningCN":"命令；委托","example":"The verb carries the idea of handing over a charge.","exampleCN":"这个动词带着「把任务交出去」的意思。"},{"word":"manus","structure":"Latin noun, fourth declension","meaning":"hand","meaningCN":"手","example":"The hand is the image behind the whole family.","exampleCN":"「手」是整个词族背后的意象。"},{"word":"demand","structure":"de- + mandare","meaning":"to ask with authority; a claim","meaningCN":"强硬要求；索求","example":"The strikers demanded an answer.","exampleCN":"罢工者要求给出答复。"},{"word":"command","structure":"com- + mandare","meaning":"to order with authority","meaningCN":"命令；指挥","example":"The officer commanded the unit to withdraw.","exampleCN":"军官命令部队撤退。"},{"word":"mandate","structure":"mandare + -um (thing done)","meaning":"an official instruction or authority","meaningCN":"授权；指令","example":"The agency has a clear mandate to inspect.","exampleCN":"该机构有明确的检查授权。"},{"word":"demanding","structure":"demand + -ing","meaning":"making great claims on someone","meaningCN":"苛求的；费力的","example":"A demanding client tests every detail.","exampleCN":"苛刻的客户会检验每个细节。"},{"word":"remand","structure":"re- + mandare","meaning":"to send back","meaningCN":"还押；发回","example":"The court remanded the case for retrial.","exampleCN":"法院把案件发回重审。"},{"word":"mandatory","structure":"mandare + -atory","meaning":"required by order","meaningCN":"强制性的","example":"Safety training is mandatory here.","exampleCN":"这里的安全培训是强制性的。"}],"latinEntries":[{"word":"mandare","structure":"mandare, mandavi, mandatum (verb, first conjugation)","meaning":"to order, entrust, commit","meaningCN":"命令；委托；交托"},{"word":"demandare","structure":"demandare, demandavi, demandatum (verb, first conjugation)","meaning":"to entrust, charge, order","meaningCN":"委托；责成；命令"},{"word":"mandatum","structure":"mandatum, mandati (n., second declension)","meaning":"a charge, an order","meaningCN":"委托；命令"}],"derivatives":[{"word":"demanding","pos":"adj.","zh":"苛求的；耗费精力的"},{"word":"demand-side","pos":"adj.","zh":"需求面的"},{"word":"on-demand","pos":"adj.","zh":"按需提供的"},{"word":"undemanding","pos":"adj.","zh":"要求不高的"}]}},{"word":"supply and demand","ipa_uk":"/səˈplaɪ ənd dɪˈmɑːnd/","ipa_us":"/səˈplaɪ ænd dɪˈmænd/","definition_zh":"供需；供给与需求（共同决定价格的两种市场力量）","definition_en":"the relationship between how much of a good is offered and how much buyers want, which together set its price","core_image":"一架天平，一端放货筐，另一端放伸出来想买的手","scene":"课堂上老师把两条曲线画在黑板上，让学生看它们相交的位置。The lecture used a simple chart to show how supply and demand set the price of wheat.","sceneCN":"课堂上老师把两条曲线画在黑板上，让学生看它们相交的位置；句中的 supply and demand 指「共同决定价格的供需两种力量」（第 1 个义项：成对作用、决定价格的市场力量）。图中可辨识物件：黑板上的两条曲线、交点、粉笔、麦穗图样。","pos":[{"tag":"n.","zh":"供需关系；供给与需求"},{"tag":"adj.","zh":"供需的（作定语，常写作 supply-and-demand）"}],"collocations":[{"phrase":"the law of supply and demand","zh":"供需法则"},{"phrase":"supply and demand balance","zh":"供需平衡"},{"phrase":"supply and demand forces","zh":"供需两股力量"},{"phrase":"a shift in supply and demand","zh":"供需的变动"},{"phrase":"supply and demand curve","zh":"供需曲线"},{"phrase":"supply-side and demand-side","zh":"供给面与需求面"}],"forms":[{"label":"定语连字符形式","form":"supply-and-demand"},{"label":"语序变体","form":"demand and supply"},{"label":"口语简称","form":"supply-demand"}],"derivatives":[{"word":"supplier","pos":"n.","zh":"供应商"},{"word":"demanding","pos":"adj.","zh":"苛求的；费力的"},{"word":"supply-side","pos":"adj.","zh":"供给面的"},{"word":"demand-side","pos":"adj.","zh":"需求面的"}],"senses":[{"no":"01","title":"The paired forces that set price","titleCN":"共同决定价格的一对力量","definition":"the two market forces whose interaction fixes the price of a good","definitionCN":"相互作用从而定出货物价格的两股市场力量","example":"The lecture used a simple chart to show how supply and demand set the price of wheat.","exampleCN":"这堂课用一张简图展示供需如何决定小麦价格。","why":"Supply and demand are simply the two sides of a market, and naming them together names the mechanism that moves price.","whyCN":"供给与需求本就是市场的两侧，把它们并称就是给推动价格的机制命名。"},{"no":"02","title":"The balance between availability and desire","titleCN":"可供量与想要程度之间的平衡","definition":"the balance, or imbalance, between what is available and what people want","definitionCN":"可供之物与人们想要之物之间的均衡或不均衡","example":"In a small town, supply and demand decide which shops survive.","exampleCN":"在小镇上，供需决定哪些店铺能活下来。","why":"The phrase describes a relation rather than a thing, so it can be used wherever availability meets wanting.","whyCN":"这个短语描述的是关系而非实体，因此凡「可供」遇上「想要」之处都能用。"},{"no":"03","title":"The textbook two-curve model","titleCN":"教科书里的两条曲线模型","definition":"the standard diagram in which a supply curve and a demand curve cross","definitionCN":"供给曲线与需求曲线相交的标准图示","example":"The chapter introduces supply and demand before any policy question.","exampleCN":"这一章先讲供需，再谈任何政策问题。","why":"Economics turned the everyday relation into a picture with two lines, and the picture took the name of the relation.","whyCN":"经济学把日常关系画成两条线，这幅图便沿用了这一关系的名称。"},{"no":"04","title":"An everyday explanation of scarcity","titleCN":"解释稀缺的日常说法","definition":"a plain way of saying that things are scarce because many want them and few have them","definitionCN":"一种朴素说法：东西少而想要的人多，所以稀缺","example":"When tickets sell out, promoters shrug and say it is supply and demand.","exampleCN":"票卖光时，主办方一摊手，说这就是供需。","why":"Outside economics the phrase works as a ready-made answer, a way of saying the outcome was nobody's decision.","whyCN":"在经济学之外，这个短语是一句现成答案，用来表示结果并非谁的决定。"},{"no":"05","title":"The principle invoked in price debates","titleCN":"价格争论中被援引的原理","definition":"the principle cited when arguing about rents, fares or wages","definitionCN":"讨论房租、票价或工资时被援引的原理","example":"Critics blame supply and demand for volatile rents in the city.","exampleCN":"批评者把城市租金的剧烈波动归因于供需。","why":"Once the pair is treated as a law, it can be blamed or defended in public argument.","whyCN":"一旦这对概念被当成法则，它就能在公共争论中被指责或辩护。"},{"no":"06","title":"The attributive form naming an analysis","titleCN":"作定语，指一种分析方法","definition":"used before a noun to name an analysis or a policy built on the two forces","definitionCN":"放在名词前，指基于这两股力量的分析或政策","example":"A supply-and-demand analysis predicts a fall in the price of used cars.","exampleCN":"一份供需分析预测二手车价格将下跌。","why":"The hyphenated form turns the phrase into a label for a method rather than the forces themselves.","whyCN":"加连字符的形式把这个短语变成一种方法的标签，而不再指两股力量本身。"},{"no":"07","title":"The stated law","titleCN":"被表述为法则的供需","definition":"the doctrine that price moves until the amount offered matches the amount wanted","definitionCN":"价格会一直变动，直到供给量与需求量相符的主张","example":"The law of supply and demand is often repeated as a slogan.","exampleCN":"供需法则常被当作口号反复引用。","why":"Naming it a law claims regularity: the same pairing is said to work in every market.","whyCN":"称之为法则就是宣称其有规律性：同一对力量据说到处都起作用。"},{"no":"08","title":"Supply-side versus demand-side framing","titleCN":"供给面与需求面的分法","definition":"the split used in policy talk, where one side is blamed or boosted","definitionCN":"政策讨论中的分法，用来指责或扶持其中一侧","example":"The debate split into supply-side and demand-side remedies.","exampleCN":"争论分成供给面与需求面两类对策。","why":"The pair can be pulled apart rhetorically, and each half then names a programme of action.","whyCN":"这对概念在修辞上可以被拆开，各自指一套行动方案。"}],"etymology":{"intro":{"en":"Supply and demand is an English phrase joining two nouns of Latin origin. It has no Latin source of its own; its history belongs to political economy.","cn":"supply and demand 是把两个拉丁来源的英语名词用 and 连起来的短语，本身没有独立的拉丁词源，其历史属于政治经济学。"},"items":[{"era":"ENGLISH NOUNS","en":"Supply comes from Latin supplere 'to fill up', demand from Latin demandare 'to entrust, charge'; both were ordinary English nouns long before they were paired.","cn":"supply 来自拉丁 supplere「填满」，demand 来自拉丁 demandare「委托、责成」；两者在配对之前早已是普通英语名词。"},{"era":"EIGHTEENTH CENTURY","en":"Adam Smith wrote of effectual demand, the demand of those able to pay, rather than of a paired phrase.","cn":"亚当·斯密写的是「有效需求」，即付得起钱者的需求，尚未使用成对的短语。"},{"era":"EARLY NINETEENTH CENTURY","en":"British political economists began to speak of supply and demand together as the mechanism that adjusts price.","cn":"英国政治经济学家开始把供给与需求并称，视为调整价格的机制。"},{"era":"CLASSICAL FORMULATION","en":"Nineteenth-century writers drew supply and demand curves, and Alfred Marshall's Principles of Economics of 1890 made the crossing diagram standard.","cn":"十九世纪作者画出供给与需求曲线，1890 年马歇尔的《经济学原理》使相交图成为标准。"},{"era":"TEXTBOOK STANDARD","en":"In the twentieth century the phrase became the first lesson of every economics course and then a general explanation of scarcity.","cn":"到二十世纪，这个短语成了每门经济学课的第一课，随后又成了对稀缺的通用解释。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: no exact first use of the paired wording is agreed, and the earlier separate term effectual demand long predates it.","cn":"来源不确定：这一成对说法没有公认的最早用例，更早的「有效需求」一词远在它之前。"}]},"similar":{"note":{"en":"Group one holds neighbouring market terms built on the same nouns; group two holds near expressions for the same idea.","cn":"第一组是由同一批名词构成的相邻市场术语；第二组是表达同一观念的其他说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"supply chain","ipa":"/səˈplaɪ tʃeɪn/","tag":"logistics, not price","definition":"The sequence of firms that move goods from raw material to buyer; it describes delivery, not the price-setting pair.","definitionCN":"把货物从原料送到买家的企业序列；描述交付，不是定价的一对力量。"},{"word":"demand curve","ipa":"/dɪˈmɑːnd kɜːv/","tag":"one half only","definition":"The line showing how much buyers want at each price; alone it is only half of the pairing.","definitionCN":"表示各价格下买方想要多少的曲线；单看只是这对力量的一半。"},{"word":"market equilibrium","ipa":"/ˈmɑːkɪt ˌiːkwɪˈlɪbriəm/","tag":"outcome, not forces","definition":"The point the two forces produce, where price and quantity settle; it names the result rather than the mechanism.","definitionCN":"两股力量产生的结果，价格与数量在此稳定；指结果而非机制。"},{"word":"supply-side","ipa":"/səˈplaɪ saɪd/","tag":"one half as policy","definition":"The half of the pairing treated as a lever, as in supply-side tax policy.","definitionCN":"被当作杠杆的那一半，如供给面税收政策。"}]},{"heading":"NEAR MEANING","entries":[{"word":"market forces","ipa":"/ˈmɑːkɪt fɔːsɪz/","tag":"broader label","definition":"The general pressures of buying and selling; it includes supply and demand but also competition and expectations.","definitionCN":"买卖产生的总体压力；包括供需，也包括竞争与预期。"},{"word":"price mechanism","ipa":"/praɪs ˈmekənɪzəm/","tag":"how price signals","definition":"The process by which price transmits information between buyers and sellers; it focuses on the signal, not the two quantities.","definitionCN":"价格在买卖双方之间传递信息的过程；侧重信号而非两个数量。"},{"word":"equilibrium","ipa":"/ˌiːkwɪˈlɪbriəm/","tag":"state reached","definition":"The settled state in which the two sides match; it is the resting point of supply and demand.","definitionCN":"双方相符后的稳定状态；是供需的静止点。"},{"word":"shortage and surplus","ipa":"/ˈʃɔːtɪdʒ ənd ˈsɜːpləs/","tag":"imbalances","definition":"The two ways the pairing can fail to match, too little or too much; they describe deviation, not the norm.","definitionCN":"这对力量失衡的两种情形，太少或太多；描述偏离而非常态。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: two real nouns, their Latin sources and the standard phrases they form.","cn":"正常联想：两个真实名词、它们的拉丁来源，以及由它们构成的固定说法。"},"normal":[{"en":"Two Latin-fed nouns joined by and: one fills a gap, the other presses a claim.","cn":"两个源自拉丁语的名词用 and 连起来：一个填补空缺，一个施加索取。"},{"en":"The usual fixed phrases are the law of supply and demand and a shift in supply and demand.","cn":"常见固定说法是供需法则与供需变动。"},{"en":"The pair splits into supply-side and demand-side whenever policy is debated.","cn":"讨论政策时，这一对会拆成供给面与需求面。"},{"en":"Its two halves keep their own families: supplier, supplies, demanding, demand-side.","cn":"两半各自保留词族：supplier、supplies、demanding、demand-side。"},{"en":"Economics diagrams mark the meeting of the two with a single crossing point.","cn":"经济学图示用一个交点标出两者的相遇。"}],"abstract":[{"en":"Picture two hands reaching for the same object from opposite sides of a table.","cn":"想象两只手从桌子两侧伸向同一件东西。"},{"en":"Picture a see-saw that only levels when the load on each side is equal.","cn":"想象一架跷跷板，只有两边负重相等时才放平。"},{"en":"Picture a crowd where every raised hand is answered by one item lifted from a crate.","cn":"想象一群人，每只举起的手都对应从箱子里取出的一件东西。"}]},"examples":[{"en":"Rising supply and demand for lithium reshaped the whole battery industry.","cn":"锂的供需上升重塑了整个电池产业。"},{"en":"The report treats supply and demand as a single mechanism, not two separate facts.","cn":"该报告把供需视为一个机制，而非两个独立事实。"},{"en":"Students often confuse supply and demand with the equilibrium they produce.","cn":"学生常把供需与它们产生的均衡混为一谈。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「supply（供应）+ and + demand（需求）」——一只手递货，一只手要货，两手相遇就定出价格","word":"supply and demand"},"root":"由英语 supply 与 demand 两个名词经 and 连接而成；前者源自拉丁 supplere，后者源自拉丁 demandare，短语本身无独立拉丁词源。","sensesIntro":{"en":"Eight senses follow one pairing: two forces, their balance, the textbook diagram, the everyday excuse, the debating principle, the attributive label, the stated law and the split into two policy camps.","cn":"八个义项围绕一对概念展开：两股力量、二者的平衡、教科书图示、日常说法、争论中的原理、定语标签、被表述的法则，以及拆成两个政策阵营。"},"semanticMap":{"core":{"en":"CORE IMAGE: a level beam with goods on one side and outstretched buying hands on the other.","cn":"核心意象：一架水平的横梁，一边是货物，另一边是伸出的买货之手。"},"chain":["TWO FORCES","AVAILABILITY","WANTING","CROSSING POINT","PRICE SET","EVERYDAY EXPLANATION"],"branches":[{"senses":"01 · 03","en":"MODEL: the two forces are studied as a pair of curves that cross.","cn":"模型：两股力量被研究为一对相交的曲线。"},{"senses":"02 · 04","en":"BALANCE: the same pairing explains a small town's shops and a sold-out concert.","cn":"平衡：同一对概念既能解释小镇店铺，也能解释售罄的演出。"},{"senses":"05 · 08","en":"DEBATE: the pairing becomes something to blame and something to split into camps.","cn":"争论：这对概念成了可指责的对象，也可拆成两个阵营。"},{"senses":"06","en":"METHOD: hyphenated, it names an analysis rather than the forces.","cn":"方法：加上连字符后，它指一种分析而非两股力量。"},{"senses":"07","en":"LAW: stated as a rule, the pairing claims to work in every market.","cn":"法则：被表述为规则时，这对概念声称处处有效。"}]},"affixes":{"intro":{"en":"The phrase is built from two complete English nouns, each with its own Latin root, so it is read as two families joined by and.","cn":"这个短语由两个完整的英语名词构成，各自带有拉丁词根，因此要按两个词族用 and 相连来读。"},"latinIntro":{"en":"Supplere supplies the first half and demandare the second; neither prefix belongs to the phrase as a whole.","cn":"前半来自 supplere，后半来自 demandare；两个前缀都不属于整个短语。"},"items":[{"word":"supply","structure":"sub- + plere (Latin)","meaning":"to fill up, provide","meaningCN":"填满；供应","example":"The first half names what is offered.","exampleCN":"前半指被提供的东西。"},{"word":"demand","structure":"de- + mandare (Latin)","meaning":"to claim, require","meaningCN":"索取；要求","example":"The second half names what is wanted.","exampleCN":"后半指被想要的东西。"},{"word":"supplier","structure":"supply + -er","meaning":"one who supplies","meaningCN":"供应商","example":"The supplier doubled its output.","exampleCN":"供应商把产量提高了一倍。"},{"word":"demanding","structure":"demand + -ing","meaning":"making great claims","meaningCN":"苛求的","example":"A demanding market rewards precision.","exampleCN":"苛刻的市场奖励精确。"},{"word":"supply-side","structure":"supply + side","meaning":"the offering half as policy","meaningCN":"作为政策的供给面","example":"Supply-side measures aim at producers.","exampleCN":"供给面措施针对生产者。"},{"word":"demand-side","structure":"demand + side","meaning":"the wanting half as policy","meaningCN":"作为政策的需求面","example":"Demand-side measures aim at households.","exampleCN":"需求面措施针对家庭。"},{"word":"supply curve","structure":"supply + curve","meaning":"the line of quantities offered","meaningCN":"表示供给量的曲线","example":"The supply curve slopes upward.","exampleCN":"供给曲线向上倾斜。"},{"word":"demand curve","structure":"demand + curve","meaning":"the line of quantities wanted","meaningCN":"表示需求量的曲线","example":"The demand curve slopes downward.","exampleCN":"需求曲线向下倾斜。"}],"latinEntries":[{"word":"supplere","structure":"supplere, supplevi, suppletum (verb, second conjugation)","meaning":"to fill up, complete","meaningCN":"填满；补齐"},{"word":"demandare","structure":"demandare, demandavi, demandatum (verb, first conjugation)","meaning":"to entrust, charge","meaningCN":"委托；责成"},{"word":"mandare","structure":"mandare, mandavi, mandatum (verb, first conjugation)","meaning":"to order, entrust","meaningCN":"命令；委托"}],"derivatives":[{"word":"supplier","pos":"n.","zh":"供应商"},{"word":"supplies","pos":"n.","zh":"补给品"},{"word":"demanding","pos":"adj.","zh":"苛求的"},{"word":"supply-side","pos":"adj.","zh":"供给面的"},{"word":"demand-side","pos":"adj.","zh":"需求面的"}]}},{"word":"equilibrium","ipa_uk":"/ˌiːkwɪˈlɪbriəm/","ipa_us":"/ˌiːkwɪˈlɪbriəm/","definition_zh":"平衡；均衡；（物理）平衡态；（经济）市场均衡；（情绪）平静","definition_en":"a state in which opposing forces or influences are balanced, so nothing tends to change","core_image":"一架天平两端重量相等，指针停在中央刻度上","scene":"走钢丝的人在风中调整手里的长杆，让身体停在正中不再倾斜。The tightrope walker adjusted the pole until the body reached equilibrium above the wire.","sceneCN":"走钢丝的人在风中调整长杆，让身体停在正中不再倾斜；句中的 equilibrium 指「相反的力量相抵、系统不再偏移的状态」（第 1 个义项：物理意义上的受力平衡）。图中可辨识物件：钢丝、长杆、稳定姿态、远处的风旗。","pos":[{"tag":"n.","zh":"平衡；均衡；平静（复数 equilibria）"},{"tag":"adj.","zh":"均衡的（作定语，如 equilibrium state）"}],"collocations":[{"phrase":"in equilibrium","zh":"处于平衡状态"},{"phrase":"thermal equilibrium","zh":"热平衡"},{"phrase":"market equilibrium","zh":"市场均衡"},{"phrase":"chemical equilibrium","zh":"化学平衡"},{"phrase":"equilibrium point","zh":"平衡点"},{"phrase":"stable equilibrium","zh":"稳定平衡"}],"forms":[{"label":"复数（主要形式）","form":"equilibria"},{"label":"复数（较少用）","form":"equilibriums"},{"label":"动词（使平衡）","form":"equilibrate"},{"label":"名词（平衡过程）","form":"equilibration"}],"derivatives":[{"word":"equilibrate","pos":"v.","zh":"（使）平衡"},{"word":"equilibration","pos":"n.","zh":"平衡过程"},{"word":"disequilibrium","pos":"n.","zh":"失衡"},{"word":"nonequilibrium","pos":"n./adj.","zh":"非平衡（的）"}],"senses":[{"no":"01","title":"Balance of physical forces","titleCN":"物理受力的平衡","definition":"the state in which the forces acting on a body cancel out","definitionCN":"作用在一个物体上的力相互抵消的状态","example":"The tightrope walker adjusted the pole until the body reached equilibrium above the wire.","exampleCN":"走钢丝的人调整长杆，直到身体在钢丝上方达到平衡。","why":"The Latin word joins 'level' and 'scales', so the first sense is simply a pair of pans that no longer tips.","whyCN":"拉丁词把「平」与「天平」合在一起，因此第一义就是一架不再倾斜的天平。"},{"no":"02","title":"Chemical balance of two reactions","titleCN":"化学反应的双向平衡","definition":"the state in which a forward reaction and its reverse proceed at equal rates","definitionCN":"正反应与逆反应速率相等的状态","example":"The mixture reaches equilibrium when both reactions run at the same rate.","exampleCN":"当两个反应以相同速率进行时，混合物达到平衡。","why":"Two opposing processes cancelling is the same picture as two weights cancelling, applied to rates instead of forces.","whyCN":"两个相反过程相互抵消，与两个重量相抵是同一幅图，只是把力换成了速率。"},{"no":"03","title":"Market balance of supply and demand","titleCN":"市场供需的均衡","definition":"the price and quantity at which the amount offered equals the amount wanted","definitionCN":"供给量与需求量相等时的价格与数量","example":"The market found equilibrium at a price neither side had expected.","exampleCN":"市场在一个双方都没预料到的价位上达到均衡。","why":"Economics borrowed the word because a market that stops moving looks like a beam that has levelled.","whyCN":"经济学借用这个词，因为停止波动的市场就像一根已经放平的横梁。"},{"no":"04","title":"Emotional composure","titleCN":"情绪的平稳自持","definition":"a calm inner state in which opposing feelings do not pull a person about","definitionCN":"相反情绪不再把人拉来拉去的平静内心状态","example":"Years of practice gave her an equilibrium that no insult could shake.","exampleCN":"多年历练给了她一种任何侮辱都撼不动的平静。","why":"The metaphor moves inward: the opposing weights become feelings, and the level beam becomes a steady temper.","whyCN":"这个比喻转向内心：相抵的重量变成情绪，水平的横梁变成稳定的性情。"},{"no":"05","title":"Biological and ecological balance","titleCN":"生物体与生态的平衡","definition":"the steady internal or ecological state that a living system maintains","definitionCN":"生命系统维持的内部或生态稳定状态","example":"Reef fish keep a rough equilibrium with the corals they feed on.","exampleCN":"礁鱼与它们取食的珊瑚之间维持着大致平衡。","why":"A living system held steady by opposing processes is the same idea as a body held steady by opposing forces.","whyCN":"生命系统靠相反过程维持稳定，与物体靠相反的力维持稳定是同一想法。"},{"no":"06","title":"A steady state with no tendency to change","titleCN":"不再有变化趋势的稳定状态","definition":"a general condition in which nothing pushes the system away from where it is","definitionCN":"没有任何因素把系统推离原位的总体状态","example":"After the shock, the system slowly returned to equilibrium.","exampleCN":"冲击过后，系统慢慢回到平衡。","why":"Stripped of physics and markets, the core is simply rest, a state that no push disturbs.","whyCN":"去掉物理与市场的具体内容，核心就是静止——一种没有推力能打扰的状态。"},{"no":"07","title":"A strategy nobody gains by changing","titleCN":"无人因单独改变而获益的策略均衡","definition":"in game theory, a profile of choices in which no player gains by switching alone","definitionCN":"博弈论中任何一方单独改变选择都无利可图的局面","example":"Neither firm could improve its payoff, so the pair settled into equilibrium.","exampleCN":"两家公司都无法提高收益，于是这一对选择进入均衡。","why":"The word is used for a balance of incentives rather than of forces, yet the shape is the same.","whyCN":"这里平衡的是激励而非力，但形状仍然相同。"},{"no":"08","title":"Thermal equilibrium","titleCN":"热平衡","definition":"the condition in which two bodies in contact exchange no net heat","definitionCN":"两个接触物体之间没有净热量交换的状态","example":"The two blocks reached thermal equilibrium at the same temperature.","exampleCN":"两块物体在同一温度下达到热平衡。","why":"Heat flow stops exactly when the two sides level off, which is the scales image made literal.","whyCN":"热流恰在两侧齐平之时停止，这正是天平意象的字面版本。"}],"etymology":{"intro":{"en":"Equilibrium is Latin aequilibrium 'level balance', from aequus 'level, equal' and libra 'balance, scales'. English took it in the seventeenth century.","cn":"equilibrium 来自拉丁 aequilibrium「水平的平衡」，由 aequus「平的、相等的」与 libra「天平」构成，十七世纪进入英语。"},"items":[{"era":"LATIN AEQUUS","en":"Aequus meant 'level, even, equal' and also 'calm, fair'. It gives equal, equity, equator and equable.","cn":"aequus 意为「平的、齐的、相等的」，也表示「平静、公正」；它衍生 equal、equity、equator 与 equable。"},{"era":"LATIN LIBRA","en":"Libra meant 'balance, scales' and also a unit of weight, roughly a pound; the zodiac sign took the same name.","cn":"libra 意为「天平、秤」，也指一种重量单位，约合一磅；黄道十二宫的「天秤座」沿用此名。"},{"era":"LATIN AEQUILIBRIUM","en":"Aequus plus libra produced aequilibrium, 'a level balance', used for physical balance and later for balance of mind.","cn":"aequus 加 libra 构成 aequilibrium「水平的平衡」，先用于物理平衡，后也用于心境。"},{"era":"SEVENTEENTH CENTURY","en":"English adopted the word in the 1600s, at first for physical and mechanical balance.","cn":"英语在十七世纪吸收这个词，最初用于物理与力学的平衡。"},{"era":"ECONOMIC SENSE","en":"Nineteenth-century economics applied it to the price at which supply and demand meet, and the term became central to the discipline.","cn":"十九世纪经济学把它用于供需相遇的价格，这个词随后成为该学科的核心术语。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: whether English took the word directly from Latin or through French equilibre is not settled, and the earliest citation date is approximate.","cn":"来源不确定：英语是直接从拉丁语借入，还是经法语 equilibre 传入，尚无定论；最早书证年代也只是约数。"}]},"similar":{"note":{"en":"Group one holds words from the same Latin stock that are easily confused; group two holds near terms for balance.","cn":"第一组是同出拉丁词源、容易混淆的词；第二组是表示平衡的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"equable","ipa":"/ˈekwəbl/","tag":"same first element","definition":"Built on aequus alone: a steady, unvarying temper or climate, with no second element meaning balance.","definitionCN":"只由 aequus 构成：指平稳不变的性情或气候，并没有表示「天平」的第二部分。"},{"word":"equanimity","ipa":"/ˌekwəˈnɪməti/","tag":"different second element","definition":"From aequus plus animus 'mind': calmness of mind, a cousin in meaning but not built on the scales image.","definitionCN":"由 aequus 加 animus「心」构成：心平气和，意思相近，但并不建立在天平意象上。"},{"word":"equity","ipa":"/ˈekwəti/","tag":"same root, different field","definition":"From aequitas, 'evenness, fairness': justice or ownership value, not a physical balance.","definitionCN":"来自 aequitas「均平、公正」：指公平或产权价值，不是物理平衡。"},{"word":"equipoise","ipa":"/ˈekwɪpɔɪz/","tag":"English coinage","definition":"An English formation from equi- 'equal' and poise 'weight': a balanced state, close in meaning but not from the Latin noun.","definitionCN":"英语自造词，由 equi-「相等」与 poise「重量」构成：平衡状态，意思接近但并非来自那个拉丁名词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"balance","ipa":"/ˈbæləns/","tag":"plain everyday word","definition":"The ordinary word for an even distribution of weight or power; it is the everyday counterpart of equilibrium.","definitionCN":"表示重量或力量均匀分布的日常词，是 equilibrium 的日常对应词。"},{"word":"stability","ipa":"/stəˈbɪləti/","tag":"resistance to change","definition":"The tendency to stay in place when pushed; equilibrium is the state, stability is how well it holds.","definitionCN":"受推时保持原位的倾向；equilibrium 是状态，stability 是这种状态有多稳。"},{"word":"homeostasis","ipa":"/ˌhəʊmiəˈsteɪsɪs/","tag":"biological term","definition":"The specific biological term for a body holding its internal conditions steady; equilibrium is the wider word.","definitionCN":"生物体维持内部条件稳定的专门术语；equilibrium 范围更广。"},{"word":"stasis","ipa":"/ˈsteɪsɪs/","tag":"no movement","definition":"A state of standstill, often used of fluids or history; it names stillness rather than balanced forces.","definitionCN":"停滞状态，常用于流体或历史；指静止而非力量相抵。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two Latin pieces, the fixed phrases and the real relatives.","cn":"正常联想：两个拉丁成分、固定搭配与真实同族词。"},"normal":[{"en":"Aequus 'level' plus libra 'scales': a pair of pans that stops tipping.","cn":"aequus「平」加 libra「天平」：一对不再倾斜的秤盘。"},{"en":"The family runs equilibrium, equilibrate, equilibration, disequilibrium and nonequilibrium.","cn":"同族词有 equilibrium、equilibrate、equilibration、disequilibrium 与 nonequilibrium。"},{"en":"Fixed phrases: in equilibrium, thermal equilibrium, market equilibrium, stable equilibrium.","cn":"固定说法：处于平衡、热平衡、市场均衡、稳定平衡。"},{"en":"The same first element appears in equal, equity, equator and equable.","cn":"同一前半出现在 equal、equity、equator 与 equable 中。"},{"en":"Aequus also meant calm, which is why the word can describe a steady temper.","cn":"aequus 也含「平静」之意，所以这个词能形容稳定的性情。"}],"abstract":[{"en":"Picture a beam that stops moving the moment its two pans carry the same weight.","cn":"想象一根横梁，两端负重相等的那一刻就停止摆动。"},{"en":"Picture a room where heat stops crossing the wall because both sides are equally warm.","cn":"想象一间屋子，两侧一样暖时热量就不再穿墙。"},{"en":"Picture a mind pulled from both sides until the pull cancels and it simply stays.","cn":"想象一颗心被两侧拉扯，直到拉力相抵，它就原地不动。"}]},"examples":[{"en":"The reaction mixture took twenty minutes to reach equilibrium.","cn":"反应混合物用了二十分钟达到平衡。"},{"en":"Higher tariffs pushed the market away from its old equilibrium.","cn":"更高的关税把市场推离了原来的均衡。"},{"en":"She listened to the whole complaint with an unshaken equilibrium.","cn":"她以毫不动摇的平静听完了整段抱怨。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「equi（相等）+ librium（天平）——两边相等，秤就平了」","word":"equilibrium"},"root":"拉丁 aequilibrium「水平的平衡」= aequus「平的、相等的」+ libra「天平、秤」。","sensesIntro":{"en":"Eight senses follow one image, a beam that levels: forces, reaction rates, market price, temper, living systems, plain rest, incentives and heat flow.","cn":"八个义项围绕同一幅图——一根放平的横梁：力、反应速率、市场价格、性情、生命系统、单纯的静止、激励与热流。"},"semanticMap":{"core":{"en":"CORE IMAGE: scales whose pointer rests exactly at the middle mark.","cn":"核心意象：一架指针正停在中央刻度的天平。"},"chain":["EQUAL WEIGHT","NO NET CHANGE","TWO-SIDED MATCH","CALM MIND","STEADY SYSTEM","SETTLED PRICE"],"branches":[{"senses":"01 · 08","en":"WEIGHT: mechanical forces and heat flow both stop when the two sides level.","cn":"重量：力学上的力与热流，都在两侧齐平时停止。"},{"senses":"02 · 05","en":"NATURAL PROCESSES: reaction rates match, and living systems hold their inner conditions steady.","cn":"自然过程：反应速率相符，生命系统则维持内部条件稳定。"},{"senses":"03 · 06","en":"SETTLED MARKET AND MERE REST: price stops moving, and any system stops being pushed.","cn":"市场与静止：价格不再变动，任何系统也不再被推动。"},{"senses":"04","en":"MIND: composure is a balance of feelings that nobody can see.","cn":"内心：平静是一种看不见的情绪平衡。"},{"senses":"07","en":"INCENTIVES: no player gains by moving alone, so the choices stay put.","cn":"激励：无人因单独改变而获益，选择因此停在原处。"}]},"affixes":{"intro":{"en":"Equilibrium is two Latin words welded together, and each half still builds English words on its own.","cn":"equilibrium 由两个拉丁词焊接而成，两半各自仍能构成英语词。"},"latinIntro":{"en":"Latin aequus gives equal, equity, equator and equable; libra gives Libra and the sense of weighing.","cn":"拉丁 aequus 衍生 equal、equity、equator 与 equable；libra 衍生 Libra 及「称量」之义。"},"items":[{"word":"aequi-","structure":"Latin combining form from aequus","meaning":"equal, level","meaningCN":"相等的；平的","example":"The first half of the word carries the idea of evenness.","exampleCN":"这个词的前半带着「均平」的意思。"},{"word":"libra","structure":"Latin noun, first declension","meaning":"balance, scales; a unit of weight","meaningCN":"天平；秤；重量单位","example":"The second half supplies the picture of weighing.","exampleCN":"后半提供「称量」的意象。"},{"word":"equilibrium","structure":"aequus + libra","meaning":"a level balance","meaningCN":"水平的平衡","example":"The beam settled into equilibrium.","exampleCN":"横梁进入平衡。"},{"word":"equilibrate","structure":"equilibrium + -ate (verb)","meaning":"to bring into balance","meaningCN":"使平衡","example":"The two chambers equilibrated overnight.","exampleCN":"两个腔室一夜之间达到平衡。"},{"word":"equilibration","structure":"equilibrate + -ion (process)","meaning":"the process of balancing","meaningCN":"平衡过程","example":"Equilibration took several hours.","exampleCN":"平衡过程花了数小时。"},{"word":"disequilibrium","structure":"dis- + equilibrium","meaning":"a loss of balance","meaningCN":"失衡","example":"The shock caused a brief disequilibrium.","exampleCN":"冲击造成了短暂的失衡。"},{"word":"nonequilibrium","structure":"non- + equilibrium","meaning":"a state away from balance","meaningCN":"非平衡状态","example":"Nonequilibrium systems need constant energy.","exampleCN":"非平衡系统需要持续供能。"},{"word":"equable","structure":"aequus + -able","meaning":"steady, even","meaningCN":"平稳的；均和的","example":"He kept an equable temper all day.","exampleCN":"他一整天性情平和。"},{"word":"equity","structure":"aequitas, from aequus","meaning":"fairness; ownership value","meaningCN":"公平；产权价值","example":"Pay equity was the central demand.","exampleCN":"薪酬公平是核心诉求。"}],"latinEntries":[{"word":"aequilibrium","structure":"aequilibrium, aequilibri (n., second declension)","meaning":"a level balance","meaningCN":"水平的平衡"},{"word":"aequus","structure":"aequus, aequa, aequum (adj., first and second declension)","meaning":"level, equal, calm","meaningCN":"平的；相等的；平静的"},{"word":"libra","structure":"libra, librae (f., first declension)","meaning":"balance, scales; a pound","meaningCN":"天平；秤；一磅"}],"derivatives":[{"word":"equilibrate","pos":"v.","zh":"（使）平衡"},{"word":"equilibration","pos":"n.","zh":"平衡过程"},{"word":"disequilibrium","pos":"n.","zh":"失衡"},{"word":"nonequilibrium","pos":"n./adj.","zh":"非平衡（的）"}]}},{"word":"equilibrium price","ipa_uk":"/ˌiːkwɪˈlɪbriəm praɪs/","ipa_us":"/ˌiːkwɪˈlɪbriəm praɪs/","definition_zh":"均衡价格；供需数量相等时的市场成交价","definition_en":"the price at which the quantity sellers offer equals the quantity buyers want","core_image":"两条曲线在黑板上相交，交点旁边挂着一个价签","scene":"小麦市场报告用一张图说明价格停在哪一档时，买卖双方报出的数量正好相符。The wheat report used a chart to identify the equilibrium price at which offers and orders matched.","sceneCN":"小麦市场报告用一张图说明价格停在哪一档时买卖数量正好相符；句中的 equilibrium price 指「供需数量相等时的成交价格」（第 1 个义项：使供给量与需求量相等的价格）。图中可辨识物件：相交的两条曲线、交点处的价签、麦穗图标、报告纸页。","pos":[{"tag":"n.","zh":"均衡价格；市场出清价"},{"tag":"adj.","zh":"均衡价格的（作定语，如 equilibrium-price analysis）"}],"collocations":[{"phrase":"reach the equilibrium price","zh":"达到均衡价格"},{"phrase":"above the equilibrium price","zh":"高于均衡价格"},{"phrase":"below the equilibrium price","zh":"低于均衡价格"},{"phrase":"shift the equilibrium price","zh":"改变均衡价格"},{"phrase":"market equilibrium price","zh":"市场均衡价格"},{"phrase":"equilibrium price level","zh":"均衡价格水平"}],"forms":[{"label":"复数","form":"equilibrium prices"},{"label":"定语连字符形式","form":"equilibrium-price"},{"label":"所有格","form":"equilibrium price's"},{"label":"并列短语","form":"equilibrium price and quantity"}],"derivatives":[{"word":"equilibrium pricing","pos":"n.","zh":"均衡定价"},{"word":"price","pos":"n./v.","zh":"价格；定价"},{"word":"pricing","pos":"n.","zh":"定价（行为）"},{"word":"price-setting","pos":"n./adj.","zh":"价格设定（的）"}],"senses":[{"no":"01","title":"The price where the two quantities match","titleCN":"使供给量与需求量相等的那一档价格","definition":"the price at which the amount sellers offer is exactly the amount buyers want","definitionCN":"卖方愿意提供的数量与买方想要的数量恰好相等的价格","example":"The wheat report used a chart to identify the equilibrium price at which offers and orders matched.","exampleCN":"小麦市场报告用一张图找出买卖数量相符的均衡价格。","why":"Equilibrium means a level beam, and price is the value on that beam, so the phrase names the value at which the market stops tipping.","whyCN":"equilibrium 指放平的横梁，price 是横梁上的数值，因此这个短语指市场不再倾斜时的价位。"},{"no":"02","title":"The market-clearing price","titleCN":"市场出清价","definition":"the price at which everything offered is sold and every order is filled","definitionCN":"供给全部售出、订单全部得到满足的价格","example":"At the market-clearing price, no crate of grain is left unsold.","exampleCN":"在市场出清价上，没有一箱粮食剩下卖不掉。","why":"Clearing is what balance looks like in a market: nothing left on one side, nothing waiting on the other.","whyCN":"「出清」就是平衡在市场里的样子：一边不剩货，另一边也不留空等。"},{"no":"03","title":"The vertical coordinate of the crossing","titleCN":"交点在图上的纵坐标","definition":"the price value read off the vertical axis where the two curves cross","definitionCN":"两条曲线相交处，在纵轴上读出的价格数值","example":"Read the equilibrium price from the vertical axis, not the horizontal one.","exampleCN":"均衡价格要从纵轴读出，而不是横轴。","why":"Once the relation is drawn, price becomes one coordinate of a single point, so the phrase names that coordinate.","whyCN":"关系一旦画成图，价格就成了一个点的坐标之一，这个短语便指那个坐标。"},{"no":"04","title":"A benchmark for policy","titleCN":"政策评估的参照价位","definition":"the price used as a comparison when a tax, subsidy or price cap is proposed","definitionCN":"提出税收、补贴或限价时用来作比较的价格","example":"The subsidy moved the traded price away from the equilibrium price.","exampleCN":"补贴使实际成交价偏离了均衡价格。","why":"A benchmark is a level one measures deviation from, and a balance point is the natural zero for such comparisons.","whyCN":"基准就是用来衡量偏离的参照，而平衡点正是这类比较的天然零点。"},{"no":"05","title":"A price that moves after a shock","titleCN":"冲击之后形成的新均衡价","definition":"the new price at which the market settles after supply or demand changes","definitionCN":"供给或需求变化后市场重新稳定下来的价格","example":"A poor harvest produced a much higher equilibrium price.","exampleCN":"歉收造成了高得多的均衡价格。","why":"The beam still finds a level, but with different weights, so the phrase follows the market to its new resting point.","whyCN":"横梁仍会找到水平，只是重量变了，因此这个短语跟着市场走到新的静止点。"},{"no":"06","title":"The price that removes shortage and surplus","titleCN":"消除短缺与过剩的价格","definition":"the price at which neither a shortage nor a surplus remains","definitionCN":"既不留下短缺也不留下过剩的价格","example":"Below the equilibrium price, a shortage appears; above it, a surplus does.","exampleCN":"低于均衡价格会出现短缺，高于它则出现过剩。","why":"Both imbalances are departures from one price, so naming that price names the cure for both.","whyCN":"两种失衡都是对同一价位的偏离，因此指出这个价位就等于指出两者的解药。"},{"no":"07","title":"A theoretical benchmark, not a posted tag","titleCN":"理论基准，而非货架上的标价","definition":"a modelled value used for reasoning, which need not equal any price actually charged","definitionCN":"用于推理的模型数值，未必等于任何实际收取的价格","example":"Textbook models treat the equilibrium price as a benchmark rather than a shop label.","exampleCN":"教科书模型把均衡价格当作基准，而不是商店标签。","why":"A model can solve for a level that no single transaction reaches, so the term marks an ideal rather than a fact.","whyCN":"模型可以解出一个没有任何单笔交易达到的水平，因此这个术语标记的是理想值而非事实。"},{"no":"08","title":"The attributive form in analysis","titleCN":"作定语的分析用语","definition":"used before a noun to name a study or estimate built on the balancing price","definitionCN":"放在名词前，指以这一平衡价格为基础的研究或估算","example":"The equilibrium-price study estimated costs for the coming season.","exampleCN":"这份均衡价格研究估算了下一季的成本。","why":"Hyphenated, the phrase stops naming a price and starts naming the method that computes it.","whyCN":"加连字符后，这个短语不再指某个价格，而指计算它的方法。"}],"etymology":{"intro":{"en":"Equilibrium price joins a Latin-derived balance word with an Old French price word; the combination itself is a nineteenth-century economics term.","cn":"equilibrium price 把拉丁来源的「平衡」词与古法语来源的「价格」词组合起来，这一组合本身是十九世纪经济学的术语。"},"items":[{"era":"LATIN PRETIUM","en":"Pretium meant 'price, value, reward'. Its deeper origin is not established, so any earlier form offered for it is a reconstruction.","cn":"pretium 意为「价格、价值、报酬」。其更深来源未得到证明，凡为其给出的更早形式都属重构。"},{"era":"OLD FRENCH PRIS","en":"Old French pris, 'price, value', carried the word into Middle English in the thirteenth century.","cn":"古法语 pris「价格、价值」在十三世纪把这个词带入中古英语。"},{"era":"ENGLISH PRICE","en":"By the sixteenth century price covered both the money asked and the worth of a thing.","cn":"到十六世纪，price 既指所要的钱，也指一物的价值。"},{"era":"LATIN AEQUILIBRIUM","en":"Aequilibrium, 'level balance', supplied the first half, built on aequus 'level' and libra 'scales'.","cn":"前半来自 aequilibrium「水平的平衡」，由 aequus「平」与 libra「天平」构成。"},{"era":"NINETEENTH-CENTURY ECONOMICS","en":"Classical economists paired the two words for the price that clears a market, and Marshall's 1890 textbook fixed the term.","cn":"古典经济学家把这两个词配在一起，指使市场出清的价格，马歇尔 1890 年的教科书固定了这一术语。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper origin of pretium is unsettled and the first use of the full phrase is dated only approximately.","cn":"来源不确定：pretium 的更深来源尚无定论，整个短语的最早用例也只能给约数。"}]},"similar":{"note":{"en":"Group one holds neighbouring price terms easily mistaken for this one; group two holds near labels for the same balancing value.","cn":"第一组是容易被当成均衡价格的相邻价格术语；第二组是同一平衡价位的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"market price","ipa":"/ˈmɑːkɪt praɪs/","tag":"actual, not modelled","definition":"The price at which goods are actually trading now; it may sit above or below the balancing level.","definitionCN":"货物当下实际成交的价格；可能高于或低于平衡价位。"},{"word":"equilibrium quantity","ipa":"/ˌiːkwɪˈlɪbriəm ˈkwɒntəti/","tag":"the other coordinate","definition":"The amount traded at the balancing level; it is the horizontal partner of this price.","definitionCN":"平衡价位上成交的数量；是这个价格在横轴上的伙伴。"},{"word":"asking price","ipa":"/ˈɑːskɪŋ praɪs/","tag":"seller's posted figure","definition":"What a seller hopes to get, set before any bargaining; it has no balancing role.","definitionCN":"卖方希望得到的价码，在议价前定下；不含平衡作用。"},{"word":"administered price","ipa":"/əˈdɪmɪnɪstəd praɪs/","tag":"set by authority","definition":"A price fixed by a government or a firm rather than by the meeting of offers and orders.","definitionCN":"由政府或企业定下的价格，而非由供需相遇形成。"}]},{"heading":"NEAR MEANING","entries":[{"word":"market-clearing price","ipa":"/ˈmɑːkɪt ˈklɪərɪŋ praɪs/","tag":"same idea, process view","definition":"The same value seen as the price that empties the market; it stresses the clearing rather than the balance.","definitionCN":"同一价位的另一视角：使市场出清的价格；强调出清而非平衡。"},{"word":"clearing price","ipa":"/ˈklɪərɪŋ praɪs/","tag":"short form","definition":"A shortened label used in auctions and exchanges for the price that matches all bids and offers.","definitionCN":"拍卖与交易所使用的简称，指使所有出价与报价相符的价格。"},{"word":"fair price","ipa":"/feə praɪs/","tag":"value judgement","definition":"A price judged morally acceptable; fairness is a judgement, while equilibrium is a modelled outcome.","definitionCN":"被认为道德上可接受的价格；公平是判断，均衡是模型结果。"},{"word":"price point","ipa":"/praɪs pɔɪnt/","tag":"marketing term","definition":"A chosen selling level in a product range; it is a decision, not a computed balance.","definitionCN":"产品系列中选定的售价档位；是决策，不是算出的平衡。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two source words, their fixed phrases and the diagram that shows them.","cn":"正常联想：两个来源词、它们的固定搭配，以及把它们画出来的图示。"},"normal":[{"en":"Balance plus price: the value at which the market stops tipping.","cn":"平衡加价格：市场停止倾斜时的那个数值。"},{"en":"The usual fixed phrases are above the equilibrium price and below the equilibrium price.","cn":"常见固定说法是高于均衡价格与低于均衡价格。"},{"en":"It is the vertical coordinate of the point where the two curves cross.","cn":"它是两条曲线交点处的纵坐标。"},{"en":"Its partner term is equilibrium quantity, the horizontal coordinate.","cn":"与它配对的术语是均衡数量，即横坐标。"},{"en":"Policy talk compares the traded price with this benchmark.","cn":"政策讨论拿实际成交价与这个基准作比较。"}],"abstract":[{"en":"Picture two curves crossing and a price tag hanging exactly at the crossing.","cn":"想象两条曲线相交，一个价签正好挂在交点处。"},{"en":"Picture a beam that stops moving only at one particular weight.","cn":"想象一根横梁，只在某一个特定重量上才停止摆动。"},{"en":"Picture a market where every crate lifted is matched by one order filled.","cn":"想象一个市场，每搬走一箱货，就正好有一张订单被填上。"}]},"examples":[{"en":"A tax on sellers raises the equilibrium price and lowers the quantity traded.","cn":"对卖方征税会提高均衡价格，并减少成交量。"},{"en":"The equilibrium price of the crop fell once two exporting countries reopened their ports.","cn":"两个出口国重开港口后，这种作物的均衡价格下跌。"},{"en":"Analysts disagree about where the equilibrium price really sits.","cn":"分析人士对均衡价格究竟在哪一档意见不一。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「equilibrium（平衡）+ price（价格）」——天平放平那一刻对应的是哪个价","word":"equilibrium price"},"root":"由 equilibrium（拉丁 aequilibrium「水平的平衡」）与 price（拉丁 pretium「价格」，经古法语 pris）组合而成的经济学短语，自身无独立拉丁词源。","sensesIntro":{"en":"Eight senses follow one value: the matching price, the clearing price, the vertical coordinate, a policy benchmark, a new level after a shock, the cure for shortage and surplus, a modelled ideal and finally an attributive method label.","cn":"八个义项围绕同一个数值：相符的价格、出清价、纵坐标、政策基准、冲击后的新水平、消除短缺与过剩的价格、模型中的理想值，最后是作定语的方法标签。"},"semanticMap":{"core":{"en":"CORE IMAGE: two curves meeting, with a price tag pinned at the meeting point.","cn":"核心意象：两条曲线相交，交点上钉着一个价签。"},"chain":["TWO CURVES","CROSSING POINT","MATCHED QUANTITIES","MARKET CLEARING","POLICY BENCHMARK","MOVING LEVEL"],"branches":[{"senses":"01 · 02","en":"MATCH AND CLEAR: the price that equates offers and orders is the same price that empties the market.","cn":"相符与出清：使报价与订单相等的价格，也就是让市场不剩货的价格。"},{"senses":"03","en":"COORDINATE: on a diagram the value shrinks to one number on the vertical axis.","cn":"坐标：在图上这个值缩小为纵轴上的一个数字。"},{"senses":"04 · 07","en":"BENCHMARK: policy measures deviation from it, and models treat it as an ideal rather than a tag.","cn":"基准：政策衡量对它的偏离，模型则把它当作理想值而非标签。"},{"senses":"05 · 06","en":"EQUILIBRATION: after a shock the beam finds a new level, and each level is the cure for shortage and surplus alike.","cn":"再平衡：冲击之后横梁找到新水平，而每个水平都是短缺与过剩的共同解药。"},{"senses":"08","en":"METHOD: hyphenated, the phrase names the analysis rather than the price.","cn":"方法：加连字符后，短语指分析而非价格。"}]},"affixes":{"intro":{"en":"The phrase is two words from two different Latin roots, so it is read as a balance word plus a value word.","cn":"这个短语由两个来自不同拉丁词根的词组成，要按「平衡」加「价值」来读。"},"latinIntro":{"en":"Aequus and libra supply the first word, pretium the second; none of the three belongs to the phrase as a whole.","cn":"aequus 与 libra 构成第一个词，pretium 构成第二个词；三者都不专属于整个短语。"},"items":[{"word":"aequi-","structure":"Latin combining form from aequus","meaning":"equal, level","meaningCN":"相等的；平的","example":"The prefix carries the evenness of the balance.","exampleCN":"这个构词成分带着平衡的均平感。"},{"word":"libra","structure":"Latin noun, first declension","meaning":"balance, scales","meaningCN":"天平；秤","example":"The root supplies the weighing image.","exampleCN":"这个词根提供称量的意象。"},{"word":"pretium","structure":"Latin noun, second declension","meaning":"price, value","meaningCN":"价格；价值","example":"The second word comes from this root.","exampleCN":"第二词来自这个词根。"},{"word":"price","structure":"pretium through Old French pris","meaning":"the money asked for a thing","meaningCN":"一物所要的价钱","example":"The price settled at the crossing.","exampleCN":"价格停在交点处。"},{"word":"equilibrium","structure":"aequus + libra","meaning":"a level balance","meaningCN":"水平的平衡","example":"The market found equilibrium.","exampleCN":"市场达到平衡。"},{"word":"pricing","structure":"price + -ing","meaning":"the activity of setting prices","meaningCN":"定价活动","example":"Pricing decisions follow the model.","exampleCN":"定价决策依据这个模型。"},{"word":"overprice","structure":"over- + price","meaning":"to price too high","meaningCN":"定价过高","example":"Overpriced stock stayed on the shelf.","exampleCN":"定价过高的货留在架上。"},{"word":"underprice","structure":"under- + price","meaning":"to price too low","meaningCN":"定价过低","example":"Underpriced tickets sold out at once.","exampleCN":"定价过低的票立刻售罄。"},{"word":"equilibrium pricing","structure":"equilibrium + pricing","meaning":"setting prices by the balancing level","meaningCN":"按平衡价位定价","example":"The firm adopted equilibrium pricing.","exampleCN":"这家公司采用均衡定价。"}],"latinEntries":[{"word":"pretium","structure":"pretium, preti (n., second declension)","meaning":"price, value, reward","meaningCN":"价格；价值；报酬"},{"word":"aequilibrium","structure":"aequilibrium, aequilibri (n., second declension)","meaning":"a level balance","meaningCN":"水平的平衡"},{"word":"libra","structure":"libra, librae (f., first declension)","meaning":"balance, scales","meaningCN":"天平；秤"}],"derivatives":[{"word":"equilibrium pricing","pos":"n.","zh":"均衡定价"},{"word":"price","pos":"n./v.","zh":"价格；定价"},{"word":"pricing","pos":"n.","zh":"定价"},{"word":"price-setting","pos":"n./adj.","zh":"价格设定（的）"}]}},{"word":"equilibrium quantity","ipa_uk":"/ˌiːkwɪˈlɪbriəm ˈkwɒntəti/","ipa_us":"/ˌiːkwɪˈlɪbriəm ˈkwɑːntəti/","definition_zh":"均衡数量；供需相等时的成交量","definition_en":"the quantity of a good actually traded when the price settles at the balancing level","core_image":"库房门口，进货单与订单上的数字第一次对齐","scene":"拍卖结束后，工作人员把成交数量写进记录本，这个数目与卖方原先报出的数量正好相同。After the auction closed, the clerk recorded the equilibrium quantity, which matched the amount the sellers had offered.","sceneCN":"拍卖结束后，工作人员把成交数量记进本子，这个数目与卖方原报数量正好相同；句中的 equilibrium quantity 指「价格稳定时实际成交的数量」（第 1 个义项：供需相符时的成交量）。图中可辨识物件：拍卖槌、记录本、库存清单、编号牌。","pos":[{"tag":"n.","zh":"均衡数量；均衡成交量"},{"tag":"adj.","zh":"均衡数量的（作定语，如 equilibrium-quantity estimate）"}],"collocations":[{"phrase":"the equilibrium quantity of sth","zh":"某物的均衡数量"},{"phrase":"reach the equilibrium quantity","zh":"达到均衡数量"},{"phrase":"above the equilibrium quantity","zh":"高于均衡数量"},{"phrase":"equilibrium quantity and price","zh":"均衡数量与均衡价格"},{"phrase":"raise the equilibrium quantity","zh":"提高均衡数量"},{"phrase":"equilibrium quantity level","zh":"均衡数量水平"}],"forms":[{"label":"复数","form":"equilibrium quantities"},{"label":"定语连字符形式","form":"equilibrium-quantity"},{"label":"所有格","form":"equilibrium quantity's"},{"label":"并列短语","form":"equilibrium quantity and price"}],"derivatives":[{"word":"quantity","pos":"n.","zh":"数量"},{"word":"quantify","pos":"v.","zh":"量化"},{"word":"quantitative","pos":"adj.","zh":"定量的"},{"word":"equilibrium quantity estimate","pos":"n.","zh":"均衡数量估算"}],"senses":[{"no":"01","title":"The amount traded at the balancing price","titleCN":"平衡价位上实际成交的数量","definition":"the quantity bought and sold once the price has settled at the balancing level","definitionCN":"价格稳定在平衡水平后买入与卖出的数量","example":"After the auction closed, the clerk recorded the equilibrium quantity, which matched the amount the sellers had offered.","exampleCN":"拍卖结束后，工作人员记下均衡数量，这个数目与卖方原报数量相符。","why":"Quantity is the amount side of the market, so the phrase names how much changes hands when the beam is level.","whyCN":"数量是市场中的「量」，因此这个短语指横梁放平时有多少东西易手。"},{"no":"02","title":"The horizontal coordinate of the crossing","titleCN":"交点在图上的横坐标","definition":"the quantity value read off the horizontal axis where the two curves cross","definitionCN":"两条曲线相交处，在横轴上读出的数量数值","example":"The equilibrium quantity is read from the horizontal axis.","exampleCN":"均衡数量从横轴读出。","why":"On a diagram, amount becomes one coordinate of the crossing point, so the phrase names that number.","whyCN":"在图上，数量变成交点的一个坐标，这个短语便指那个数字。"},{"no":"03","title":"The amount that clears the market","titleCN":"使市场出清的数量","definition":"the amount that leaves no unsold stock and no unfilled order","definitionCN":"既不留下卖不掉的存货、也不留下未填的订单的数量","example":"At that level, the equilibrium quantity leaves the warehouse empty.","exampleCN":"在这一水平上，均衡数量正好让仓库清空。","why":"Clearing means the amount offered and the amount wanted are consumed together, which is what this quantity measures.","whyCN":"出清意为供给量与需求量互相抵尽，而这个数量正是衡量它的。"},{"no":"04","title":"The amount compared in policy evaluation","titleCN":"政策评估中被比较的数量","definition":"the traded amount used as a baseline when a tax or subsidy is assessed","definitionCN":"评估税收或补贴时用作基准的成交数量","example":"The tax lowered the equilibrium quantity by a fifth.","exampleCN":"这项税使均衡数量减少了五分之一。","why":"To judge a policy one needs a before-and-after amount, and the balancing amount is the natural before.","whyCN":"评判政策需要前后的数量，而平衡时的数量就是天然的「前」。"},{"no":"05","title":"The new amount after a shift","titleCN":"条件变化后的新均衡数量","definition":"the amount traded once supply or demand has moved and a new balance forms","definitionCN":"供给或需求移动、形成新平衡之后的成交数量","example":"New irrigation raised the equilibrium quantity of rice.","exampleCN":"新的灌溉抬高了稻米的均衡数量。","why":"The balance point moves with the curves, and the phrase follows the traded amount to its new resting place.","whyCN":"平衡点随曲线移动，这个短语跟着成交量走到新的静止处。"},{"no":"06","title":"The partner of the balancing price","titleCN":"与均衡价格配对的数量","definition":"the amount that belongs with the balancing price as the other half of one outcome","definitionCN":"与均衡价格一起构成同一结果另一半的数量","example":"Price and equilibrium quantity are read together from one point.","exampleCN":"价格与均衡数量从同一个点一起读出。","why":"One crossing yields two numbers, and each word names one half of the same event.","whyCN":"一个交点给出两个数字，两个词各指同一事件的一半。"},{"no":"07","title":"A modelled amount, not a sales total","titleCN":"模型中的数量，非实际销量","definition":"a computed value used in reasoning, which need not equal any real sales figure","definitionCN":"用于推理的计算值，未必等于任何真实销量","example":"The model's equilibrium quantity is a device for reasoning, not last year's sales total.","exampleCN":"模型中的均衡数量是推理工具，不是去年的销量总和。","why":"Models solve for an amount no single market need actually reach, so the term marks an ideal.","whyCN":"模型解出的数量未必有哪个真实市场达到，因此这个术语标记理想值。"},{"no":"08","title":"The attributive form in estimates","titleCN":"作定语的估算用语","definition":"used before a noun to name an estimate or forecast based on the balancing amount","definitionCN":"放在名词前，指以这一平衡数量为基础的估算或预测","example":"The equilibrium-quantity estimate guided next year's storage plan.","exampleCN":"均衡数量估算指导了下一年的仓储计划。","why":"Hyphenated, the phrase stops naming a figure and starts naming the calculation behind it.","whyCN":"加连字符后，这个短语不再指某个数字，而指算出它的计算。"}],"etymology":{"intro":{"en":"Equilibrium quantity joins a Latin balance word with a Latin amount word of French passage; the pairing is a nineteenth-century economics term.","cn":"equilibrium quantity 把拉丁「平衡」词与经法语传入的拉丁「数量」词组合起来，这一配对是十九世纪经济学的术语。"},"items":[{"era":"LATIN QUANTUS","en":"Quantus meant 'how much, how great', built on the interrogative stem quam 'how'.","cn":"quantus 意为「多少、多大」，由疑问词干 quam「如何」构成。"},{"era":"LATIN QUANTITAS","en":"Quantitas, 'amount, size', turned the adjective into a noun of measure.","cn":"quantitas「数量、大小」把这个形容词变成表示度量的名词。"},{"era":"OLD FRENCH QUANTITE","en":"Old French quantite carried the noun into Middle English in the fourteenth century.","cn":"古法语 quantite 在十四世纪把这个名词带入中古英语。"},{"era":"LATIN AEQUILIBRIUM","en":"Aequilibrium, from aequus 'level' and libra 'scales', supplied the first word.","cn":"第一个词来自 aequilibrium，由 aequus「平」与 libra「天平」构成。"},{"era":"ECONOMIC PAIRING","en":"Nineteenth-century writers paired the balancing price with the amount traded, and the pair became standard in the twentieth century.","cn":"十九世纪作者把平衡价格与成交数量配成一对，这一配对在二十世纪成为标准。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper origin of quantus is a reconstruction, and the first use of the full phrase is dated only approximately.","cn":"来源不确定：quantus 的更早来源属重构，整个短语的最早用例也只能给约数。"}]},"similar":{"note":{"en":"Group one holds neighbouring quantity terms that are easily swapped in; group two holds near labels for the traded amount.","cn":"第一组是容易互换的相邻数量术语；第二组是成交量的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"equilibrium price","ipa":"/ˌiːkwɪˈlɪbriəm praɪs/","tag":"the other coordinate","definition":"The balancing value in money; it is the partner figure read from the same crossing point.","definitionCN":"以货币表示的平衡值；是与它从同一交点读出的配对数字。"},{"word":"quantity demanded","ipa":"/ˈkwɒntəti dɪˈmɑːndɪd/","tag":"one side only","definition":"How much buyers want at a given price; it is one curve, not the matched outcome.","definitionCN":"给定价格下买方想要的数量；只是其中一条曲线，不是相符后的结果。"},{"word":"quantity supplied","ipa":"/ˈkwɒntəti səˈplaɪd/","tag":"one side only","definition":"How much sellers offer at a given price; alone it says nothing about what actually trades.","definitionCN":"给定价格下卖方提供的数量；单看并不能说明实际成交多少。"},{"word":"output","ipa":"/ˈaʊtpʊt/","tag":"production, not trade","definition":"What is produced, whether or not anyone buys it; it measures making, not matching.","definitionCN":"生产出来的东西，无论是否有人买；衡量生产，不是匹配。"}]},{"heading":"NEAR MEANING","entries":[{"word":"traded volume","ipa":"/ˈtreɪdɪd ˈvɒljuːm/","tag":"market usage","definition":"The amount actually exchanged in a period; close in meaning but observed rather than modelled.","definitionCN":"某段时期内实际交换的数量；意思接近，但属观察值而非模型值。"},{"word":"market volume","ipa":"/ˈmɑːkɪt ˈvɒljuːm/","tag":"aggregate label","definition":"Total trade in a market over a period; it aggregates many transactions, while this term marks one balancing amount.","definitionCN":"市场一段时期内的总成交；汇总许多交易，而本词指单一的平衡量。"},{"word":"throughput","ipa":"/ˈθruːpʊt/","tag":"flow measure","definition":"The amount processed through a system in a given time; it measures flow, not a market match.","definitionCN":"系统在给定时间内处理的数量；衡量流量，不是市场匹配。"},{"word":"amount","ipa":"/əˈmaʊnt/","tag":"plain word","definition":"The everyday word for how much there is; it carries none of the balancing sense.","definitionCN":"表示「有多少」的日常词，不含平衡之意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two source words, the coordinate image and the real fixed phrases.","cn":"正常联想：两个来源词、坐标意象与真实的固定搭配。"},"normal":[{"en":"Balance plus amount: how much changes hands when the beam is level.","cn":"平衡加数量：横梁放平时有多少东西易手。"},{"en":"It is the horizontal coordinate of the crossing point.","cn":"它是交点处的横坐标。"},{"en":"The usual fixed phrases are equilibrium quantity and price and raise the equilibrium quantity.","cn":"常见固定说法是均衡数量与价格、提高均衡数量。"},{"en":"Its partner is equilibrium price, read from the same point.","cn":"与它配对的是均衡价格，从同一点读出。"},{"en":"A tax usually lowers this amount while raising the balancing price.","cn":"税收通常压低这个数量，同时抬高平衡价格。"}],"abstract":[{"en":"Picture two lists of numbers sliding toward each other until they line up.","cn":"想象两张数字清单相向滑动，直到完全对齐。"},{"en":"Picture a warehouse emptied exactly as the last order is filled.","cn":"想象仓库在最后一张订单填上时正好清空。"},{"en":"Picture a single point on a chart that answers two questions at once.","cn":"想象图上一个点同时回答两个问题。"}]},"examples":[{"en":"The new tariff cut the equilibrium quantity of imported steel.","cn":"新关税削减了进口钢材的均衡数量。"},{"en":"Economists report the equilibrium quantity alongside the balancing price.","cn":"经济学家把均衡数量与平衡价格一并报告。"},{"en":"A bumper harvest raised the equilibrium quantity but lowered the price.","cn":"丰收提高了均衡数量，却压低了价格。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「equilibrium（平衡）+ quantity（数量）」——天平放平时，究竟成交多少","word":"equilibrium quantity"},"root":"由 equilibrium（拉丁 aequilibrium「水平的平衡」）与 quantity（拉丁 quantitas「数量」，经古法语）组合而成的经济学短语，自身无独立拉丁词源。","sensesIntro":{"en":"Eight senses follow one amount: the traded figure, its axis, the cleared market, a policy baseline, a new level after a shift, the partner of the balancing price, a modelled ideal and finally an attributive estimate label.","cn":"八个义项围绕同一个数量：成交量、横坐标、出清量、政策基准、变动后的新水平、平衡价格的伙伴、模型理想值，最后是作定语的估算标签。"},"semanticMap":{"core":{"en":"CORE IMAGE: a warehouse ledger whose two columns finally show the same number.","cn":"核心意象：一本仓库账簿的两栏终于写出同一个数字。"},"chain":["CROSSING POINT","HORIZONTAL AXIS","MATCHED AMOUNT","CLEARED MARKET","POLICY EFFECT","MOVING AMOUNT"],"branches":[{"senses":"01 · 02","en":"POINT AND AXIS: the traded amount and its coordinate on the chart are the same number seen twice.","cn":"点与轴：成交数量与图上它的坐标，是同一个数字的两种呈现。"},{"senses":"03 · 06","en":"CLEARING AND PAIRING: the amount that empties the market is also the partner of the balancing price.","cn":"出清与配对：使市场清空的数量，同时也是平衡价格的伙伴。"},{"senses":"04 · 07","en":"BASELINE AND MODEL: policy measures against it, and theory treats it as an ideal rather than a sales total.","cn":"基准与模型：政策拿它作基准，理论把它当作理想值而非销量总和。"},{"senses":"05","en":"SHIFT: when the curves move, the traded amount settles at a new level.","cn":"移动：曲线一动，成交量就停在新的水平。"},{"senses":"08","en":"METHOD: hyphenated, the phrase names the estimate rather than the figure.","cn":"方法：加连字符后，短语指估算而非数字本身。"}]},"affixes":{"intro":{"en":"The phrase joins a balance word and an amount word, each from a different Latin root, so it is read in two halves.","cn":"这个短语把「平衡」词与「数量」词连接起来，二者来自不同拉丁词根，因此分两半读。"},"latinIntro":{"en":"Aequus and libra build the first word, quantus and quantitas the second.","cn":"aequus 与 libra 构成第一个词，quantus 与 quantitas 构成第二个词。"},"items":[{"word":"aequi-","structure":"Latin combining form from aequus","meaning":"equal, level","meaningCN":"相等的；平的","example":"The first word carries the level beam.","exampleCN":"第一个词带着放平的横梁。"},{"word":"libra","structure":"Latin noun, first declension","meaning":"balance, scales","meaningCN":"天平；秤","example":"The scales image sits inside the first word.","exampleCN":"天平的意象在第一个词里。"},{"word":"quantus","structure":"Latin adjective","meaning":"how much, how great","meaningCN":"多少；多大","example":"The second word comes from this measure word.","exampleCN":"第二个词来自这个度量词。"},{"word":"quantitas","structure":"Latin noun, third declension","meaning":"amount, size","meaningCN":"数量；大小","example":"Quantitas supplied the English quantity.","exampleCN":"quantitas 提供了英语的 quantity。"},{"word":"quantity","structure":"quantitas through Old French quantite","meaning":"an amount","meaningCN":"数量","example":"The quantity cleared the warehouse.","exampleCN":"这个数量让仓库清空。"},{"word":"quantify","structure":"quantity + -ify","meaning":"to express as a number","meaningCN":"量化","example":"The study quantified the effect.","exampleCN":"这项研究量化了影响。"},{"word":"quantitative","structure":"quantity + -ative","meaning":"concerned with amounts","meaningCN":"定量的","example":"Quantitative evidence supported the claim.","exampleCN":"定量证据支持这一主张。"},{"word":"equilibrium","structure":"aequus + libra","meaning":"a level balance","meaningCN":"水平的平衡","example":"Prices moved back to equilibrium.","exampleCN":"价格回到平衡。"}],"latinEntries":[{"word":"quantus","structure":"quantus, quanta, quantum (adj., first and second declension)","meaning":"how much, how great","meaningCN":"多少；多大"},{"word":"quantitas","structure":"quantitas, quantitatis (f., third declension)","meaning":"amount, size","meaningCN":"数量；大小"},{"word":"aequilibrium","structure":"aequilibrium, aequilibri (n., second declension)","meaning":"a level balance","meaningCN":"水平的平衡"}],"derivatives":[{"word":"quantity","pos":"n.","zh":"数量"},{"word":"quantify","pos":"v.","zh":"量化"},{"word":"quantitative","pos":"adj.","zh":"定量的"},{"word":"equilibrium quantity estimate","pos":"n.","zh":"均衡数量估算"}]}},{"word":"shortage","ipa_uk":"/ˈʃɔːtɪdʒ/","ipa_us":"/ˈʃɔːrtɪdʒ/","definition_zh":"短缺；不足；短缺量；缺货","definition_en":"a situation in which there is not enough of something that people need","core_image":"货架空出一大段，排队的人还在往前挤","scene":"暴雨封住公路之后，镇上唯一的面包店货架很快空了，店主只好在门口贴出限购告示。After the storm closed the roads, the town's only bakery faced a serious shortage of flour.","sceneCN":"暴雨封路后，镇上唯一的面包店货架很快空了，店主贴出限购告示；句中的 shortage 指「所需之物不够用的情况」（第 1 个义项：某物数量不够满足需要）。图中可辨识物件：空货架、限购告示、雨伞、排队的人。","pos":[{"tag":"n.","zh":"短缺；不足；短缺量；缺货状态"}],"collocations":[{"phrase":"a shortage of sth","zh":"某物短缺"},{"phrase":"labour shortage","zh":"劳动力短缺"},{"phrase":"food shortage","zh":"粮食短缺"},{"phrase":"water shortage","zh":"缺水"},{"phrase":"a severe shortage","zh":"严重短缺"},{"phrase":"ease a shortage","zh":"缓解短缺"}],"forms":[{"label":"复数","form":"shortages"},{"label":"形容词（短的；不足的）","form":"short"},{"label":"副词（不足地）","form":"short"},{"label":"相关名词（缺口）","form":"shortfall"}],"derivatives":[{"word":"short","pos":"adj./adv.","zh":"短的；不足的；短缺地"},{"word":"shortfall","pos":"n.","zh":"缺口；差额"},{"word":"shorten","pos":"v.","zh":"缩短"},{"word":"shortage-driven","pos":"adj.","zh":"由短缺引起的"}],"senses":[{"no":"01","title":"Not enough of a needed thing","titleCN":"所需之物不够用","definition":"a condition in which the available amount of something is below what is needed","definitionCN":"某物的现有数量低于所需的状态","example":"After the storm closed the roads, the town's only bakery faced a serious shortage of flour.","exampleCN":"暴雨封路后，镇上唯一的面包店面临严重的面粉短缺。","why":"The word is short plus a noun suffix, so the core reading is simply the state of being short of something.","whyCN":"这个词由 short 加名词后缀构成，核心意思就是「处于短缺的状态」。"},{"no":"02","title":"Excess demand in economics","titleCN":"经济学中的需求超过供给","definition":"the market condition in which the quantity demanded exceeds the quantity supplied","definitionCN":"需求量超过供给量的市场状态","example":"At a capped price, a shortage appeared within days.","exampleCN":"在限价之下，短缺几天内就出现了。","why":"Economics measures shortness as a gap between two quantities, turning a felt lack into a number.","whyCN":"经济学把「短」量成两个数量之间的差，把感受到的缺乏变成数字。"},{"no":"03","title":"A lack of workers or skills","titleCN":"劳动力或技能的不足","definition":"a situation in which there are too few people able or willing to do the work","definitionCN":"能胜任或愿意从事该工作的人太少的状态","example":"The hospital reported a chronic shortage of nurses.","exampleCN":"医院报告长期缺乏护士。","why":"People can be counted like goods, so the same word covers an empty staff roster as well as an empty shelf.","whyCN":"人可以像货物一样计数，因此同一个词既指空货架，也指排不满的班表。"},{"no":"04","title":"A humanitarian lack of supplies","titleCN":"人道意义上的物资匮乏","definition":"a severe lack of food, water or medicine affecting a whole population","definitionCN":"影响整个人群的食品、水或药品严重匮乏","example":"Aid agencies warned of a water shortage across the region.","exampleCN":"援助机构警告全区存在缺水问题。","why":"When the lack threatens life, shortage becomes a public emergency word rather than a market term.","whyCN":"当匮乏威胁生命，shortage 就从市场术语变成公共紧急用语。"},{"no":"05","title":"A specific missing amount","titleCN":"具体的短缺量","definition":"the amount by which what is available falls below what is required","definitionCN":"现有数量低于所需数量的差额","example":"The granary reported a shortage of ten tons against its target.","exampleCN":"粮库报告比目标少了十吨。","why":"The same noun can name the gap itself, not just the situation, which is why it takes a number.","whyCN":"这个名词也能指缺口本身而不只是处境，所以它可以带具体数字。"},{"no":"06","title":"A supply disruption in business","titleCN":"商业中的供应中断","definition":"a temporary failure of supply that leaves orders unmet","definitionCN":"供应暂时中断导致订单无法满足","example":"A single late shipment caused a shortage of parts on the line.","exampleCN":"一批迟到的货就让生产线缺件。","why":"Business use focuses on the broken flow rather than the missing total, so shortage becomes an operational event.","whyCN":"商业用法关注流被中断，而非总量缺少，因此短缺成了一起运营事件。"},{"no":"07","title":"A lack of time or money","titleCN":"时间或金钱上的不足","definition":"an insufficient amount of something abstract that a plan requires","definitionCN":"计划所需的某种抽象之物数量不足","example":"A shortage of time forced the team to drop two experiments.","exampleCN":"时间不足迫使团队砍掉两个实验。","why":"Once shortness can be counted, it attaches to anything a plan needs, including hours and funds.","whyCN":"一旦「短」可以计数，它就能附着于计划所需的任何东西，包括工时与资金。"},{"no":"08","title":"An empty space on a shelf","titleCN":"货架上的缺货","definition":"the retail condition in which an item is out of stock","definitionCN":"零售中某商品无货可卖的状态","example":"Shoppers met an empty shelf and a handwritten shortage notice.","exampleCN":"顾客只看到空货架和一张手写的缺货通知。","why":"Retail reduces the whole idea to one missing item, which is the scene most people picture.","whyCN":"零售把整个概念缩到一件缺货商品，这也是多数人想到的画面。"}],"etymology":{"intro":{"en":"Shortage is an English noun built from short plus the French-Latin suffix -age. It appeared in the early nineteenth century and was soon adopted by economics.","cn":"shortage 是由 short 加法语—拉丁后缀 -age 构成的英语名词，十九世纪初出现，很快被经济学采用。"},"items":[{"era":"OLD ENGLISH SHORT","en":"Short comes from Old English sceort, 'not long', from a Germanic root reconstructed as skurta-.","cn":"short 来自古英语 sceort「不长」，其日耳曼词根重构为 skurta-。"},{"era":"SUFFIX -AGE","en":"The suffix -age, from French, goes back to Latin -aticum and forms nouns of state or collection.","cn":"后缀 -age 来自法语，可上溯至拉丁 -aticum，构成表示状态或集合的名词。"},{"era":"ENGLISH SHORTAGE","en":"Short plus -age produced shortage in the early nineteenth century, first as a plain word for not having enough.","cn":"short 加 -age 在十九世纪初构成 shortage，最初只是「不够用」的普通说法。"},{"era":"INDUSTRIAL USE","en":"Victorian reports on food, housing and labour made shortage a standard word in public administration.","cn":"维多利亚时代关于食品、住房与劳动的调查报告，使 shortage 成为公共管理中的标准词。"},{"era":"ECONOMIC SENSE","en":"Economists later defined it precisely as the gap between quantity demanded and quantity supplied at a given price.","cn":"经济学家后来把它精确定义为给定价格下需求量与供给量之间的差。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the Germanic root behind short is a reconstruction, and the earliest record of shortage is dated only approximately.","cn":"来源不确定：short 背后的日耳曼词根属重构，shortage 的最早记录也只能给约数。"}]},"similar":{"note":{"en":"Group one holds words often used as if they meant the same as shortage; group two holds true near-synonyms with a different scope.","cn":"第一组是常被当作 shortage 同义词使用的词；第二组是范围不同的真正近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"scarcity","ipa":"/ˈskeəsəti/","tag":"long-term condition","definition":"A lasting condition in which resources are limited relative to wants; shortage is a temporary gap that price can close.","definitionCN":"资源相对欲望长期有限的状态；shortage 是价格可以弥合的暂时缺口。"},{"word":"deficit","ipa":"/ˈdefɪsɪt/","tag":"accounting gap","definition":"The amount by which money or goods fall short in an account or budget; it is a bookkeeping figure, not a market state.","definitionCN":"账目或预算中钱或货不足的数额；是记账数字，不是市场状态。"},{"word":"shortfall","ipa":"/ˈʃɔːtfɔːl/","tag":"countable gap","definition":"The exact amount by which a target is missed; it is close to the counted sense of shortage but always a figure.","definitionCN":"未达目标的确切数额；接近 shortage 的计数义，但总是一个数字。"},{"word":"dearth","ipa":"/dɜːθ/","tag":"dated, broad","definition":"An old word for a general lack, especially of food; it sounds literary where shortage sounds administrative.","definitionCN":"指普遍缺乏的旧词，尤指缺粮；文学色彩浓，而 shortage 带行政色彩。"}]},{"heading":"NEAR MEANING","entries":[{"word":"lack","ipa":"/læk/","tag":"plain word","definition":"The general state of not having something; it carries no economic measurement.","definitionCN":"没有某物的普通状态；不含经济计量。"},{"word":"insufficiency","ipa":"/ˌɪnsəˈfɪʃənsi/","tag":"formal","definition":"The quality of being too little for a purpose; a formal synonym that stresses inadequacy.","definitionCN":"对某用途而言太少的性质；正式同义词，强调不足。"},{"word":"famine","ipa":"/ˈfæmɪn/","tag":"extreme food case","definition":"A widespread extreme lack of food causing hunger and death; it is the gravest case of shortage.","definitionCN":"大范围极端缺粮并造成饥饿与死亡；是 shortage 最严重的形态。"},{"word":"bottleneck","ipa":"/ˈbɒtlnek/","tag":"cause of shortage","definition":"A point in a system that limits flow and so produces shortage downstream; it names the cause, not the lack.","definitionCN":"系统中限制流动、从而在下游造成短缺的环节；指原因而非缺乏本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real pieces, the fixed phrases and the counted gap.","cn":"正常联想：两个真实构词成分、固定搭配与可计数的缺口。"},"normal":[{"en":"Short plus -age: the state of being short of something.","cn":"short 加 -age：处于缺少某物的状态。"},{"en":"The family runs short, shortage, shortfall, shorten and shortness.","cn":"同族词有 short、shortage、shortfall、shorten 与 shortness。"},{"en":"Fixed phrases: a shortage of water, a labour shortage, a severe shortage.","cn":"固定说法：缺水、劳动力短缺、严重短缺。"},{"en":"In economics it is the gap between quantity demanded and quantity supplied.","cn":"在经济学中它是需求量与供给量之间的差。"},{"en":"The opposite term is surplus, the same gap pointing the other way.","cn":"反义术语是过剩，即同一缺口指反方向。"}],"abstract":[{"en":"Picture a queue that keeps growing while the shelf behind it keeps shrinking.","cn":"想象队伍越来越长，身后的货架却越来越空。"},{"en":"Picture a ruler laid across a gap and the gap marked in red.","cn":"想象一把尺子横在缺口上，缺口被标成红色。"},{"en":"Picture a clock with too few hours for the work written beside it.","cn":"想象一只钟，旁边写的活儿却需要更多小时。"}]},"examples":[{"en":"The city faces a serious shortage of affordable housing.","cn":"这座城市面临严重的廉价住房短缺。"},{"en":"A shortage of chips halted production for three weeks.","cn":"芯片短缺使生产停滞了三周。"},{"en":"Better storage would ease the seasonal water shortage.","cn":"改善储水可以缓解季节性缺水。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「short（短）+ age（状态）」——东西短了一截，就是短缺与不足","word":"shortage"},"root":"英语 short（古英语 sceort「不长」，日耳曼词根重构为 skurta-）加后缀 -age（源自拉丁 -aticum）构成，属英语本土构词，非拉丁借词。","sensesIntro":{"en":"Eight senses follow one gap: a general lack, excess demand, too few workers, a humanitarian emergency, a counted deficit, a broken supply flow, missing time or money, and finally an empty retail shelf.","cn":"八个义项围绕同一个缺口：普遍缺乏、需求过剩、人手不够、人道危机、可计数的差额、供应流中断、时间或资金不足，最后是零售货架上的缺货。"},"semanticMap":{"core":{"en":"CORE IMAGE: a shelf with a visible empty stretch while buyers keep coming.","cn":"核心意象：货架空出一段，买东西的人却还在来。"},"chain":["EMPTY SHELF","NOT ENOUGH","EXCESS DEMAND","MISSING AMOUNT","BROKEN FLOW","PERSISTENT LACK"],"branches":[{"senses":"01 · 05","en":"LACK AND GAP: the felt condition and the counted missing amount are one shortage seen with and without a number.","cn":"缺乏与差额：感受到的处境与数出来的缺口，是同一个短缺的两种看法。"},{"senses":"02 · 07","en":"TWO QUANTITIES: the market gap and a missing budget of hours are both differences between what is there and what is needed.","cn":"两个数量：市场缺口与不够用的工时，都是「现有」与「所需」之差。"},{"senses":"03 · 08","en":"PEOPLE AND SHELVES: an empty roster and an empty shelf are the same word applied to workers and goods.","cn":"人与货架：空班表与空货架，是同一个词用在人手与货物上。"},{"senses":"04","en":"EMERGENCY: when the lack threatens life, the word leaves economics for public alarm.","cn":"紧急：当匮乏威胁生命，这个词就从经济学走进公共警报。"},{"senses":"06","en":"BROKEN FLOW: business sees the interrupted shipment rather than the missing total.","cn":"流中断：商业看到的是被截断的货运，而不是缺少的总量。"}]},"affixes":{"intro":{"en":"Shortage is one Old English adjective plus one French-Latin noun suffix, so it can be read in two pieces without any Latin root of its own.","cn":"shortage 由一个古英语形容词加一个法语—拉丁名词后缀构成，可直接按两块读出，本身没有独立的拉丁词根。"},"latinIntro":{"en":"Only the suffix -age is of Latin origin, through French -age from Latin -aticum; the adjective short is Germanic.","cn":"只有后缀 -age 源自拉丁语，经法语 -age 上溯至拉丁 -aticum；形容词 short 属日耳曼语。"},"items":[{"word":"short","structure":"Old English adjective sceort","meaning":"not long; not enough","meaningCN":"短的；不足的","example":"The shelf was short of flour.","exampleCN":"货架上的面粉不够了。"},{"word":"-age","structure":"noun suffix from French, from Latin -aticum","meaning":"state or collection","meaningCN":"状态或集合","example":"The suffix turns the adjective into a state noun.","exampleCN":"这个后缀把形容词变成状态名词。"},{"word":"shortage","structure":"short + -age","meaning":"the state of being short","meaningCN":"短缺的状态","example":"The bakery faced a flour shortage.","exampleCN":"面包店面面临面粉短缺。"},{"word":"shortfall","structure":"short + fall","meaning":"the amount by which a target is missed","meaningCN":"未达标的缺口","example":"The harvest left a shortfall of ten tons.","exampleCN":"收成留下了十吨的缺口。"},{"word":"shorten","structure":"short + -en (verb)","meaning":"to make shorter","meaningCN":"缩短","example":"They shortened the delivery route.","exampleCN":"他们缩短了送货路线。"},{"word":"shortness","structure":"short + -ness","meaning":"the quality of being short","meaningCN":"短；不足","example":"Shortness of breath followed the climb.","exampleCN":"爬坡之后出现了气短。"},{"word":"short-staffed","structure":"short + staffed","meaning":"having too few workers","meaningCN":"人手不足的","example":"The ward was short-staffed all winter.","exampleCN":"整个冬天这个病区都人手不足。"},{"word":"short-dated","structure":"short + dated","meaning":"due soon","meaningCN":"期限短的","example":"Short-dated stock sells first.","exampleCN":"保质期短的货先卖。"}],"latinEntries":[{"word":"-aticum","structure":"-aticum, -atici (n., second declension; suffix)","meaning":"a state, a group, a duty","meaningCN":"状态；群体；义务"}],"derivatives":[{"word":"short","pos":"adj./adv.","zh":"短的；不足的"},{"word":"shortfall","pos":"n.","zh":"缺口；差额"},{"word":"shorten","pos":"v.","zh":"缩短"},{"word":"shortness","pos":"n.","zh":"短；不足"}]}},{"word":"surplus","ipa_uk":"/ˈsɜːpləs/","ipa_us":"/ˈsɜːrpləs/","definition_zh":"过剩；剩余；盈余；多余的（作定语）","definition_en":"an amount left over after what is needed has been used, or more than is required","core_image":"满仓的谷袋之外，还堆着一座没处放的粮堆","scene":"秋收之后，合作社把多出来的粮食装进临时搭起的仓棚，等来年再卖。After the harvest, the cooperative stored its surplus grain in a temporary shed.","sceneCN":"秋收后，合作社把多出来的粮食装进临时仓棚，等来年再卖；句中的 surplus 指「满足需要之后剩余下来的量」（第 1 个义项：用不完而剩下的部分）。图中可辨识物件：满仓的谷袋、临时仓棚、木锨、田埂。","pos":[{"tag":"n.","zh":"剩余；过剩；盈余；顺差"},{"tag":"adj.","zh":"多余的；过剩的"}],"collocations":[{"phrase":"trade surplus","zh":"贸易顺差"},{"phrase":"budget surplus","zh":"预算盈余"},{"phrase":"surplus grain","zh":"余粮"},{"phrase":"a surplus of sth","zh":"某物的过剩"},{"phrase":"surplus to requirements","zh":"多余的；不再需要的"},{"phrase":"agricultural surplus","zh":"农业过剩"}],"forms":[{"label":"复数","form":"surpluses"},{"label":"形容词（同形）","form":"surplus"},{"label":"相关名词（剩余物；赘语）","form":"surplusage"},{"label":"相关名词（剩余物）","form":"surplusage"}],"derivatives":[{"word":"surplusage","pos":"n.","zh":"剩余物；赘语"},{"word":"surplus-value","pos":"n.","zh":"剩余价值"},{"word":"surpluses","pos":"n.","zh":"剩余（复数）"},{"word":"surplus labor","pos":"n.","zh":"剩余劳动"}],"senses":[{"no":"01","title":"What is left after needs are met","titleCN":"满足需要后剩下的部分","definition":"the amount that remains once what is needed has been used","definitionCN":"所需之物用完之后剩下的数量","example":"After the harvest, the cooperative stored its surplus grain in a temporary shed.","exampleCN":"秋收后，合作社把余粮存进临时仓棚。","why":"The Latin source is literally 'over more', so the word begins as what sits above the required line.","whyCN":"拉丁词源字面就是「在上方更多」，因此词义起于「超出所需线」的部分。"},{"no":"02","title":"Supply beyond demand","titleCN":"供给超过需求","definition":"the market condition in which the quantity supplied exceeds the quantity demanded","definitionCN":"供给量超过需求量的市场状态","example":"A price floor kept a surplus of milk in the market.","exampleCN":"最低限价让市场上牛奶过剩。","why":"Economics turns the leftover into a measured gap, exactly mirroring shortage on the other side.","whyCN":"经济学把剩余量化为差额，与另一侧的短缺正好对称。"},{"no":"03","title":"Exports above imports","titleCN":"出口多于进口；贸易顺差","definition":"the amount by which a country's exports exceed its imports","definitionCN":"一国出口超过进口的数额","example":"The trade surplus widened for a third quarter.","exampleCN":"贸易顺差连续第三个季度扩大。","why":"A trade balance is a national ledger, and a positive balance is literally a left-over on the plus side.","whyCN":"贸易差额是国家账簿，正差额字面上就是加号一侧的剩余。"},{"no":"04","title":"Revenue above spending","titleCN":"收入多于支出；预算盈余","definition":"the amount by which income exceeds expenditure in a budget","definitionCN":"预算中收入超过支出的数额","example":"The city ran a small budget surplus last year.","exampleCN":"该市去年有少量预算盈余。","why":"A budget is a set of needs, and whatever is left after paying them is the same surplus.","whyCN":"预算是一组需要，付清之后剩下的就是同一种剩余。"},{"no":"05","title":"Extra or spare, as an adjective","titleCN":"作定语表示多余、备用的","definition":"more than is needed, and therefore available to spare","definitionCN":"超出所需，因而可以匀出来的","example":"The army sold its surplus equipment at auction.","exampleCN":"军队把多余的装备拍卖掉了。","why":"The noun became a modifier: what is left over becomes a stock of extra things.","whyCN":"名词转为定语：剩下的东西成了一批备用物。"},{"no":"06","title":"Extra farm produce","titleCN":"农业上的余粮余菜","definition":"crops produced beyond what the growers themselves consume","definitionCN":"种植者自用之外多产出的农产品","example":"Farmers hauled their surplus to the town market.","exampleCN":"农民把余粮运到镇上市场。","why":"Agriculture gives the word its oldest concrete setting: grain that no household can eat.","whyCN":"农业给了这个词最古老的具体场景：家里吃不完的粮食。"},{"no":"07","title":"Retained earnings in accounting","titleCN":"会计上的留存收益","definition":"the accumulated profit kept in a company rather than paid out","definitionCN":"留在公司、未分配出去的累计利润","example":"The firm moved the surplus into its reserves.","exampleCN":"公司把盈余转入公积金。","why":"Accounting keeps the ledger sense: profit beyond what was disbursed is a leftover on the books.","whyCN":"会计保留了账簿义：未分配而留下的利润就是账上的剩余。"},{"no":"08","title":"Redundant staff or stock","titleCN":"冗员或多余库存","definition":"people or goods no longer needed for the job in hand","definitionCN":"当前工作已不再需要的人员或货物","example":"Two assistants were declared surplus to requirements.","exampleCN":"两名助理被列为富余人员。","why":"The phrase surplus to requirements states the core idea socially: what remains after the need has been defined.","whyCN":"「超出需求」这一说法把核心意思社会化：需求界定之后还剩下的东西。"}],"etymology":{"intro":{"en":"Surplus comes from Old French surplus, from Medieval Latin superplus, literally 'over more'. It entered English in the sixteenth century as a noun of remainder.","cn":"surplus 经古法语 surplus 来自中世纪拉丁 superplus，字面是「在上方更多」，十六世纪作为「剩余」名词进入英语。"},"items":[{"era":"LATIN PLUS","en":"Plus meant 'more'. It is generally traced to the same reconstructed root as plere 'to fill', which also gives supply and complete.","cn":"plus 意为「更多」，一般认为与 plere「填满」同出同一重构词根，supply 与 complete 也来自那一支。"},{"era":"MEDIEVAL LATIN SUPERPLUS","en":"Super- 'over' plus plus produced superplus, an amount over and above what is needed.","cn":"super-「在上」加 plus 构成 superplus，即超出所需之上的量。"},{"era":"OLD FRENCH","en":"Old French surplus carried both the noun of remainder and the adjective meaning extra.","cn":"古法语 surplus 既指剩余的名词，也指「额外」的形容词。"},{"era":"SIXTEENTH-CENTURY ENGLISH","en":"English adopted surplus in the 1500s, first in accounts and inventories where a remainder had to be recorded.","cn":"英语在十六世纪吸收 surplus，最初用于需要记录余数的账目与清册。"},{"era":"ECONOMIC SENSE","en":"Nineteenth-century economics fixed the familiar senses: excess supply, a positive trade balance and a budget remainder.","cn":"十九世纪经济学固定了如今熟悉的义项：供给过剩、贸易正差额与预算剩余。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the link between plus and the filling root is a reconstruction rather than a recorded derivation.","cn":"来源不确定：plus 与「填满」词根之间的联系属重构，并非有记录的派生。"}]},"similar":{"note":{"en":"Group one holds look-alikes and same-root words; group two holds near words for what is left over.","cn":"第一组是形近词与同根词；第二组是表示「剩下」的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"supplement","ipa":"/ˈsʌplɪmənt/","tag":"added, not left","definition":"Something added to complete a whole; a surplus is what remains after the whole is already satisfied.","definitionCN":"为补足整体而添加的东西；surplus 则是整体已满足后剩下的部分。"},{"word":"superfluous","ipa":"/suːˈpɜːfluəs/","tag":"same over idea","definition":"From super- plus fluere 'to flow': flowing over, hence unnecessary; it describes a quality, while surplus names an amount.","definitionCN":"由 super- 加 fluere「流」构成：溢出因而多余；它描述性质，surplus 指名数量。"},{"word":"superplus","ipa":"/ˈsuːpəplʌs/","tag":"the Latin source","definition":"The Medieval Latin form behind the word; it survives only in technical or historical writing.","definitionCN":"这个词背后的中世纪拉丁形式；如今只见于技术或历史文字。"},{"word":"surplice","ipa":"/ˈsɜːpləs/","tag":"different origin","definition":"A white church garment, from a different Latin base; the similar sound is accidental.","definitionCN":"一种白色教堂礼服，来自另一拉丁词基；读音相近只是巧合。"}]},{"heading":"NEAR MEANING","entries":[{"word":"excess","ipa":"/ɪkˈses/","tag":"general word","definition":"More than is usual or allowed; it is the everyday word, while surplus often implies a recorded remainder.","definitionCN":"超过通常或允许的量；是日常用词，surplus 常含「记录在账的余数」。"},{"word":"glut","ipa":"/ɡlʌt/","tag":"market over-supply","definition":"A supply so large that it cannot be absorbed; it is a more negative word than surplus.","definitionCN":"大到无法消化的供给；比 surplus 更带负面色彩。"},{"word":"remainder","ipa":"/rɪˈmeɪndə/","tag":"what is left","definition":"The part left after the rest is taken; it lacks the economic sense of a positive balance.","definitionCN":"其余部分取走后剩下的部分；不含「正差额」的经济义。"},{"word":"overage","ipa":"/ˈəʊvərɪdʒ/","tag":"counted extra","definition":"An amount over an expected or allowed figure; it is a counted excess, not a stored remainder.","definitionCN":"超过预期或允许数字的部分；是可计的超出量，不是储存的余数。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Latin pieces, the fixed phrases and the mirrored pair with shortage.","cn":"正常联想：拉丁构词成分、固定搭配，以及与短缺对称的配对。"},"normal":[{"en":"Super- 'over' plus plus 'more': what sits above the needed line.","cn":"super-「在上」加 plus「更多」：超出所需线之上的部分。"},{"en":"The family runs surplus, surpluses, surplusage and surplus-value.","cn":"同族词有 surplus、surpluses、surplusage 与 surplus-value。"},{"en":"Fixed phrases: trade surplus, budget surplus, surplus grain, surplus to requirements.","cn":"固定说法：贸易顺差、预算盈余、余粮、富余人员。"},{"en":"Its opposite is shortage, the same gap with the sign reversed.","cn":"反义是短缺，即同一缺口把符号反过来。"},{"en":"Political economy pairs it with demand: excess supply is one form of surplus.","cn":"政治经济学把它与需求配对：供给过剩是剩余的一种形态。"}],"abstract":[{"en":"Picture a granary so full that sacks spill out and sit in the yard.","cn":"想象粮仓满到谷袋溢出来，堆在院子里。"},{"en":"Picture a table cleared of every guest while one untouched plate remains.","cn":"想象客人散尽，桌上还剩一盘没动过的菜。"},{"en":"Picture a ledger line where income and outgo leave a number on the plus side.","cn":"想象账簿上一行收入与支出，最后在加号一侧留下一个数。"}]},"examples":[{"en":"The country recorded a record trade surplus with its largest partner.","cn":"该国与最大贸易伙伴录得创纪录的贸易顺差。"},{"en":"Better storage turned a seasonal surplus into steady supply.","cn":"更好的储藏把季节性余粮变成稳定供给。"},{"en":"The agency sold surplus furniture to local schools.","cn":"该机构把多余家具卖给当地学校。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「sur（在上）+ plus（更多）」——在所需之上还多出来的，就是剩余与盈余","word":"surplus"},"root":"古法语 surplus，来自中世纪拉丁 superplus = super-（在上）+ plus（更多）；plus 一般认为与 plere「填满」同出重构词根。","sensesIntro":{"en":"Eight senses follow one remainder: what is left after needs, excess supply, a trade balance, a budget balance, spare goods, extra crops, retained profit and finally redundant staff.","cn":"八个义项围绕同一个余量：需求满足后的剩余、供给过剩、贸易差额、预算余额、备用物资、多产的农产品、留存利润，最后是富余人员。"},"semanticMap":{"core":{"en":"CORE IMAGE: a full granary with a heap of extra sacks standing outside it.","cn":"核心意象：满仓之外还堆着一小堆多余的谷袋。"},"chain":["MORE THAN NEEDED","LEFTOVER STOCK","EXCESS SUPPLY","POSITIVE BALANCE","SPARE GOODS","REDUNDANCY"],"branches":[{"senses":"01 · 06","en":"REMAINDER: grain a household cannot eat and goods a buyer cannot absorb are the same leftover at two scales.","cn":"余量：家里吃不完的粮与买家吃不下的货，是同一剩余的两个尺度。"},{"senses":"02 · 07","en":"TWO LEDGERS: excess supply and retained profit both record a positive balance.","cn":"两本账：供给过剩与留存利润，都记下了一个正余额。"},{"senses":"03 · 04","en":"NATIONAL AND PUBLIC ACCOUNTS: exports over imports and revenue over spending are the same plus sign.","cn":"国家与公共账簿：出口多于进口、收入多于支出，是同一个加号。"},{"senses":"05","en":"SPARE: as an adjective the leftover becomes a stock of extra things.","cn":"备用：作定语时，剩余变成一批多余物资。"},{"senses":"08","en":"REDUNDANCY: the phrase surplus to requirements puts the same idea on people.","cn":"冗员：超出需求这一说法把同一想法用在人身上。"}]},"affixes":{"intro":{"en":"Surplus is two Latin pieces meaning over and more, and both pieces still build English words.","cn":"surplus 由两个意为「在上」与「更多」的拉丁成分构成，两部分至今仍能构成英语词。"},"latinIntro":{"en":"Latin super- gives superplus, superfluous and supervise; Latin plus gives plus, plural and surplus itself.","cn":"拉丁 super- 衍生 superplus、superfluous 与 supervise；拉丁 plus 衍生 plus、plural 与 surplus 本身。"},"items":[{"word":"super-","structure":"Latin prefix","meaning":"above, over","meaningCN":"在上；超过","example":"The prefix places the amount above the line.","exampleCN":"这个前缀把数量放到所需线之上。"},{"word":"plus","structure":"Latin adjective/adverb, genitive pluris","meaning":"more","meaningCN":"更多","example":"The second piece supplies the idea of more.","exampleCN":"第二部分提供「更多」的意思。"},{"word":"surplus","structure":"super- + plus","meaning":"an amount over what is needed","meaningCN":"超出所需的量","example":"The cooperative stored its surplus grain.","exampleCN":"合作社存下了余粮。"},{"word":"superfluous","structure":"super- + fluere","meaning":"flowing over; unnecessary","meaningCN":"溢出；多余的","example":"A superfluous comment delayed the meeting.","exampleCN":"一句多余的话拖长了会议。"},{"word":"surplusage","structure":"surplus + -age","meaning":"an excess; needless matter","meaningCN":"剩余物；赘语","example":"The editor cut the surplusage.","exampleCN":"编辑删去了赘余部分。"},{"word":"surplus-value","structure":"surplus + value","meaning":"value beyond what labour is paid","meaningCN":"超出劳动报酬的价值","example":"The term belongs to nineteenth-century critique.","exampleCN":"这个术语属于十九世纪的批判理论。"},{"word":"plural","structure":"plus + -alis","meaning":"of more than one","meaningCN":"复数的","example":"Plural forms mark more than one item.","exampleCN":"复数形式标记不止一个事物。"},{"word":"surpluses","structure":"surplus + -es (plural)","meaning":"more than one remainder","meaningCN":"多处剩余","example":"Two surpluses followed in as many years.","exampleCN":"接连两年各出现一次剩余。"}],"latinEntries":[{"word":"plus","structure":"plus, pluris (adj., third declension)","meaning":"more","meaningCN":"更多"},{"word":"superplus","structure":"superplus, superpluris (adj., comparative)","meaning":"more than enough","meaningCN":"超过所需的"},{"word":"super","structure":"super (preposition and prefix)","meaning":"above, over","meaningCN":"在上；超过"}],"derivatives":[{"word":"surplusage","pos":"n.","zh":"剩余物；赘语"},{"word":"surplus-value","pos":"n.","zh":"剩余价值"},{"word":"surpluses","pos":"n.","zh":"剩余（复数）"},{"word":"surplus to requirements","pos":"phrase","zh":"富余的；不再需要的"}]}},{"word":"allocation","ipa_uk":"/ˌæləˈkeɪʃən/","ipa_us":"/ˌæləˈkeɪʃən/","definition_zh":"分配；配置；分摊；拨款；名额","definition_en":"the act of deciding how resources, tasks or money are shared out","core_image":"一张大饼被切成若干份，每份旁边都写着用途","scene":"项目组把有限的经费摊在桌上，按优先次序分给三个小组。The committee agreed on an allocation of funds to three research teams.","sceneCN":"项目组把有限经费摊在桌上，按优先次序分给三个小组；句中的 allocation 指「把资源按用途分给各方的行为」（第 1 个义项：把资源分开并派给不同对象）。图中可辨识物件：摊开的预算表、三只信封、计算器、白板。","pos":[{"tag":"n.","zh":"分配；配置；分摊；拨款；名额"}],"collocations":[{"phrase":"resource allocation","zh":"资源配置"},{"phrase":"budget allocation","zh":"预算分配"},{"phrase":"the allocation of tasks","zh":"任务分派"},{"phrase":"seat allocation","zh":"名额分配"},{"phrase":"memory allocation","zh":"内存分配"},{"phrase":"cost allocation","zh":"成本分摊"}],"forms":[{"label":"复数","form":"allocations"},{"label":"动词（分配）","form":"allocate"},{"label":"形容词（配置的）","form":"allocative"},{"label":"名词（分配者）","form":"allocator"}],"derivatives":[{"word":"allocate","pos":"v.","zh":"分配；拨给"},{"word":"allocative","pos":"adj.","zh":"配置的；分配的"},{"word":"allocator","pos":"n.","zh":"分配者；分配程序"},{"word":"reallocation","pos":"n.","zh":"重新分配"},{"word":"misallocation","pos":"n.","zh":"配置失当"}],"senses":[{"no":"01","title":"The act of sharing out resources","titleCN":"把资源分给各方的行为","definition":"the act of dividing something among several users or purposes","definitionCN":"把某物在多个使用者或用途之间分开的行为","example":"The committee agreed on an allocation of funds to three research teams.","exampleCN":"委员会同意把经费分配给三个研究团队。","why":"The Latin verb means to place something somewhere, so allocation is literally placing each part where it goes.","whyCN":"拉丁动词意为把某物放到某处，因此 allocation 字面上就是把每一份放到它该去的地方。"},{"no":"02","title":"Resource allocation in economics","titleCN":"经济学中的资源配置","definition":"the way an economy decides which goods and services get produced and who gets them","definitionCN":"一个经济体决定生产哪些商品与服务、由谁获得的方式","example":"Efficient resource allocation is the central question of the course.","exampleCN":"有效的资源配置是这门课的核心问题。","why":"Economics studies who gets what, and placing each part is exactly what the word describes.","whyCN":"经济学研究谁得到什么，而「把每一份放好」正是这个词所描述的。"},{"no":"03","title":"A budget line or grant","titleCN":"预算中的一项拨款","definition":"a sum of money set aside for a particular department or purpose","definitionCN":"为某部门或某用途专门留出的款项","example":"The library's allocation rose by five per cent.","exampleCN":"图书馆的拨款增加了百分之五。","why":"A grant is money placed at a destination, so the word shifts from the act to the sum assigned.","whyCN":"拨款就是把钱放到某个去处，因此词义从动作转到被指派的款额。"},{"no":"04","title":"Assigning duties to people","titleCN":"把任务分派给人","definition":"the assignment of jobs or responsibilities to particular people","definitionCN":"把工作或责任分给具体的人","example":"A clear allocation of duties prevented two people editing the same page.","exampleCN":"明确分派职责，避免了两人重复编辑同一页。","why":"Tasks are placed on people's desks, which extends the placing image from things to duties.","whyCN":"任务被放到各人的桌上，这把「安放」的意象从物品扩展到职责。"},{"no":"05","title":"A share of limited places","titleCN":"有限名额的分配","definition":"the distribution of limited places such as seats or school positions","definitionCN":"座位、学位等有限名额的分发","example":"The allocation of school places followed a new formula.","exampleCN":"学位名额按新公式分配。","why":"When places are scarce, sharing them out becomes a visible decision with rules.","whyCN":"当名额稀缺，如何分发就成了一件有规则、看得见的决定。"},{"no":"06","title":"Memory allocation in computing","titleCN":"计算机的内存分配","definition":"the process by which a program reserves memory for data","definitionCN":"程序为数据预留内存的过程","example":"A memory allocation error crashed the program.","exampleCN":"一次内存分配错误让程序崩溃。","why":"Computing reused the word because memory, like money, is a finite store that must be handed out.","whyCN":"计算机沿用这个词，因为内存和钱一样是有限存量，必须逐一派给。"},{"no":"07","title":"Cost allocation in accounting","titleCN":"会计中的成本分摊","definition":"the assignment of shared costs to the activities or products that caused them","definitionCN":"把共同成本分给造成这些成本的业务或产品","example":"Cost allocation put half the warehouse bill on the online orders.","exampleCN":"成本分摊把一半仓储费算到了网络订单上。","why":"Accounting places each cost on a product, which is the same gesture applied to figures.","whyCN":"会计把每笔成本放到某个产品上，是同一动作用在数字上。"},{"no":"08","title":"Rationing in times of shortage","titleCN":"短缺时期的定量配给","definition":"the controlled distribution of scarce goods to users, often by quota","definitionCN":"按配额把稀缺物资受控地分给使用者","example":"Wartime allocation of sugar limited each household to a small weekly amount.","exampleCN":"战时的食糖配给把每户每周限制在少量。","why":"Rationing is sharing out under pressure, so the word takes on the tone of scarcity.","whyCN":"配给就是压力下的分发，因此这个词带上稀缺的意味。"}],"etymology":{"intro":{"en":"Allocation comes from Medieval Latin allocatio, from allocare 'to place, assign', built on ad- 'to' and locus 'place'. English borrowed it in the sixteenth century.","cn":"allocation 来自中世纪拉丁 allocatio，源自动词 allocare「安放、指派」，由 ad-「向」与 locus「地方」构成，十六世纪进入英语。"},"items":[{"era":"LATIN LOCUS","en":"Locus meant 'place, position'. It gives local, locate, locality and dislocate.","cn":"locus 意为「地方、位置」，衍生 local、locate、locality 与 dislocate。"},{"era":"LATIN LOCARE","en":"Locare meant 'to place, set, station', turning the noun of place into a verb of putting.","cn":"locare 意为「放置、安顿、驻扎」，把表示地方的名词变成「放」的动词。"},{"era":"LATIN ALLOCARE","en":"Ad- 'to' plus locare gave allocare, 'to place something to someone, assign'.","cn":"ad-「向」加 locare 构成 allocare，意为「把某物放到某人处、指派」。"},{"era":"MEDIEVAL LATIN ALLOCATIO","en":"Allocatio, 'an assigning', was used in accounts and administration before English borrowed it.","cn":"allocatio「指派、分派」在英语借入之前已用于账目与行政。"},{"era":"SIXTEENTH-CENTURY ENGLISH","en":"English adopted the word in the 1500s for the setting aside of money or goods for a purpose.","cn":"英语在十六世纪吸收这个词，指为某用途留出钱或货。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: whether English took the noun directly from Latin or through French allocation is not settled, and the earliest date is approximate.","cn":"来源不确定：英语是直接从拉丁语借入，还是经法语 allocation 传入，尚无定论；最早年代也只是约数。"}]},"similar":{"note":{"en":"Group one holds words from the same place root that are easily confused with allocation; group two holds near terms for sharing out.","cn":"第一组是同出「地方」词根、易与 allocation 混淆的词；第二组是表示分发的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"location","ipa":"/ləʊˈkeɪʃən/","tag":"same root, place not share","definition":"A position or site, from the same place root; it names where something is, not how it is divided.","definitionCN":"位置或地点，同出「地方」词根；指某物在哪，不指如何分。"},{"word":"allotment","ipa":"/əˈlɒtmənt/","tag":"similar shape, different root","definition":"A share or a small plot assigned to someone, built on lot rather than locus; it is close in meaning but not a relative.","definitionCN":"分给某人的一份或一小块地，由 lot 而非 locus 构成；意思接近但不同源。"},{"word":"dislocate","ipa":"/dɪsˈləʊkeɪt/","tag":"same root, displacement","definition":"To move something out of its proper place, as a joint; it keeps the place image but reverses the fitting.","definitionCN":"把某物移出原位，如关节脱位；保留「地方」意象但把安放反过来。"},{"word":"allocution","ipa":"/ˌæləˈkjuːʃən/","tag":"different root","definition":"A formal speech, from loqui 'to speak'; the shared opening is misleading.","definitionCN":"正式讲话，来自 loqui「说话」；相同的开头容易误导。"}]},{"heading":"NEAR MEANING","entries":[{"word":"distribution","ipa":"/ˌdɪstrɪˈbjuːʃən/","tag":"broad word","definition":"The general word for spreading things among people or places; it does not imply a decision about shares.","definitionCN":"把东西分给人或地方的通用词；不含「决定份额」之意。"},{"word":"apportionment","ipa":"/əˈpɔːʃənmənt/","tag":"proportional split","definition":"The division of something in fixed proportions, often by rule; it stresses the ratio rather than the placing.","definitionCN":"按固定比例分，常依规则；强调比例而非安放。"},{"word":"assignment","ipa":"/əˈsaɪnmənt/","tag":"tasks and people","definition":"The giving of a task or a person to a role; it is the usual word when duties rather than funds are involved.","definitionCN":"把任务或人派到某角色；涉及职责而非资金时更常用。"},{"word":"rationing","ipa":"/ˈreɪʃənɪŋ/","tag":"scarcity control","definition":"Controlled distribution of scarce goods by quota; it is the emergency form of allocation.","definitionCN":"按配额受控地分发稀缺物资；是 allocation 的紧急形态。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the place root, the fixed phrases and the real family.","cn":"正常联想：「地方」词根、固定搭配与真实词族。"},"normal":[{"en":"Ad- 'to' plus locus 'place': to allocate is to put each part in its place.","cn":"ad-「向」加 locus「地方」：分配就是把每一份放到它的位置。"},{"en":"The family runs allocate, allocation, allocative, allocator, reallocation and misallocation.","cn":"同族词有 allocate、allocation、allocative、allocator、reallocation 与 misallocation。"},{"en":"Fixed phrases: resource allocation, budget allocation, seat allocation, cost allocation.","cn":"固定说法：资源配置、预算分配、名额分配、成本分摊。"},{"en":"The same root appears in local, locate, locality and dislocate.","cn":"同一词根出现在 local、locate、locality 与 dislocate 中。"},{"en":"A budget line is money placed at a destination, so the act and the sum share one word.","cn":"预算中的一项就是把钱放到某个去处，动作与款额因此共用一个词。"}],"abstract":[{"en":"Picture a cake cut into shares, each labelled with a name.","cn":"想象一块饼切成若干份，每份都写着名字。"},{"en":"Picture a shelf of identical boxes, each carried to a different desk.","cn":"想象一排放着相同盒子，每只被搬到不同的桌上。"},{"en":"Picture a limited row of chairs and a list deciding who sits where.","cn":"想象一排有限的椅子，一份名单决定谁坐哪里。"}]},"examples":[{"en":"The allocation of water between farms and towns is decided each spring.","cn":"农场与城镇之间的水量分配每年春天决定。"},{"en":"A fair allocation of seats gave every department two places.","cn":"公平的名额分配让每个部门得到两个位置。"},{"en":"Poor allocation of staff left the busiest ward short-handed.","cn":"人员配置不当让最忙的病区人手不足。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「al（向）+ location（位置）」——把东西一件件放到各自的位置，就是分配","word":"allocation"},"root":"中世纪拉丁 allocatio，来自 allocare「安放、指派」= ad-（向）+ locare「放置」，而 locare 出自 locus「地方」。","sensesIntro":{"en":"Eight senses follow one gesture, placing each part where it belongs: sharing resources, the economic question, a budget line, duties, limited places, computer memory, shared costs and finally wartime rations.","cn":"八个义项围绕同一个动作——把每一份放到该去的地方：分配资源、经济问题、预算拨款、职责、有限名额、计算机内存、共同成本，最后是战时配给。"},"semanticMap":{"core":{"en":"CORE IMAGE: a large cake cut into labelled shares, one for each purpose.","cn":"核心意象：一张大饼切成标好用途的若干份。"},"chain":["SHARE OUT","PLACE EACH PART","BUDGET LINES","TASKS ASSIGNED","SLOTS LIMITED","RATIONS"],"branches":[{"senses":"01 · 03","en":"ACT AND SUM: sharing out and the budget line it produces are one gesture seen as process and result.","cn":"动作与款额：分发行为与由此产生的预算项，是同一动作的过程与结果。"},{"senses":"02 · 07","en":"TWO ECONOMIES: resources and shared costs are both placed on someone's account.","cn":"两种经济：资源与共同成本，都被记到某方的账上。"},{"senses":"04 · 05","en":"PEOPLE AND PLACES: duties go to desks and places go to applicants, both by a decision.","cn":"人与位置：职责分到桌上，名额分到申请人，都靠一个决定。"},{"senses":"06","en":"MACHINE MEMORY: the computer hands out its finite store as money is handed out.","cn":"机器内存：计算机像分钱一样分发有限的存储。"},{"senses":"08","en":"SCARCITY: when goods run short, sharing becomes rationing.","cn":"稀缺：物资一紧张，分发就变成配给。"}]},"affixes":{"intro":{"en":"Allocation is a Latin verb of placing with a prefix that points it at someone, plus a noun ending.","cn":"allocation 是由「放置」的拉丁动词加指向某人的前缀，再加名词词尾构成。"},"latinIntro":{"en":"Latin locus and locare give allocate, location, local and dislocate; ad- directs the placing toward a recipient.","cn":"拉丁 locus 与 locare 衍生 allocate、location、local 与 dislocate；ad- 把「放」指向接受者。"},"items":[{"word":"ad-","structure":"Latin prefix (assimilating to al- before l)","meaning":"to, toward","meaningCN":"向；朝","example":"The prefix points the placing at a recipient.","exampleCN":"这个前缀把「放置」指向接受者。"},{"word":"locus","structure":"Latin noun, second declension","meaning":"place, position","meaningCN":"地方；位置","example":"The root supplies the idea of a spot.","exampleCN":"这个词根提供「地点」的意思。"},{"word":"locare","structure":"Latin verb, first conjugation","meaning":"to place, station","meaningCN":"放置；安顿","example":"The verb turns place into an action.","exampleCN":"这个动词把「地方」变成动作。"},{"word":"allocate","structure":"ad- + locare","meaning":"to assign, set aside","meaningCN":"分配；拨给","example":"The board allocated funds to two labs.","exampleCN":"董事会把经费分给两个实验室。"},{"word":"allocation","structure":"allocate + -ion (action or result)","meaning":"the act or result of assigning","meaningCN":"分配（动作或结果）","example":"The allocation was announced in June.","exampleCN":"分配方案在六月公布。"},{"word":"allocative","structure":"allocation + -ive","meaning":"relating to assignment","meaningCN":"配置的；分配的","example":"Allocative efficiency matters in health care.","exampleCN":"配置效率在医疗中很重要。"},{"word":"reallocation","structure":"re- + allocation","meaning":"a fresh sharing out","meaningCN":"重新分配","example":"Reallocation moved two posts to the new site.","exampleCN":"重新分配把两个岗位挪到新址。"},{"word":"misallocation","structure":"mis- + allocation","meaning":"a bad or wrong sharing out","meaningCN":"配置失当","example":"Misallocation wasted half the budget.","exampleCN":"配置失当浪费了一半预算。"}],"latinEntries":[{"word":"locus","structure":"locus, loci (m., second declension)","meaning":"place, spot","meaningCN":"地方；地点"},{"word":"locare","structure":"locare, locavi, locatum (verb, first conjugation)","meaning":"to place, set, station","meaningCN":"放置；安顿；驻扎"},{"word":"allocare","structure":"allocare, allocavi, allocatum (verb, first conjugation)","meaning":"to place to, assign","meaningCN":"分派；指派"}],"derivatives":[{"word":"allocate","pos":"v.","zh":"分配；拨给"},{"word":"allocative","pos":"adj.","zh":"配置的"},{"word":"reallocation","pos":"n.","zh":"重新分配"},{"word":"misallocation","pos":"n.","zh":"配置失当"}]}},{"word":"efficient","ipa_uk":"/ɪˈfɪʃənt/","ipa_us":"/ɪˈfɪʃənt/","definition_zh":"高效的；效率高的；（人）干练的；能胜任的","definition_en":"working well and producing the desired result without wasting time, money or effort","core_image":"一台机器把原料几乎全部变成成品，废料口只掉出一点碎屑","scene":"车间换了新流程之后，同样的原料做出了更多成品，废料也少了很多。The new process is far more efficient, turning the same raw material into twice the output.","sceneCN":"车间换了新流程，同样的原料做出更多成品，废料也少了很多；句中的 efficient 指「以更少耗费做出更多成果」（第 1 个义项：投入少而产出多）。图中可辨识物件：流水线、成品箱、废料槽、计时器。","pos":[{"tag":"adj.","zh":"高效的；效率高的；（人）干练的"}],"collocations":[{"phrase":"energy-efficient","zh":"节能的"},{"phrase":"cost-efficient","zh":"成本高效的"},{"phrase":"efficient use of sth","zh":"对某物的高效利用"},{"phrase":"highly efficient","zh":"非常高效的"},{"phrase":"efficient market","zh":"有效市场"},{"phrase":"efficient cause","zh":"动力因（哲学用语）"}],"forms":[{"label":"比较级","form":"more efficient"},{"label":"最高级","form":"most efficient"},{"label":"名词（效率）","form":"efficiency"},{"label":"副词（高效地）","form":"efficiently"},{"label":"名词复数（各种效率）","form":"efficiencies"}],"derivatives":[{"word":"efficiency","pos":"n.","zh":"效率"},{"word":"efficiently","pos":"adv.","zh":"高效地"},{"word":"inefficient","pos":"adj.","zh":"低效的"},{"word":"efficacious","pos":"adj.","zh":"有效的；奏效的"},{"word":"effectiveness","pos":"n.","zh":"有效性"}],"senses":[{"no":"01","title":"Producing results with little waste","titleCN":"耗费少而成果多","definition":"achieving the wanted result while using as little time, money or material as possible","definitionCN":"在尽可能少用时间、金钱或材料的情况下达到想要的结果","example":"The new process is far more efficient, turning the same raw material into twice the output.","exampleCN":"新流程效率高得多，同样的原料做出了两倍成品。","why":"The Latin verb means to accomplish, and the prefix points outward, so the word begins with getting the thing done.","whyCN":"拉丁动词意为「做成」，前缀又指向外，因此这个词起于「把事做出来」。"},{"no":"02","title":"A capable, well-organized person","titleCN":"干练有序的人","definition":"describing a person who works quickly and without confusion","definitionCN":"形容做事又快又不乱的一个人","example":"An efficient assistant had the files ready before the meeting.","exampleCN":"一位干练的助理在会前就把文件备好了。","why":"A person who wastes no motion is the machine image applied to human work.","whyCN":"不浪费动作的人，就是机器意象用在了人的工作上。"},{"no":"03","title":"High output for a machine","titleCN":"机器以单位投入换高产出的","definition":"describing a machine or system that gets a large result from a given input","definitionCN":"形容机器或系统以给定投入取得大量产出","example":"The new engine is efficient enough to cut fuel use by a third.","exampleCN":"新发动机效率高到能把油耗降低三分之一。","why":"Engineering measures output over input, which is the clearest form of the little-waste idea.","whyCN":"工程上用产出除以投入来衡量，这是「少浪费」最清晰的形态。"},{"no":"04","title":"Information in prices, market efficiency","titleCN":"价格已反映信息的市场有效","definition":"describing a market in which prices already reflect available information","definitionCN":"形容价格已反映可得信息的市场","example":"An efficient market leaves little room for easy profit.","exampleCN":"有效市场几乎不留轻松套利的空间。","why":"Economics borrows the word for markets that waste no available signal.","whyCN":"经济学借用这个词，指不浪费任何可得信号的市场。"},{"no":"05","title":"Good use of time","titleCN":"时间利用得当","definition":"describing a way of working that fits the most into the hours available","definitionCN":"形容在可用时间内安排下最多事情的做法","example":"A short agenda made the meeting surprisingly efficient.","exampleCN":"简短的议程让会议效率出奇地高。","why":"Time is another input, so saving it is the same calculation as saving material.","whyCN":"时间也是一种投入，省时间与省材料是同一套算法。"},{"no":"06","title":"The efficient cause in philosophy","titleCN":"哲学上的动力因","definition":"the agent or force that actually brings an effect about","definitionCN":"真正带来结果的施动者或力量","example":"Aristotle called the maker the efficient cause of the table.","exampleCN":"亚里士多德把制作者称为桌子的动力因。","why":"Here the word names the doing itself, which is the root sense before any talk of waste.","whyCN":"这里这个词指「做」本身，是谈论浪费之前的词根本义。"},{"no":"07","title":"Effective in getting a result","titleCN":"能奏效、解决问题","definition":"describing a method or measure that actually works","definitionCN":"形容方法或措施确实起作用","example":"A single form proved the most efficient solution to the queue.","exampleCN":"一张表格成了解决排队问题最奏效的办法。","why":"Efficient and effective overlap here: the deed gets done, and no extra step is needed.","whyCN":"这里 efficient 与 effective 意思重叠：事情办成了，也没有多余步骤。"},{"no":"08","title":"A service with few steps","titleCN":"手续少、不拖延的服务","definition":"describing an office or service that completes requests without unnecessary delay","definitionCN":"形容办事机构或服务没有多余拖延地完成请求","example":"The efficient service returned the permit in one visit.","exampleCN":"高效的服务一次就办好了许可证。","why":"Bureaucratic waste is measured in repeated steps, so a short path counts as efficient.","whyCN":"官僚浪费以重复步骤衡量，因此路径短就算高效。"}],"etymology":{"intro":{"en":"Efficient comes from Latin efficiens, the present participle of efficere 'to accomplish', built on ex- 'out' and facere 'to do, make'. English took it through French in the fourteenth century.","cn":"efficient 来自拉丁 efficiens，是动词 efficere「做成」的现在分词，由 ex-「出」与 facere「做、造」构成，十四世纪经法语进入英语。"},"items":[{"era":"LATIN FACERE","en":"Facere meant 'to do, make'. It gives fact, factory, effect, perfect, difficult and manufacture.","cn":"facere 意为「做、造」，衍生 fact、factory、effect、perfect、difficult 与 manufacture。"},{"era":"LATIN EFFICERE","en":"Ex- 'out' plus facere produced efficere, 'to work out, accomplish, bring about'.","cn":"ex-「出」加 facere 构成 efficere，意为「做出、完成、带来」。"},{"era":"LATIN EFFICIENS","en":"The present participle efficiens named the thing that brings a result about, which philosophy later called the efficient cause.","cn":"现在分词 efficiens 指带来结果的那个东西，哲学后来称之为动力因。"},{"era":"FOURTEENTH-CENTURY ENGLISH","en":"English adopted the adjective through French, at first for causes and agents that produce effects.","cn":"英语经法语吸收这个形容词，最初用于产生结果的原因与施动者。"},{"era":"INDUSTRIAL SENSE","en":"From the eighteenth and nineteenth centuries the word was applied to machines, engines and workers judged by output per input.","cn":"从十八、十九世纪起，这个词被用于按「产出比投入」来评判的机器、发动机与工人。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the exact first use of the mechanical sense is not recorded, and the date is approximate.","cn":"来源不确定：机械义的最早用例没有确切记录，年代只是约数。"}]},"similar":{"note":{"en":"Group one holds same-root words that are constantly confused with efficient; group two holds near adjectives for working well.","cn":"第一组是同根且常与 efficient 混淆的词；第二组是表示「运作良好」的近义形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"effective","ipa":"/ɪˈfektɪv/","tag":"same root, result not waste","definition":"From the same verb: it asks whether the result was achieved, not whether few resources were spent.","definitionCN":"同出这一动词：它问结果是否达成，不问耗费是否少。"},{"word":"efficacious","ipa":"/ˌefɪˈkeɪʃəs/","tag":"same root, medical","definition":"Same root, used chiefly of remedies that produce the intended cure; it is narrower than efficient.","definitionCN":"同根，主要用于产生预期疗效的药物；范围比 efficient 窄。"},{"word":"efficiency","ipa":"/ɪˈfɪʃənsi/","tag":"the noun","definition":"The noun of the same adjective, naming the ratio of output to input rather than describing a thing.","definitionCN":"同一形容词的名词，指产出与投入的比值，而非形容某物。"},{"word":"effect","ipa":"/ɪˈfekt/","tag":"the result","definition":"The outcome produced; it is the thing the efficient agent brings about, not the agent itself.","definitionCN":"产生的结果；是高效施动者带来的东西，不是施动者本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"economical","ipa":"/ˌiːkəˈnɒmɪkəl/","tag":"money focus","definition":"Saving money or resources; it stresses low cost, while efficient stresses low waste for high output.","definitionCN":"省钱省资源；侧重成本低，而 efficient 侧重低浪费高产出。"},{"word":"productive","ipa":"/prəˈdʌktɪv/","tag":"output focus","definition":"Producing a lot; it measures how much comes out, not how little went in.","definitionCN":"产出很多；衡量出来多少，而非投入多少。"},{"word":"streamlined","ipa":"/ˈstriːmlaɪnd/","tag":"process shape","definition":"Made simple and smooth by removing steps; it describes the design that makes efficiency possible.","definitionCN":"通过删减步骤变得简洁顺畅；描述使高效成为可能的设计。"},{"word":"competent","ipa":"/ˈkɒmpɪtənt/","tag":"person judgement","definition":"Good enough to do the job properly; it is a minimum standard, while efficient implies speed and little waste.","definitionCN":"足以胜任；是及格线，而 efficient 含快速与少浪费。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the do-root, the fixed phrases and the same-root family.","cn":"正常联想：「做」的词根、固定搭配与同根词族。"},"normal":[{"en":"Ex- 'out' plus facere 'do': efficient work gets the thing done and out.","cn":"ex-「出」加 facere「做」：高效的工作把东西做出来、做出去。"},{"en":"The family runs efficient, efficiency, efficiently, inefficient and efficacious.","cn":"同族词有 efficient、efficiency、efficiently、inefficient 与 efficacious。"},{"en":"Fixed phrases: energy-efficient, cost-efficient, efficient use of time, efficient market.","cn":"固定说法：节能的、成本高效的、时间的高效利用、有效市场。"},{"en":"The same root appears in effect, effective, factory and manufacture.","cn":"同一词根出现在 effect、effective、factory 与 manufacture 中。"},{"en":"Philosophy keeps the older sense in efficient cause, the force that does the work.","cn":"哲学用动力因保留了较早的词义，即真正做功的那股力量。"}],"abstract":[{"en":"Picture a machine whose scrap bin stays almost empty all day.","cn":"想象一台机器，废料箱一整天几乎都是空的。"},{"en":"Picture a clock hand that never pauses between tasks.","cn":"想象一根钟表指针，在任务之间从不停顿。"},{"en":"Picture a queue that moves because nobody repeats a form twice.","cn":"想象一支队伍之所以在动，是因为没人把表格填两遍。"}]},"examples":[{"en":"LED bulbs are more efficient than the old filament lamps.","cn":"发光二极管灯泡比旧式灯丝灯泡更高效。"},{"en":"An efficient team finishes the weekly report by Friday noon.","cn":"高效的团队周五中午就交上周报。"},{"en":"The study asks whether the market is truly efficient.","cn":"这项研究追问市场是否真的有效。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「e（出）+ fic（做）+ ient」——把事做出来且不浪费，就是高效","word":"efficient"},"root":"拉丁 efficiens「做出的、完成的」，来自 efficere = ex-（出）+ facere「做、造」；经法语进入英语。","sensesIntro":{"en":"Eight senses follow one idea, getting the result without waste: a process, a person, a machine, a market, time use, a philosophical cause, a working method and a short service path.","cn":"八个义项围绕一个想法——不浪费地把结果拿到：流程、人、机器、市场、时间、哲学原因、奏效的方法，以及简短的服务路径。"},"semanticMap":{"core":{"en":"CORE IMAGE: a machine turning nearly all its input into finished product, with almost no scrap.","cn":"核心意象：一台机器把几乎全部投入变成成品，几乎没有废料。"},"chain":["LITTLE WASTE","GOOD OUTPUT","CAPABLE PERSON","MARKET SIGNAL","SAVING TIME","CAUSE THAT ACTS"],"branches":[{"senses":"01 · 03","en":"OUTPUT OVER INPUT: the general saving of waste and the machine's ratio are one measurement.","cn":"产出比投入：总体少浪费与机器的比值，是同一种度量。"},{"senses":"02 · 07","en":"CAPABILITY: a person who wastes no motion and a method that actually works both get the job done.","cn":"能力：不浪费动作的人与确实奏效的方法，都把事办成。"},{"senses":"04 · 08","en":"SYSTEMS: a market that absorbs all signals and an office that removes steps are efficient in the same way.","cn":"系统：吸收全部信号的市场与删去多余步骤的窗口，以同样方式高效。"},{"senses":"05","en":"TIME AS INPUT: fitting more into the same hours is the same calculation.","cn":"时间也是投入：在同样工时里塞进更多事，是同一套算法。"},{"senses":"06","en":"CAUSE: the older sense names the doing itself, before any waste is counted.","cn":"原因：较早的词义指「做」本身，尚未计入任何浪费。"}]},"affixes":{"intro":{"en":"Efficient is a Latin participle from a prefix and a do-root, and the root builds a large English family.","cn":"efficient 是由前缀与「做」词根构成的拉丁分词，这个词根构成了一大片英语词族。"},"latinIntro":{"en":"Latin facere gives effect, factory, perfect and manufacture; ex- adds the direction of working something out.","cn":"拉丁 facere 衍生 effect、factory、perfect 与 manufacture；ex- 增添「做出」的方向。"},"items":[{"word":"ex-","structure":"Latin prefix (assimilating to ef- before f)","meaning":"out, thoroughly","meaningCN":"出；彻底","example":"The prefix points the doing outward into a result.","exampleCN":"这个前缀把「做」指向外，成为结果。"},{"word":"facere","structure":"Latin verb, third conjugation","meaning":"to do, make","meaningCN":"做；造","example":"The root carries the act of making.","exampleCN":"这个词根带着「造」的动作。"},{"word":"efficere","structure":"ex- + facere","meaning":"to accomplish, bring about","meaningCN":"完成；带来","example":"The verb means working something out.","exampleCN":"这个动词意为把某事做出来。"},{"word":"efficient","structure":"efficere + -ent (present participle)","meaning":"bringing a result about","meaningCN":"带来结果的；高效的","example":"The engine proved remarkably efficient.","exampleCN":"这台发动机效率极高。"},{"word":"efficiency","structure":"efficient + -cy","meaning":"the ratio of output to input","meaningCN":"效率","example":"Efficiency rose after the redesign.","exampleCN":"重新设计后效率提高了。"},{"word":"effect","structure":"ex- + facere + -tum","meaning":"the result produced","meaningCN":"结果；效果","example":"The change had an immediate effect.","exampleCN":"这一改动立刻见效。"},{"word":"effective","structure":"effect + -ive","meaning":"able to produce a result","meaningCN":"有效的","example":"The remedy was effective within a day.","exampleCN":"这种疗法一天内见效。"},{"word":"factory","structure":"facere + -ory (place)","meaning":"a place where things are made","meaningCN":"工厂","example":"The factory ran three shifts.","exampleCN":"工厂开三班。"},{"word":"manufacture","structure":"manu 'hand' + facere","meaning":"to make by hand or machine","meaningCN":"制造","example":"They manufacture parts for turbines.","exampleCN":"他们制造涡轮机零件。"}],"latinEntries":[{"word":"facere","structure":"facere, feci, factum (verb, third conjugation)","meaning":"to do, make","meaningCN":"做；造"},{"word":"efficere","structure":"efficere, effeci, effectum (verb, third conjugation)","meaning":"to accomplish, bring about","meaningCN":"完成；带来"},{"word":"efficiens","structure":"efficiens, efficientis (present participle)","meaning":"bringing about, effective","meaningCN":"带来的；奏效的"}],"derivatives":[{"word":"efficiency","pos":"n.","zh":"效率"},{"word":"efficiently","pos":"adv.","zh":"高效地"},{"word":"inefficient","pos":"adj.","zh":"低效的"},{"word":"efficacious","pos":"adj.","zh":"有效的；奏效的"}]}},{"word":"inefficiency","ipa_uk":"/ˌɪnɪˈfɪʃənsi/","ipa_us":"/ˌɪnɪˈfɪʃənsi/","definition_zh":"低效；效率低下；浪费；低效之处（复数）","definition_en":"the quality of working badly, so that time, money or effort is wasted","core_image":"同一条流水线上原料堆成小山，成品却只有几箱，废料口不断掉渣","scene":"审计员发现，同一条审批流程要在三个窗口重复排号，办事的人来回跑。The audit blamed bureaucratic inefficiency for the repeated queues.","sceneCN":"审计员发现同一条审批流程要在三个窗口重复排号，办事的人来回跑；句中的 inefficiency 指「耗费多而成果少的状态」（第 1 个义项：资源未被有效利用）。图中可辨识物件：三个窗口、重复的排号单、来回走的人、审计夹板。","pos":[{"tag":"n.","zh":"低效；效率低下；低效之处（复数 inefficiencies）"}],"collocations":[{"phrase":"economic inefficiency","zh":"经济低效"},{"phrase":"energy inefficiency","zh":"能源利用低效"},{"phrase":"bureaucratic inefficiency","zh":"官僚低效"},{"phrase":"reduce inefficiency","zh":"减少低效"},{"phrase":"inefficiencies in the system","zh":"体系中的低效之处"},{"phrase":"technical inefficiency","zh":"技术低效"}],"forms":[{"label":"复数","form":"inefficiencies"},{"label":"形容词（低效的）","form":"inefficient"},{"label":"副词（低效地）","form":"inefficiently"},{"label":"反义名词（效率）","form":"efficiency"}],"derivatives":[{"word":"inefficient","pos":"adj.","zh":"低效的"},{"word":"inefficiently","pos":"adv.","zh":"低效地"},{"word":"efficiency","pos":"n.","zh":"效率（反义同根）"},{"word":"cost-inefficiency","pos":"n.","zh":"成本上的低效"}],"senses":[{"no":"01","title":"Failure to use resources well","titleCN":"资源未被有效利用","definition":"a condition in which time, money or effort is spent without producing the result it should","definitionCN":"时间、金钱或精力花了出去，却没有产生应有的结果","example":"The audit blamed bureaucratic inefficiency for the repeated queues.","exampleCN":"审计把重复排队归咎于官僚低效。","why":"The word is simply the negative of efficiency, so it names the absence of result for the effort spent.","whyCN":"这个词就是 efficiency 的反义形式，因此指花费了力气却没有结果。"},{"no":"02","title":"Misallocation in economics","titleCN":"经济学中的配置低效","definition":"a market outcome in which resources go to less valuable uses than they could","definitionCN":"资源流向价值较低的用途、本可更优的市场结果","example":"Subsidies for outdated plants created long-run inefficiency.","exampleCN":"补贴过时工厂造成了长期配置低效。","why":"Economics measures inefficiency as value lost by placing resources in the wrong use.","whyCN":"经济学把低效衡量为「资源放错用途而损失的价值」。"},{"no":"03","title":"Red tape in an organization","titleCN":"组织中的繁文缛节","definition":"wasted effort caused by duplicated forms, approvals and procedures","definitionCN":"重复的表格、审批与程序造成的浪费","example":"Staff cuts removed layers but left the inefficiency untouched.","exampleCN":"裁员去掉了层级，却没能动到低效本身。","why":"An organization is judged like a machine, and repeated steps are the scrap it throws off.","whyCN":"组织像机器一样被评判，重复的步骤就是它甩出的废料。"},{"no":"04","title":"Energy wasted in conversion","titleCN":"能源转换中的浪费","definition":"the share of energy input lost as heat or other unusable output","definitionCN":"能量投入中以热或其他无用产出形式损失的部分","example":"Old boilers were singled out for their energy inefficiency.","exampleCN":"旧锅炉因能源低效被特别指出。","why":"Physics states the idea numerically: useful output divided by input, with the rest counted as loss.","whyCN":"物理学用数字表述这个想法：有用产出除以投入，其余算作损失。"},{"no":"05","title":"Production below the possible frontier","titleCN":"生产低于可达到的效率前沿","definition":"the gap between actual output and the output achievable with the same inputs","definitionCN":"同样投入下，实际产出与可达到产出之间的差距","example":"The study measured technical inefficiency across forty factories.","exampleCN":"这项研究测算了四十家工厂的技术低效。","why":"If a frontier of best practice exists, falling short of it is the precise meaning of inefficiency.","whyCN":"若存在最佳实践的前沿，达不到前沿正是「低效」的精确含义。"},{"no":"06","title":"Specific wasteful practices","titleCN":"具体的一处处浪费","definition":"countable instances of waste inside an otherwise working system","definitionCN":"一个本可运转的体系中可数的一处处浪费","example":"The report listed seven inefficiencies, from double entry to idle trucks.","exampleCN":"报告列出七处低效，从重复录入到闲置卡车。","why":"The plural turns an abstract quality into a checklist of things that can be fixed one by one.","whyCN":"复数把抽象性质变成一张可逐条整改的清单。"},{"no":"07","title":"Prices that ignore information","titleCN":"价格未能反映信息","definition":"a market failure in which prices do not carry the information participants already have","definitionCN":"价格未能传递参与者已有信息的市场失灵","example":"Thin trading produced an inefficiency that arbitrageurs quickly exploited.","exampleCN":"交易清淡造成一种低效，套利者很快加以利用。","why":"A market that fails to absorb available signals wastes them, which is the informational form of waste.","whyCN":"市场没能吸收可得信号，就是浪费了这些信号，属信息形态的浪费。"},{"no":"08","title":"Wasted motion inside a process","titleCN":"流程内部的多余动作","definition":"the extra steps a process forces on people who use it","definitionCN":"流程强加给使用者的多余步骤","example":"Walking between three desks was the clearest inefficiency in the office.","exampleCN":"在三个柜台之间来回走，是办公室里最明显的低效。","why":"The word follows the process, not the person: the waste is built into the route.","whyCN":"这个词跟着流程走，而不是跟着人走：浪费被设计进了路线。"}],"etymology":{"intro":{"en":"Inefficiency is the English noun of negation in- plus efficiency, itself from Latin efficientia, from efficere 'to accomplish'. The negative form is a nineteenth-century coinage.","cn":"inefficiency 是拉丁否定前缀 in- 加 efficiency 构成的英语名词，而 efficiency 来自拉丁 efficientia，源自动词 efficere「做成」；否定形式是十九世纪的新造词。"},"items":[{"era":"LATIN FACERE","en":"Facere meant 'to do, make'. Through efficere it reaches efficiency and every word in this family.","cn":"facere 意为「做、造」，经 efficere 通向 efficiency 及这一词族的每个词。"},{"era":"LATIN EFFICIENTIA","en":"Efficientia named the power or action of accomplishing something; the modern ratio sense came later.","cn":"efficientia 指「完成某事的能力或作用」，现代的比例义出现较晚。"},{"era":"SIXTEENTH-CENTURY EFFICIENCY","en":"English adopted efficiency in the sixteenth century, at first as the fact of producing an effect.","cn":"英语在十六世纪吸收 efficiency，最初指「产生效果」这一事实。"},{"era":"LATIN NEGATION IN-","en":"The prefix in-, 'not', is the same one that forms inactive and inaccurate; before some consonants it changes shape, as in impossible.","cn":"否定前缀 in- 也构成 inactive 与 inaccurate；在某些辅音前会变形，如 impossible。"},{"era":"NINETEENTH-CENTURY COINAGE","en":"Industrial accounting and engineering gave the negative noun its modern sense: measurable loss of output for a given input.","cn":"工业会计与工程学赋予这个否定名词现代义：给定投入下可测量的产出损失。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the first written use of the negative noun is not firmly dated, and the year is approximate.","cn":"来源不确定：这个否定名词的最早书面用例没有确切年代，给出的年份只是约数。"}]},"similar":{"note":{"en":"Group one holds negated words easily mistaken for inefficiency; group two holds near terms for waste in a system.","cn":"第一组是带否定前缀、容易与 inefficiency 混淆的词；第二组是表示体系内浪费的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"inefficacy","ipa":"/ɪnˈefɪkəsi/","tag":"no effect at all","definition":"The state of producing no effect whatever, as a medicine that does nothing; inefficiency concerns cost, this concerns result.","definitionCN":"完全不产生效果的状态，如毫无作用的药；inefficiency 关心耗费，这个词关心结果。"},{"word":"ineffectiveness","ipa":"/ˌɪnɪˈfektɪvnəs/","tag":"result not achieved","definition":"Failure to achieve the intended result; a method can be ineffective without being wasteful.","definitionCN":"未能达成预期结果；方法可能无效却不浪费。"},{"word":"insufficiency","ipa":"/ˌɪnsəˈfɪʃənsi/","tag":"different root","definition":"Not enough in amount, from a different root meaning to suffice; it is about quantity, not waste.","definitionCN":"数量不够，来自另一表示「足够」的词根；说的是数量而非浪费。"},{"word":"inefficient","ipa":"/ˌɪnɪˈfɪʃənt/","tag":"the adjective","definition":"The adjective form, describing the thing itself rather than naming the quality.","definitionCN":"形容词形式，形容事物本身，而非给这种性质命名。"}]},{"heading":"NEAR MEANING","entries":[{"word":"waste","ipa":"/weɪst/","tag":"plain word","definition":"The everyday word for material or effort thrown away; inefficiency is the measured, systemic version.","definitionCN":"指被丢弃的材料或精力的日常词；inefficiency 是可测量、系统化的版本。"},{"word":"slack","ipa":"/slæk/","tag":"unused capacity","definition":"Capacity that exists but is not used, such as idle machines or hours; it is unused potential rather than poor use.","definitionCN":"存在却未使用的产能，如闲置机器或工时；是未用潜力而非使用不当。"},{"word":"dysfunction","ipa":"/dɪsˈfʌŋkʃən/","tag":"broken operation","definition":"A failure in how a system operates, often organizational; it can cause inefficiency but is not the same thing.","definitionCN":"系统运作上的失灵，常指组织层面；可能导致低效，但不等于低效。"},{"word":"drag","ipa":"/dræɡ/","tag":"growth metaphor","definition":"Something that slows progress, as in fiscal drag; it names the slowing effect rather than the wasted resources.","definitionCN":"拖慢进展的因素，如财政拖累；指拖慢效应，而非浪费的资源。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the negation, the do-root and the fixed phrases.","cn":"正常联想：否定前缀、「做」的词根与固定搭配。"},"normal":[{"en":"In- 'not' plus efficiency: the result does not come out of the effort put in.","cn":"in-「不」加 efficiency：投入的力气没有变成结果。"},{"en":"The family runs inefficient, inefficiently, efficiency and cost-inefficiency.","cn":"同族词有 inefficient、inefficiently、efficiency 与 cost-inefficiency。"},{"en":"Fixed phrases: bureaucratic inefficiency, energy inefficiency, technical inefficiency.","cn":"固定说法：官僚低效、能源低效、技术低效。"},{"en":"The same negative prefix appears in inactive, inaccurate and impossible.","cn":"同一否定前缀出现在 inactive、inaccurate 与 impossible 中。"},{"en":"The plural, inefficiencies, is a checklist of wasteful practices to remove.","cn":"复数形式 inefficiencies 是一张可逐条清除的浪费清单。"}],"abstract":[{"en":"Picture a pipe that leaks most of what it carries before reaching the tap.","cn":"想象一根管子，还没到水龙头就把大半的水漏掉了。"},{"en":"Picture three windows in a row where one would do.","cn":"想象一排三个窗口，其实一个就够。"},{"en":"Picture a form that asks the same question on two pages.","cn":"想象一张表格，在两页上问同一个问题。"}]},"examples":[{"en":"Bureaucratic inefficiency delayed the permits by months.","cn":"官僚低效让许可证拖了几个月。"},{"en":"Old heating systems are a common source of energy inefficiency.","cn":"旧供暖系统是能源低效的常见来源。"},{"en":"The review found several inefficiencies that could be removed at no cost.","cn":"审查发现几处可以零成本消除的低效。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「in（不）+ efficiency（效率）」——效率不在场，就是低效与浪费","word":"inefficiency"},"root":"英语否定前缀 in-（不）加 efficiency；efficiency 来自拉丁 efficientia，源自动词 efficere = ex- + facere「做」。","sensesIntro":{"en":"Eight senses follow one shortfall: resources badly used, misallocated capital, red tape, lost energy, output below the frontier, listed waste, prices that ignore information and extra steps in a process.","cn":"八个义项围绕同一种不足：资源用得不好、资本配置失当、繁文缛节、能量损失、产出低于前沿、逐条列出的浪费、价格无视信息，以及流程中的多余步骤。"},"semanticMap":{"core":{"en":"CORE IMAGE: a production line where raw material piles up and finished goods barely fill one crate.","cn":"核心意象：一条流水线，原料堆成山，成品却装不满一箱。"},"chain":["WASTE","LOW OUTPUT","RED TAPE","EXTRA STEPS","LOST OUTPUT","MARKET BLINDSPOT"],"branches":[{"senses":"01 · 04","en":"WASTE OF INPUT: money, effort and energy all disappear without becoming result.","cn":"投入的浪费：钱、力气与能量都在没有变成结果的情况下消失。"},{"senses":"02 · 07","en":"MISPLACEMENT: resources in the wrong use and prices blind to information are both value lost.","cn":"错置：资源放错用途与价格看不见信息，都是价值损失。"},{"senses":"03 · 08","en":"STEPS: red tape and repeated trips are the same waste built into a procedure.","cn":"步骤：繁文缛节与来回奔波，是同一种被设计进程序里的浪费。"},{"senses":"05","en":"FRONTIER: with best practice as a line, falling short of it becomes measurable.","cn":"前沿：以最佳实践为线，达不到线就成了可测量的事。"},{"senses":"06","en":"CHECKLIST: the plural turns the quality into items that can be fixed one at a time.","cn":"清单：复数把这种性质变成可逐项整改的条目。"}]},"affixes":{"intro":{"en":"The word is one negative prefix on top of an English noun that itself comes from a Latin do-verb.","cn":"这个词是在一个英语名词上再加否定前缀，而那个名词本身来自拉丁「做」动词。"},"latinIntro":{"en":"Latin in- supplies the negation; facere and efficere supply efficiency and the whole family behind it.","cn":"拉丁 in- 提供否定；facere 与 efficere 提供 efficiency 及其背后的整个词族。"},"items":[{"word":"in-","structure":"Latin negative prefix","meaning":"not","meaningCN":"不","example":"The prefix turns efficiency into its opposite.","exampleCN":"这个前缀把 efficiency 变成它的反面。"},{"word":"facere","structure":"Latin verb, third conjugation","meaning":"to do, make","meaningCN":"做；造","example":"The root carries the act of making.","exampleCN":"这个词根带着「造」的动作。"},{"word":"efficere","structure":"ex- + facere","meaning":"to accomplish","meaningCN":"完成","example":"The verb sits behind efficiency.","exampleCN":"这个动词位于 efficiency 背后。"},{"word":"efficiency","structure":"efficient + -cy","meaning":"output for a given input","meaningCN":"给定投入下的产出","example":"Efficiency fell after the merger.","exampleCN":"合并之后效率下降了。"},{"word":"inefficiency","structure":"in- + efficiency","meaning":"waste for a given input","meaningCN":"给定投入下的浪费","example":"The report measured inefficiency in hours.","exampleCN":"报告以工时衡量低效。"},{"word":"inefficient","structure":"in- + efficient","meaning":"working with waste","meaningCN":"低效的","example":"The old pump was inefficient.","exampleCN":"旧水泵效率很低。"},{"word":"inefficiently","structure":"inefficient + -ly","meaning":"in a wasteful way","meaningCN":"低效地","example":"The forms were processed inefficiently.","exampleCN":"这些表格处理得很低效。"},{"word":"cost-inefficiency","structure":"cost + inefficiency","meaning":"waste measured in money","meaningCN":"成本上的低效","example":"Cost-inefficiency showed up in the audit.","exampleCN":"成本低效在审计中显现出来。"}],"latinEntries":[{"word":"facere","structure":"facere, feci, factum (verb, third conjugation)","meaning":"to do, make","meaningCN":"做；造"},{"word":"efficere","structure":"efficere, effeci, effectum (verb, third conjugation)","meaning":"to accomplish","meaningCN":"完成；做成"},{"word":"efficientia","structure":"efficientia, efficientiae (f., first declension)","meaning":"efficiency, accomplishing power","meaningCN":"效率；成事之力"}],"derivatives":[{"word":"inefficient","pos":"adj.","zh":"低效的"},{"word":"inefficiently","pos":"adv.","zh":"低效地"},{"word":"efficiency","pos":"n.","zh":"效率"},{"word":"cost-inefficiency","pos":"n.","zh":"成本低效"}]}},{"word":"production","ipa_uk":"/prəˈdʌkʃən/","ipa_us":"/prəˈdʌkʃən/","definition_zh":"生产；产量；制作；（作品的）上演；生成","definition_en":"the process of making goods, or the amount made","core_image":"一条流水线把原料一路推成成品，末端的成品箱不断堆高","scene":"工厂把旧线改成两班倒之后，一个月的成品数量翻了一倍。After the second shift was added, monthly production doubled.","sceneCN":"工厂把旧线改成两班倒，一个月的成品数量翻了一倍；句中的 production 指「把原料制成成品的过程及其产出」（第 1 个义项：制造商品的活动）。图中可辨识物件：流水线、成品箱、排班表、计数器。","pos":[{"tag":"n.","zh":"生产；产量；制作；上演；生成"}],"collocations":[{"phrase":"production line","zh":"生产线"},{"phrase":"mass production","zh":"批量生产"},{"phrase":"production costs","zh":"生产成本"},{"phrase":"in production","zh":"在生产中；在拍摄中"},{"phrase":"oil production","zh":"石油产量"},{"phrase":"food production","zh":"粮食生产"}],"forms":[{"label":"复数","form":"productions"},{"label":"动词（生产）","form":"produce"},{"label":"名词（生产者）","form":"producer"},{"label":"形容词（多产的）","form":"productive"},{"label":"名词（生产率）","form":"productivity"}],"derivatives":[{"word":"produce","pos":"v./n.","zh":"生产；农产品"},{"word":"producer","pos":"n.","zh":"生产者；制片人"},{"word":"productive","pos":"adj.","zh":"多产的；有成效的"},{"word":"productivity","pos":"n.","zh":"生产率"},{"word":"reproduction","pos":"n.","zh":"再生产；繁殖"}],"senses":[{"no":"01","title":"The making of goods","titleCN":"把原料制成成品","definition":"the activity of making goods from materials, especially in large amounts","definitionCN":"用材料制造商品的活动，尤指大量制造","example":"After the second shift was added, monthly production doubled.","exampleCN":"加上第二班之后，月产量翻了一倍。","why":"The Latin verb means to lead forward, so the word begins as bringing something out into being.","whyCN":"拉丁动词意为「向前引出」，因此这个词起于「把东西带出来、造出来」。"},{"no":"02","title":"The amount produced","titleCN":"产量","definition":"the total quantity of something made in a given period","definitionCN":"某段时期内造出的总量","example":"Rice production reached a ten-year high.","exampleCN":"稻米产量达到十年来的最高点。","why":"The noun of the process slides into naming its result, so production can be a number.","whyCN":"过程名词滑向指结果，因此 production 可以是一个数字。"},{"no":"03","title":"Economic output of goods and services","titleCN":"经济意义上的商品与服务产出","definition":"the creation of goods and services measured as a whole economy's activity","definitionCN":"作为整体经济活动衡量的商品与服务创造","example":"The region's production grew faster than its population.","exampleCN":"该地区的产出增长快于人口增长。","why":"Economics treats the whole making activity as one quantity, which is this sense.","whyCN":"经济学把全部制造活动当作一个量，这就是此义。"},{"no":"04","title":"Staging a play or film","titleCN":"戏剧或影视的排演制作","definition":"the work of preparing and presenting a play, film or programme","definitionCN":"筹备并呈现戏剧、电影或节目的工作","example":"Production on the film took fourteen months.","exampleCN":"这部电影的制作花了十四个月。","why":"A play is brought out before an audience, which is the same leading-forward image in culture.","whyCN":"戏剧被带到观众面前，与文化领域的「引出」意象相同。"},{"no":"05","title":"Bringing forth knowledge or results","titleCN":"产生知识或成果","definition":"the act of generating ideas, evidence or results rather than goods","definitionCN":"产生想法、证据或成果而非货物的行为","example":"The lab's production of reliable data made the review possible.","exampleCN":"实验室产出可靠数据，才使这次评审成为可能。","why":"Anything brought into existence can be produced, so the word extends from factories to research.","whyCN":"任何被带进存在的东西都可被「生产」，因此这个词从工厂延伸到研究。"},{"no":"06","title":"A bodily substance generated","titleCN":"生物体内生成物质","definition":"the generation of a substance by a living body, such as a hormone","definitionCN":"活体生成某种物质，如激素","example":"Stress increases the production of cortisol.","exampleCN":"压力会增加皮质醇的生成。","why":"Biology keeps the core meaning of bringing something forth, with no factory involved.","whyCN":"生物学保留「带出某物」的核心义，却不涉及工厂。"},{"no":"07","title":"The stage of being made","titleCN":"处于制造或拍摄阶段","definition":"the stage at which something is being manufactured or filmed","definitionCN":"某物正在被制造或拍摄的阶段","example":"The new model is in production but not yet on sale.","exampleCN":"新车型已在生产，但尚未开售。","why":"The phrase in production names a phase of the process, which is why it takes a fixed preposition.","whyCN":"in production 指过程的一个阶段，因此配固定介词。"},{"no":"08","title":"A particular staged work","titleCN":"一部具体的出品","definition":"a single play, film or show as staged by a company","definitionCN":"某团体排演的一部戏、电影或节目","example":"The festival opened with a new production of the opera.","exampleCN":"艺术节以这部歌剧的新制作开幕。","why":"The process noun finally stands for one finished work, a countable product of the stage.","whyCN":"过程名词最终指一部成品，成为舞台上可数的产物。"}],"etymology":{"intro":{"en":"Production comes from Latin productio, 'a bringing forth', from producere 'to lead forward', built on pro- 'forward' and ducere 'to lead'. English took it through French in the fifteenth century.","cn":"production 来自拉丁 productio「带出、引出」，源自动词 producere「向前引出」，由 pro-「向前」与 ducere「引导」构成，十五世纪经法语进入英语。"},"items":[{"era":"LATIN DUCERE","en":"Ducere meant 'to lead, draw'. It gives duct, conduct, introduce, reduce and educate.","cn":"ducere 意为「引导、拉」，衍生 duct、conduct、introduce、reduce 与 educate。"},{"era":"LATIN PRODUCERE","en":"Pro- 'forward' plus ducere produced producere, 'to lead or bring forward, to bring out'.","cn":"pro-「向前」加 ducere 构成 producere，意为「向前引出、带出」。"},{"era":"LATIN PRODUCTIO","en":"Productio named a bringing forth or a stretching out; the sense of making goods grew later.","cn":"productio 指「带出、拉长」；制造货物的意思出现较晚。"},{"era":"FIFTEENTH-CENTURY ENGLISH","en":"English adopted production through French, at first for bringing something into existence rather than for factories.","cn":"英语经法语吸收 production，最初指使某物产生，而非工厂制造。"},{"era":"INDUSTRIAL SENSE","en":"Eighteenth- and nineteenth-century industry fixed the modern sense: the making of goods in quantity, measured as output.","cn":"十八、十九世纪的工业固定了现代义：大量制造货物，并以产出计量。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: whether the noun came directly from Latin or through French is not settled, and the earliest date is approximate.","cn":"来源不确定：这个名词是直接来自拉丁语还是经法语传入，尚无定论；最早年代也是约数。"}]},"similar":{"note":{"en":"Group one holds words from the same lead-forward root that are easily confused; group two holds near words for making and output.","cn":"第一组是同出「向前引出」词根、易混的词；第二组是表示制造与产出的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"product","ipa":"/ˈprɒdʌkt/","tag":"the thing, not the act","definition":"Same root: the thing that results, while production is the activity or the total amount.","definitionCN":"同根：指产生的那件东西，而 production 指活动或总量。"},{"word":"produce","ipa":"/prəˈdjuːs/","tag":"the verb and farm goods","definition":"The verb of making, and as a noun farm goods; it is the action behind production.","definitionCN":"表示制造的动词，作名词时指农产品；是 production 背后的动作。"},{"word":"producer","ipa":"/prəˈdjuːsə/","tag":"the person","definition":"The one who makes, or the one who organizes a film; it names an agent, not a process.","definitionCN":"制造者或组织影片的人；指施动者而非过程。"},{"word":"reproduction","ipa":"/ˌriːprəˈdʌkʃən/","tag":"making again","definition":"Re- 'again' plus production: the making of a copy, or the biological bearing of young.","definitionCN":"re-「再」加 production：复制，或生物的繁殖。"}]},{"heading":"NEAR MEANING","entries":[{"word":"output","ipa":"/ˈaʊtpʊt/","tag":"amount focus","definition":"What comes out of a process, especially as a measured quantity; it matches sense two closely.","definitionCN":"一个过程的产物，尤指可计量的数量；与第 2 义接近。"},{"word":"manufacture","ipa":"/ˌmænjuˈfæktʃə/","tag":"factory making","definition":"Making goods on an industrial scale; it stresses factories and hands, where production is broader.","definitionCN":"工业规模地制造货物；强调工厂与手工，而 production 范围更广。"},{"word":"generation","ipa":"/ˌdʒenəˈreɪʃən/","tag":"bringing forth","definition":"The producing of something, especially energy or offspring; it is closer to the older sense than to factory output.","definitionCN":"产生某物，尤指能源或后代；比工厂产出更接近较早的词义。"},{"word":"creation","ipa":"/kriˈeɪʃən/","tag":"making something new","definition":"Bringing something into existence, often artistic or original; production may only repeat an existing design.","definitionCN":"使某物产生，常指艺术或原创；production 可能只是重复既有设计。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the lead-forward root, the fixed phrases and the industrial sense.","cn":"正常联想：「向前引出」词根、固定搭配与工业义。"},"normal":[{"en":"Pro- 'forward' plus ducere 'lead': production leads material forward into a product.","cn":"pro-「向前」加 ducere「引导」：生产把材料一路引成产品。"},{"en":"The family runs produce, producer, product, productive, productivity and reproduction.","cn":"同族词有 produce、producer、product、productive、productivity 与 reproduction。"},{"en":"Fixed phrases: production line, mass production, production costs, in production.","cn":"固定说法：生产线、批量生产、生产成本、在生产中。"},{"en":"The same root appears in conduct, introduce, reduce and educate.","cn":"同一词根出现在 conduct、introduce、reduce 与 educate 中。"},{"en":"Economics pairs it with consumption: what is made and what is used up.","cn":"经济学把它与消费配对：造出来的与用掉的。"}],"abstract":[{"en":"Picture raw bales entering one end of a line and boxes leaving the other.","cn":"想象原料包从流水线一端进去，成品箱从另一端出来。"},{"en":"Picture a counter that clicks once per finished item all day.","cn":"想象一只计数器，每出一件成品就跳一下，整天不停。"},{"en":"Picture a stage where a script slowly becomes a lit set.","cn":"想象一方舞台，剧本慢慢变成亮起的布景。"}]},"examples":[{"en":"The factory raised production without adding a single worker.","cn":"工厂没有增加一名工人就提高了产量。"},{"en":"Steel production fell during the third quarter.","cn":"第三季度钢铁产量下降。"},{"en":"The new production of the play moved the action to a modern city.","cn":"这部戏的新制作把故事搬到了现代城市。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pro（向前）+ duct（引导）+ ion」——把原料一路引出来，就是生产","word":"production"},"root":"拉丁 productio「带出、引出」，来自 producere = pro-（向前）+ ducere「引导」；经法语进入英语。","sensesIntro":{"en":"Eight senses follow one bringing-forth: making goods, the amount made, the whole economy's output, a staged work, new knowledge, a bodily substance, the stage of being made and finally one finished production.","cn":"八个义项围绕「带出」这个动作：制造货物、产量、整体经济产出、舞台制作、新知识、体内物质、正在制造的阶段，最后是一部成品。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line that carries raw material forward until it emerges as a finished box.","cn":"核心意象：一条把原料一路送到出口、变成成品箱的线。"},"chain":["INPUTS CONVERTED","GOODS MADE","OUTPUT AMOUNT","STAGE WORK","BRINGING FORTH","GENERATION"],"branches":[{"senses":"01 · 03","en":"ACT AND SCALE: one factory's making and a whole economy's making are the same act at different sizes.","cn":"动作与规模：一家工厂的制造与整个经济的制造，是同一动作的不同尺度。"},{"senses":"02 · 07","en":"AMOUNT AND PHASE: the figure produced and the stage of being produced are two views of one process.","cn":"数量与阶段：造出的数字与正在造的阶段，是同一过程的两种视角。"},{"senses":"04 · 08","en":"STAGE: preparing a show and one finished staging are the process and its countable result.","cn":"舞台：排演与一部成品，是过程与可数的结果。"},{"senses":"05","en":"KNOWLEDGE: data and ideas are brought forth exactly as goods are.","cn":"知识：数据和想法被带出来，与货物一样。"},{"senses":"06","en":"BODY: a gland making a hormone is production with no factory at all.","cn":"身体：腺体生成激素，是完全没有工厂的生产。"}]},"affixes":{"intro":{"en":"Production is a Latin noun of leading forward, built from a prefix, a lead-root and an action ending.","cn":"production 是由「向前引出」构成的拉丁名词，包含前缀、引导词根与动作词尾。"},"latinIntro":{"en":"Latin ducere gives conduct, introduce, reduce and educate; pro- adds the forward direction that production keeps.","cn":"拉丁 ducere 衍生 conduct、introduce、reduce 与 educate；pro- 增添 production 保留的向前方向。"},"items":[{"word":"pro-","structure":"Latin prefix","meaning":"forward, before","meaningCN":"向前；在前","example":"The prefix sends the action outward.","exampleCN":"这个前缀把动作送向外。"},{"word":"ducere","structure":"Latin verb, third conjugation","meaning":"to lead, draw","meaningCN":"引导；拉","example":"The root carries the pulling forward.","exampleCN":"这个词根带着「往前拉」。"},{"word":"producere","structure":"pro- + ducere","meaning":"to lead forward, bring out","meaningCN":"向前引出；带出","example":"The verb produced the English produce.","exampleCN":"这个动词给出了英语的 produce。"},{"word":"produce","structure":"producere through French","meaning":"to make, bring forth","meaningCN":"生产；产生","example":"The region produces most of the crop.","exampleCN":"该地区生产大部分这种作物。"},{"word":"production","structure":"produce + -tion (action)","meaning":"the act of making","meaningCN":"生产；制造","example":"Production doubled after the change.","exampleCN":"改动之后产量翻倍。"},{"word":"product","structure":"pro- + ducere + -tum","meaning":"the thing produced","meaningCN":"产品","example":"The product sold out in a week.","exampleCN":"产品一周内售罄。"},{"word":"productive","structure":"product + -ive","meaning":"producing much","meaningCN":"多产的；有成效的","example":"It was a productive afternoon.","exampleCN":"那是一个颇有成效的下午。"},{"word":"productivity","structure":"productive + -ity","meaning":"output per unit of effort","meaningCN":"生产率","example":"Productivity rose with the new tools.","exampleCN":"有了新工具，生产率提高了。"},{"word":"reproduction","structure":"re- + production","meaning":"making again; breeding","meaningCN":"复制；繁殖","example":"The museum ordered a reproduction.","exampleCN":"博物馆订了一件复制品。"}],"latinEntries":[{"word":"ducere","structure":"ducere, duxi, ductum (verb, third conjugation)","meaning":"to lead, draw","meaningCN":"引导；拉"},{"word":"producere","structure":"producere, produxi, productum (verb, third conjugation)","meaning":"to lead forward, bring out","meaningCN":"向前引出；带出"},{"word":"productio","structure":"productio, productionis (f., third declension)","meaning":"a bringing forth; a lengthening","meaningCN":"带出；拉长"}],"derivatives":[{"word":"produce","pos":"v./n.","zh":"生产；农产品"},{"word":"producer","pos":"n.","zh":"生产者；制片人"},{"word":"productive","pos":"adj.","zh":"多产的；有成效的"},{"word":"productivity","pos":"n.","zh":"生产率"}]}},{"word":"producer","ipa_uk":"/prəˈdjuːsə/","ipa_us":"/prəˈduːsər/","definition_zh":"生产者；制造商；制片人；（生态）生产者","definition_en":"a person or company that makes goods, or the one who organizes a film or programme","core_image":"车间尽头的一双手给成品贴上标签，标签上写着出自谁手","scene":"剧组杀青那天，制片人站在监视器旁核对最后一份预算表。On the last day of shooting, the producer checked the final budget beside the monitor.","sceneCN":"剧组杀青那天，制片人站在监视器旁核对最后一份预算表；句中的 producer 指「负责组织并推进影视制作的人」（第 3 个义项：影视或戏剧的制片人）。图中可辨识物件：监视器、预算表、场记板、折叠椅。","pos":[{"tag":"n.","zh":"生产者；制造商；制片人；（生态）生产者"}],"collocations":[{"phrase":"film producer","zh":"电影制片人"},{"phrase":"music producer","zh":"音乐制作人"},{"phrase":"producer price","zh":"出厂价"},{"phrase":"producer goods","zh":"生产资料"},{"phrase":"agricultural producer","zh":"农业生产者"},{"phrase":"executive producer","zh":"执行制片人"}],"forms":[{"label":"复数","form":"producers"},{"label":"动词（生产）","form":"produce"},{"label":"名词（生产）","form":"production"},{"label":"形容词（多产的）","form":"productive"},{"label":"名词（生产率）","form":"productivity"}],"derivatives":[{"word":"produce","pos":"v./n.","zh":"生产；农产品"},{"word":"production","pos":"n.","zh":"生产；制作"},{"word":"productive","pos":"adj.","zh":"多产的；有成效的"},{"word":"productivity","pos":"n.","zh":"生产率"},{"word":"co-producer","pos":"n.","zh":"联合制片人"}],"senses":[{"no":"01","title":"A maker of goods","titleCN":"制造货物的人或企业","definition":"a person or firm that makes goods for sale","definitionCN":"制造货物以供出售的人或企业","example":"The producer shipped the first batch on Monday.","exampleCN":"制造商周一发出了第一批货。","why":"Producer is the doer form of produce, so it simply names whoever brings the goods forth.","whyCN":"producer 是 produce 的施动者形式，因此直接指把货物造出来的一方。"},{"no":"02","title":"The supplying side of an economy","titleCN":"经济中的生产方","definition":"the side of a market that makes and offers goods, as opposed to buyers","definitionCN":"市场中制造并提供货物的一方，与买方相对","example":"Producers absorbed most of the higher input cost.","exampleCN":"生产者承担了大部分上涨的投入成本。","why":"Economics splits a market into makers and takers, and producer names one whole side.","whyCN":"经济学把市场分成制造方与取用方，producer 指其中一整侧。"},{"no":"03","title":"The organizer of a film or play","titleCN":"影视或戏剧的制片人","definition":"the person who arranges funding, staff and schedule for a film, play or series","definitionCN":"为电影、戏剧或剧集安排资金、人员与进度的人","example":"On the last day of shooting, the producer checked the final budget beside the monitor.","exampleCN":"杀青那天，制片人在监视器旁核对最后一份预算表。","why":"A show must be brought into existence like a product, so the one who arranges it takes the same name.","whyCN":"一部戏也要像产品一样被造出来，因此安排它的人沿用同一称呼。"},{"no":"04","title":"The organizer of a music recording","titleCN":"音乐制作人","definition":"the person who supervises the recording, mixing and shape of a music release","definitionCN":"监督录音、混音与成品形态的人","example":"The producer reshaped the album around a single riff.","exampleCN":"制作人围绕一段乐句重塑了整张专辑。","why":"Music uses the same word because a record is assembled from parts under one hand.","whyCN":"音乐沿用这个词，因为一张唱片是在一双手的安排下由各部分拼成的。"},{"no":"05","title":"A farmer or grower","titleCN":"农业生产者","definition":"a person or farm that grows crops or raises animals for sale","definitionCN":"种植作物或饲养动物以供出售的人或农场","example":"Local producers sell directly at the Saturday market.","exampleCN":"本地农业生产者周六直接在集市上出售。","why":"Growing food is one form of bringing forth, so farms count as producers in ordinary speech.","whyCN":"种出食物是「带出」的一种，因此农场在日常语言里也算生产者。"},{"no":"06","title":"An organism that makes its own food","titleCN":"生态学中自养的生产者","definition":"in ecology, an organism such as a plant that makes food from sunlight or chemicals","definitionCN":"生态学中靠阳光或化学能自制食物的生物，如植物","example":"Green plants are the producers at the base of the food web.","exampleCN":"绿色植物是食物网底层的生产者。","why":"Ecology borrowed the economic word for organisms that create food rather than consume it.","whyCN":"生态学借用这个经济词，指制造食物而非消耗食物的生物。"},{"no":"07","title":"The organizer of a broadcast","titleCN":"广播电视节目的制作负责人","definition":"the person responsible for putting a radio or television programme together","definitionCN":"负责把广播或电视节目组织成形的人","example":"The producer cut the interview to fit the half-hour slot.","exampleCN":"制片人把访谈剪到半小时内。","why":"A programme is assembled to a fixed length, and the one who assembles it is named as a maker.","whyCN":"节目要按固定时长拼装，负责拼装的人便被称为制造者。"},{"no":"08","title":"Producer responsibility in policy","titleCN":"环境政策中的生产者责任","definition":"the duty placed on manufacturers to take back or fund the disposal of their products","definitionCN":"要求制造商回收或出资处理其产品的义务","example":"New rules extended producer responsibility to packaging.","exampleCN":"新规把生产者责任扩展到包装。","why":"Policy makes the maker answerable for the whole life of the thing made.","whyCN":"政策让制造者对成品的整个生命周期负责。"}],"etymology":{"intro":{"en":"Producer is the English agent noun of produce, formed with the suffix -er on a verb that comes from Latin producere 'to lead forward'. The film and music senses are nineteenth- and twentieth-century extensions.","cn":"producer 是 produce 的英语施动名词，在源自拉丁 producere「向前引出」的动词上加 -er 构成；影视与音乐义是十九、二十世纪的延伸。"},"items":[{"era":"LATIN DUCERE","en":"Ducere meant 'to lead, draw'. Through producere it reaches produce, product and producer.","cn":"ducere 意为「引导、拉」，经 producere 通向 produce、product 与 producer。"},{"era":"LATIN PRODUCERE","en":"Pro- 'forward' plus ducere gave producere, 'to lead forward, bring out'.","cn":"pro-「向前」加 ducere 构成 producere，意为「向前引出、带出」。"},{"era":"ENGLISH PRODUCE","en":"English took the verb through French; the agent suffix -er, from Old English -ere and French -eur, was added to name the doer.","cn":"英语经法语吸收这个动词，再加施动后缀 -er（源自古英语 -ere 与法语 -eur）来指做这件事的人。"},{"era":"EARLY PRODUCER","en":"From the sixteenth century a producer was simply one who brings something forth, whether crops or goods.","cn":"从十六世纪起，producer 只指带出某物的人，无论作物还是货物。"},{"era":"STAGE AND SCREEN","en":"In the nineteenth century theatre and later film gave the word its managerial sense: the person who funds and organizes a show.","cn":"十九世纪的戏剧以及后来的电影赋予这个词管理义：出资并组织演出的人。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the first use of the film sense is not precisely dated, and the year is approximate.","cn":"来源不确定：影视义的最早用例没有确切年代，给出的年份只是约数。"}]},"similar":{"note":{"en":"Group one holds same-root words that are often swapped; group two holds near roles that are not producers.","cn":"第一组是同根且常被互换的词；第二组是并非 producer 的近义角色。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"produce","ipa":"/prəˈdjuːs/","tag":"the verb","definition":"The action itself, or farm goods as a noun; it is what a producer does, not the doer.","definitionCN":"动作本身，或作名词指农产品；是 producer 所做的事，不是做的人。"},{"word":"product","ipa":"/ˈprɒdʌkt/","tag":"the thing","definition":"What is made; a producer makes products, but product never names the maker.","definitionCN":"被造出来的东西；生产者制造产品，但 product 从不指制造者。"},{"word":"production","ipa":"/prəˈdʌkʃən/","tag":"the process","definition":"The activity or total output; it names the making, while producer names the one making.","definitionCN":"活动或总产出；指制造，而 producer 指制造者。"},{"word":"director","ipa":"/dɪˈrektə/","tag":"different film role","definition":"The person who shapes the performances and shots; the producer handles money and organization.","definitionCN":"负责表演与镜头形态的人；制片人管钱与组织。"}]},{"heading":"NEAR MEANING","entries":[{"word":"manufacturer","ipa":"/ˌmænjuˈfæktʃərə/","tag":"factory word","definition":"A firm that makes goods in factories; narrower and more industrial than producer.","definitionCN":"在工厂制造货物的企业；比 producer 更窄、更工业。"},{"word":"maker","ipa":"/ˈmeɪkə/","tag":"plain word","definition":"The everyday word for one who makes something; it lacks the economic and media senses.","definitionCN":"指制造者的日常词；不含经济与影视义。"},{"word":"grower","ipa":"/ˈɡrəʊə/","tag":"crops only","definition":"A person who grows crops, especially fruit; it is the farming half of producer.","definitionCN":"种植作物的人，尤指水果；是 producer 中务农的那一半。"},{"word":"supplier","ipa":"/səˈplaɪə/","tag":"delivery role","definition":"A firm that provides goods to buyers; it stresses delivery rather than creation.","definitionCN":"向买方提供货物的企业；侧重交付而非创造。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the agent suffix, the same-root family and the fixed phrases.","cn":"正常联想：施动后缀、同根词族与固定搭配。"},"normal":[{"en":"Produce plus -er: the one who brings the goods forth.","cn":"produce 加 -er：把货物带出来的那一方。"},{"en":"The family runs produce, producer, production, product, productive and productivity.","cn":"同族词有 produce、producer、production、product、productive 与 productivity。"},{"en":"Fixed phrases: film producer, music producer, producer price, agricultural producer.","cn":"固定说法：电影制片人、音乐制作人、出厂价、农业生产者。"},{"en":"The same root appears in conduct, introduce, reduce and educate.","cn":"同一词根出现在 conduct、introduce、reduce 与 educate 中。"},{"en":"Ecology keeps the word for plants that make their own food.","cn":"生态学保留这个词，指能自制食物的植物。"}],"abstract":[{"en":"Picture a hand stamping a finished box with a name.","cn":"想象一只手在成品箱上盖下一个名字。"},{"en":"Picture a person holding the schedule and the budget at once.","cn":"想象一个人同时拿着进度表与预算表。"},{"en":"Picture a green leaf quietly making food for a whole food web.","cn":"想象一片绿叶默默为整张食物网制造食物。"}]},"examples":[{"en":"The producer delayed the release until the soundtrack was finished.","cn":"制片人把发行推迟到配乐完成之后。"},{"en":"Coffee producers in the highlands formed a cooperative.","cn":"高地的咖啡生产者组建了合作社。"},{"en":"New packaging rules make the producer pay for collection.","cn":"新的包装规定让生产者承担回收费用。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「produce（生产）+ r（人）」——把东西造出来的人，就是生产者与制片人","word":"producer"},"root":"英语 produce + 施动后缀 -er；produce 源自拉丁 producere「向前引出」= pro- + ducere「引导」。","sensesIntro":{"en":"Eight senses follow one maker: a firm, a whole supplying side, a film organizer, a music organizer, a farmer, a plant, a broadcast organizer and finally a policy duty.","cn":"八个义项围绕同一个制造者：企业、整个供给方、影视制片人、音乐制作人、农户、植物、节目制作负责人，最后是政策义务。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand at the end of a line stamping a name on every finished item.","cn":"核心意象：流水线末端一只手在每件成品上盖下名字。"},"chain":["MAKER","SUPPLY SIDE","SHOW ORGANIZER","RECORD ORGANIZER","GROWER","AUTOTROPH"],"branches":[{"senses":"01 · 02 · 08","en":"MAKER AND ITS DUTIES: one firm, a whole market side, and the responsibility policy lays on them.","cn":"制造者与其责任：一家企业、整个市场一侧，以及政策加在它们身上的责任。"},{"senses":"03 · 07","en":"ORGANIZER: a film and a broadcast are both assembled by one person holding money and schedule.","cn":"组织者：电影与广播节目，都由一个掌钱与掌进度的人拼装。"},{"senses":"04","en":"RECORD: music borrows the same role for a release built from parts.","cn":"唱片：音乐为一张拼装而成的作品借用同一角色。"},{"senses":"05","en":"GROWER: a farm brings forth crops, which is production in the oldest sense.","cn":"农户：农场带出作物，是最古老意义上的生产。"},{"senses":"06","en":"AUTOTROPH: a plant makes its own food, so ecology calls it a producer.","cn":"自养者：植物自制食物，生态学便称之为生产者。"}]},"affixes":{"intro":{"en":"Producer is an English agent noun on a Latin verb of leading forward, so its ending and root can be read separately.","cn":"producer 是在「向前引出」的拉丁动词上加英语施动后缀构成，词尾与词根可分读。"},"latinIntro":{"en":"Latin ducere and producere supply the root; the -er ending came into English from both Old English and French.","cn":"拉丁 ducere 与 producere 提供词根；-er 词尾同时来自古英语与法语。"},"items":[{"word":"pro-","structure":"Latin prefix","meaning":"forward","meaningCN":"向前","example":"The prefix sends the making forward into a result.","exampleCN":"这个前缀把制造送向前，成为结果。"},{"word":"ducere","structure":"Latin verb, third conjugation","meaning":"to lead","meaningCN":"引导","example":"The root carries the leading.","exampleCN":"这个词根带着「引导」。"},{"word":"produce","structure":"pro- + ducere","meaning":"to bring forth","meaningCN":"生产；带出","example":"Farms produce most of the local food.","exampleCN":"农场生产大部分本地食物。"},{"word":"-er","structure":"agent suffix, Old English -ere and French -eur","meaning":"one who does","meaningCN":"做某事的人","example":"The suffix turns the action into a person.","exampleCN":"这个后缀把动作变成人。"},{"word":"producer","structure":"produce + -er","meaning":"one who brings forth","meaningCN":"生产者；制片人","example":"The producer signed off the budget.","exampleCN":"制片人批准了预算。"},{"word":"production","structure":"produce + -tion","meaning":"the act of making","meaningCN":"生产；制作","example":"Production began in March.","exampleCN":"制作在三月份开始。"},{"word":"product","structure":"pro- + ducere + -tum","meaning":"the thing made","meaningCN":"产品","example":"The product reached shops in June.","exampleCN":"产品六月上市。"},{"word":"co-producer","structure":"co- + producer","meaning":"a joint organizer","meaningCN":"联合制片人","example":"Two studios appointed a co-producer.","exampleCN":"两家公司指派了一位联合制片人。"}],"latinEntries":[{"word":"ducere","structure":"ducere, duxi, ductum (verb, third conjugation)","meaning":"to lead, draw","meaningCN":"引导；拉"},{"word":"producere","structure":"producere, produxi, productum (verb, third conjugation)","meaning":"to lead forward, bring out","meaningCN":"向前引出；带出"},{"word":"productio","structure":"productio, productionis (f., third declension)","meaning":"a bringing forth","meaningCN":"带出"}],"derivatives":[{"word":"produce","pos":"v./n.","zh":"生产；农产品"},{"word":"production","pos":"n.","zh":"生产；制作"},{"word":"productive","pos":"adj.","zh":"多产的"},{"word":"productivity","pos":"n.","zh":"生产率"},{"word":"co-producer","pos":"n.","zh":"联合制片人"}]}},{"word":"produce","ipa_uk":"/prəˈdjuːs/","ipa_us":"/prəˈduːs/","definition_zh":"生产；制造；产生；出示；排演；农产品","definition_en":"to make, grow or bring something into existence; as a noun, farm products","core_image":"果园枝头的果子被摘进篮子，篮子上贴着产地标签","scene":"农户把今年收的果子装筐，运到镇上的集市。The farm produces enough apples to fill a stall at the town market.","sceneCN":"农户把今年收的果子装筐运到镇上集市；句中的 produces 指「种出、出产某物」（第 2 个义项：以种植或养殖方式产出）。图中可辨识物件：果园、果筐、集市摊位、产地标签。","pos":[{"tag":"vt.","zh":"生产；制造；产生；出示；排演"},{"tag":"vi.","zh":"生产；出产"},{"tag":"n.","zh":"农产品（重音移到第一音节）"}],"collocations":[{"phrase":"produce evidence","zh":"出示证据"},{"phrase":"produce results","zh":"产生结果"},{"phrase":"produce electricity","zh":"发电"},{"phrase":"farm produce","zh":"农产品"},{"phrase":"produce a play","zh":"排演一出戏"},{"phrase":"locally produced","zh":"本地生产的"}],"forms":[{"label":"三单（he/she/it）","form":"produces"},{"label":"过去式","form":"produced"},{"label":"过去分词","form":"produced"},{"label":"现在分词","form":"producing"},{"label":"名词（农产品，重音前移）","form":"produce"},{"label":"名词（生产）","form":"production"},{"label":"名词（生产者）","form":"producer"}],"derivatives":[{"word":"product","pos":"n.","zh":"产品"},{"word":"production","pos":"n.","zh":"生产；制作"},{"word":"producer","pos":"n.","zh":"生产者；制片人"},{"word":"productive","pos":"adj.","zh":"多产的；有成效的"},{"word":"reproduce","pos":"v.","zh":"复制；繁殖"}],"senses":[{"no":"01","title":"Make or manufacture","titleCN":"制造出某物","definition":"to make something, especially in a factory or by a process","definitionCN":"造出某物，尤指在工厂或经某一过程","example":"The plant produces parts for wind turbines.","exampleCN":"这家工厂生产风力涡轮机的零件。","why":"The Latin verb means to lead forward, so making is bringing material forward into a finished thing.","whyCN":"拉丁动词意为「向前引出」，因此制造就是把材料引成成品。"},{"no":"02","title":"Grow or yield from land","titleCN":"种出、出产","definition":"to grow crops or raise animals as a result of farming","definitionCN":"通过耕作或养殖产出作物或畜禽","example":"The farm produces enough apples to fill a stall at the town market.","exampleCN":"这个农场种的苹果足够装满镇上集市的一个摊位。","why":"A field yielding fruit is the same bringing-forth, with land rather than a machine doing the work.","whyCN":"田地结出果实也是同一种「带出」，只是出力的是土地而非机器。"},{"no":"03","title":"Cause an effect","titleCN":"引起某种结果","definition":"to cause something to happen or to exist","definitionCN":"使某事发生或存在","example":"The new policy produced a sharp fall in complaints.","exampleCN":"新政策使投诉量大幅下降。","why":"Once anything can be brought forth, the word covers results that are not physical objects.","whyCN":"一旦任何东西都能被「带出」，这个词便涵盖并非实物的结果。"},{"no":"04","title":"Show or bring forward","titleCN":"出示、拿出","definition":"to present something for inspection, such as a document or a ticket","definitionCN":"把某物拿出来供查验，如文件或票据","example":"The witness produced the original receipt.","exampleCN":"证人出示了原始收据。","why":"Bringing something before someone is a literal leading forward, which explains the legal use.","whyCN":"把东西带到某人面前，字面上就是「向前引出」，这解释了法律用法。"},{"no":"05","title":"Stage a play or film","titleCN":"排演、制作影视戏剧","definition":"to prepare and present a play, film or show for an audience","definitionCN":"筹备并向观众呈现戏剧、电影或节目","example":"The company will produce the play in the spring.","exampleCN":"剧团将在春天排演这部戏。","why":"A show is brought out before an audience, so the cultural sense keeps the forward direction.","whyCN":"一部戏被带到观众面前，因此文化义保留了「向前」的方向。"},{"no":"06","title":"Generate energy","titleCN":"发出（电、热）","definition":"to generate power, heat or another form of energy","definitionCN":"发出电力、热量或其他形式的能量","example":"The dam produces power for three provinces.","exampleCN":"这座大坝为三个省发电。","why":"Energy is led out of a source into a usable current, which fits the word's movement image.","whyCN":"能量从源头被引出成可用的电流，正合这个词的「引出」意象。"},{"no":"07","title":"Farm products as a mass noun","titleCN":"作不可数名词指农产品","definition":"fresh food grown on farms, sold as a group rather than counted one by one","definitionCN":"农场种出的新鲜食物，作为整体出售而非逐件计数","example":"The shop buys its produce from nearby growers.","exampleCN":"这家店从附近农户采购农产品。","why":"The verb's result became a collective noun for what the land brings forth.","whyCN":"动词的结果转成了集合名词，指土地带出的东西。"},{"no":"08","title":"The fresh-food section of a shop","titleCN":"商店里的生鲜区","definition":"the fruit and vegetable section of a shop, or its stock","definitionCN":"商店的果蔬区或其存货","example":"The produce aisle was restocked before opening.","exampleCN":"开门前生鲜区补好了货。","why":"Retail narrows the collective noun to one department, the place where farm goods are sold.","whyCN":"零售把集合名词收窄为一个部门，即卖农产品的地方。"}],"etymology":{"intro":{"en":"Produce comes from Latin producere 'to lead forward, bring out', through French. The noun for farm goods is a later English development of the same word.","cn":"produce 经法语来自拉丁 producere「向前引出、带出」；指农产品的名词义是同一词在英语中的后起发展。"},"items":[{"era":"LATIN DUCERE","en":"Ducere meant 'to lead, draw'. It gives duct, conduct, reduce and educate.","cn":"ducere 意为「引导、拉」，衍生 duct、conduct、reduce 与 educate。"},{"era":"LATIN PRODUCERE","en":"Pro- 'forward' plus ducere produced producere, 'to lead forward, bring out, bring forth'.","cn":"pro-「向前」加 ducere 构成 producere，意为「向前引出、带出」。"},{"era":"OLD FRENCH PRODUIRE","en":"Old French produire carried the verb into English in the fifteenth century.","cn":"古法语 produire 在十五世纪把这个动词带入英语。"},{"era":"LEGAL AND GENERAL SENSES","en":"By the sixteenth century produce could mean bring forward a document as well as bring goods into being.","cn":"到十六世纪，produce 既可指造出货物，也可指出示文件。"},{"era":"FARM NOUN","en":"The mass noun for crops and fresh food appeared later, first in English rather than in Latin.","cn":"指作物与新鲜食物的不可数名词出现更晚，是英语自身的发展而非拉丁语原有。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the first date of the farm noun is not firmly recorded, and the year is approximate.","cn":"来源不确定：农产品名词的最早年代没有确切记录，给出的年份只是约数。"}]},"similar":{"note":{"en":"Group one holds same-root words constantly confused with produce; group two holds near verbs for making and yielding.","cn":"第一组是同根且常与 produce 混淆的词；第二组是表示制造与产出的近义动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"product","ipa":"/ˈprɒdʌkt/","tag":"noun of result","definition":"The thing made; produce as a verb makes products but never names them.","definitionCN":"造出来的东西；作动词的 produce 制造产品，却不用它来指产品。"},{"word":"production","ipa":"/prəˈdʌkʃən/","tag":"noun of process","definition":"The activity or total output; it is what happens while produce is what is done.","definitionCN":"活动或总产出；produce 是动作，production 是过程或总量。"},{"word":"producer","ipa":"/prəˈdjuːsə/","tag":"the doer","definition":"The person or firm that makes; the verb names the act, not the actor.","definitionCN":"制造的人或企业；动词指动作，不指施动者。"},{"word":"reproduce","ipa":"/rɪˈprəduːs/","tag":"making again","definition":"Re- 'again' plus produce: to make a copy or to breed; it repeats rather than originates.","definitionCN":"re-「再」加 produce：复制或繁殖；是重复而非原创。"}]},{"heading":"NEAR MEANING","entries":[{"word":"make","ipa":"/meɪk/","tag":"plain word","definition":"The everyday verb for creating something; it is neutral in register where produce is formal.","definitionCN":"创造某物的日常动词；语体中性，而 produce 较正式。"},{"word":"manufacture","ipa":"/ˌmænjuˈfæktʃə/","tag":"factory only","definition":"Making goods industrially; it rules out crops and effects, which produce allows.","definitionCN":"工业制造货物；排除作物与结果，而 produce 都允许。"},{"word":"generate","ipa":"/ˈdʒenəreɪt/","tag":"energy and results","definition":"Producing power, data or ideas; it is close in sense three and six but rarer for goods.","definitionCN":"产生电力、数据或想法；接近第 3、6 义，但少用于货物。"},{"word":"yield","ipa":"/jiːld/","tag":"land and output","definition":"To give a crop or a result, often under pressure; it is the farming half of produce.","definitionCN":"出产作物或结果，常含受压之意；是 produce 中务农的一半。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the lead-forward root, the mass noun and the fixed phrases.","cn":"正常联想：「向前引出」词根、不可数名词与固定搭配。"},"normal":[{"en":"Pro- 'forward' plus ducere 'lead': to produce is to lead something into being.","cn":"pro-「向前」加 ducere「引导」：produce 就是把某物引出来。"},{"en":"The family runs produce, product, production, producer, productive and reproduce.","cn":"同族词有 produce、product、production、producer、productive 与 reproduce。"},{"en":"Fixed phrases: produce evidence, produce results, farm produce, locally produced.","cn":"固定说法：出示证据、产生结果、农产品、本地生产的。"},{"en":"The noun shifts its stress to the first syllable, which is how English marks the change of word class.","cn":"作名词时重音移到第一音节，这是英语标记词性变化的方式。"},{"en":"The same root appears in conduct, introduce, reduce and educate.","cn":"同一词根出现在 conduct、introduce、reduce 与 educate 中。"}],"abstract":[{"en":"Picture a tree handing fruit into a basket one branch at a time.","cn":"想象一棵树一根枝一根枝地把果子交进篮子。"},{"en":"Picture a document sliding across a desk to be checked.","cn":"想象一份文件在桌面上滑过去接受查验。"},{"en":"Picture a switch that turns a river's weight into light in a room.","cn":"想象一个开关，把河流的重量变进房间的灯光。"}]},"examples":[{"en":"The region produces more olive oil than it can sell at home.","cn":"该地区生产的橄榄油超过本地能卖出的量。"},{"en":"The lawyer asked the company to produce the missing records.","cn":"律师要求公司出示缺失的记录。"},{"en":"A single change in the wording produced a very different response.","cn":"措辞上的一处改动引出了很不一样的反应。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pro（向前）+ duce（引导）」——把东西一路引出来，就是生产与出产","word":"produce"},"root":"拉丁 producere「向前引出、带出」= pro-（向前）+ ducere「引导」；经古法语 produire 进入英语。","sensesIntro":{"en":"Eight senses follow one bringing-forth: manufacturing, farming, causing an effect, showing a document, staging a show, generating power, farm goods as a mass noun and finally the shop's fresh section.","cn":"八个义项围绕「带出」这个动作：制造、种出、引起结果、出示文件、排演、发电、作不可数名词指农产品，最后是商店的生鲜区。"},"semanticMap":{"core":{"en":"CORE IMAGE: a basket of picked fruit carrying a label that says where it grew.","cn":"核心意象：一篮摘下的果子，标签上写着它长在哪里。"},"chain":["MATERIAL FORWARD","GOODS MADE","CROPS YIELDED","EFFECT CAUSED","SHOWN TO OTHERS","GENERATED POWER"],"branches":[{"senses":"01 · 02","en":"MAKING AND GROWING: a factory line and a field are both ways of leading material into a result.","cn":"制造与种植：工厂流水线与田地，都是把材料引成结果的方式。"},{"senses":"03 · 04","en":"BROUGHT FORTH: an effect and a document are both brought forward where they can be seen.","cn":"被带出：结果与文件都被带到能被看见的地方。"},{"senses":"05 · 08","en":"STAGE AND SHOP: a show and a fresh-food aisle are places where produce is presented to the public.","cn":"舞台与店铺：演出与生鲜区，都是把出产呈现给公众的场所。"},{"senses":"06","en":"POWER: energy is led out of a source into a current.","cn":"电力：能量从源头被引出成电流。"},{"senses":"07","en":"MASS NOUN: what the land brings forth becomes a collective name for food.","cn":"集合名词：土地带出的东西成了食物的统称。"}]},"affixes":{"intro":{"en":"Produce is a Latin verb of leading forward, and its prefix and root still build a large English family.","cn":"produce 是表示「向前引出」的拉丁动词，其前缀与词根仍构成一大片英语词族。"},"latinIntro":{"en":"Latin ducere gives conduct, introduce, reduce and educate; pro- adds the forward direction kept in produce.","cn":"拉丁 ducere 衍生 conduct、introduce、reduce 与 educate；pro- 增添 produce 保留的向前方向。"},"items":[{"word":"pro-","structure":"Latin prefix","meaning":"forward","meaningCN":"向前","example":"The prefix points the action outward.","exampleCN":"这个前缀把动作指向外。"},{"word":"ducere","structure":"Latin verb, third conjugation","meaning":"to lead","meaningCN":"引导","example":"The root carries the leading.","exampleCN":"这个词根带着「引导」。"},{"word":"produce","structure":"pro- + ducere","meaning":"to bring forth","meaningCN":"生产；带出","example":"The farm produces apples.","exampleCN":"农场出产苹果。"},{"word":"product","structure":"pro- + ducere + -tum","meaning":"the thing made","meaningCN":"产品","example":"The product sells in six countries.","exampleCN":"该产品在六国销售。"},{"word":"production","structure":"produce + -tion","meaning":"the act of making","meaningCN":"生产","example":"Production runs day and night.","exampleCN":"生产昼夜不停。"},{"word":"producer","structure":"produce + -er","meaning":"one who makes","meaningCN":"生产者","example":"The producer owns the orchard.","exampleCN":"生产者拥有这片果园。"},{"word":"productive","structure":"product + -ive","meaning":"yielding much","meaningCN":"多产的","example":"The valley is highly productive.","exampleCN":"这条河谷产量很高。"},{"word":"reproduce","structure":"re- + produce","meaning":"to make again","meaningCN":"复制；繁殖","example":"Ferns reproduce by spores.","exampleCN":"蕨类靠孢子繁殖。"}],"latinEntries":[{"word":"ducere","structure":"ducere, duxi, ductum (verb, third conjugation)","meaning":"to lead, draw","meaningCN":"引导；拉"},{"word":"producere","structure":"producere, produxi, productum (verb, third conjugation)","meaning":"to lead forward, bring out","meaningCN":"向前引出；带出"},{"word":"productum","structure":"productum, producti (n., second declension)","meaning":"a thing produced","meaningCN":"产物；产品"}],"derivatives":[{"word":"product","pos":"n.","zh":"产品"},{"word":"production","pos":"n.","zh":"生产；制作"},{"word":"producer","pos":"n.","zh":"生产者；制片人"},{"word":"productive","pos":"adj.","zh":"多产的"},{"word":"reproduce","pos":"v.","zh":"复制；繁殖"}]}},{"word":"consumption","ipa_uk":"/kənˈsʌmpʃən/","ipa_us":"/kənˈsʌmpʃən/","definition_zh":"消费；消耗；食用；消费量；（旧）肺结核","definition_en":"the use of goods, energy or resources, or the amount used","core_image":"仓库里的货一箱箱被搬空，空箱子堆在另一侧","scene":"夏天最热的那几周，老小区的用电量几乎比春天多出一半。During the hottest weeks of summer, electricity consumption in the old neighbourhood nearly doubled.","sceneCN":"夏天最热的那几周，老小区的用电量几乎比春天多出一半；句中的 consumption 指「把商品、能源等用掉的过程或数量」（第 3 个义项：能源与燃料的消耗量）。图中可辨识物件：电表、空调外机、电费账单、树荫。","pos":[{"tag":"n.","zh":"消费；消耗；食用；消费量；（旧）肺结核"}],"collocations":[{"phrase":"energy consumption","zh":"能源消耗"},{"phrase":"household consumption","zh":"家庭消费"},{"phrase":"consumption tax","zh":"消费税"},{"phrase":"fuel consumption","zh":"油耗"},{"phrase":"for public consumption","zh":"供对外宣传用"},{"phrase":"consumption patterns","zh":"消费模式"}],"forms":[{"label":"动词（消费；消耗）","form":"consume"},{"label":"名词（消费者）","form":"consumer"},{"label":"复数（各类消费量）","form":"consumptions"},{"label":"形容词（消耗的）","form":"consuming"},{"label":"形容词（旧：患肺痨的）","form":"consumptive"}],"derivatives":[{"word":"consume","pos":"v.","zh":"消费；消耗"},{"word":"consumer","pos":"n.","zh":"消费者"},{"word":"consumerism","pos":"n.","zh":"消费主义"},{"word":"consumable","pos":"adj./n.","zh":"可消耗的；消耗品"},{"word":"consumptive","pos":"adj./n.","zh":"（旧）患肺痨的；肺痨患者"}],"senses":[{"no":"01","title":"Using up goods","titleCN":"把商品用掉","definition":"the act of using goods or services until they are no longer available","definitionCN":"使用商品或服务直至其不再可用的行为","example":"Household consumption accounts for two thirds of the economy.","exampleCN":"家庭消费占经济总量的三分之二。","why":"The Latin verb means to take up completely, so consumption begins as taking something all the way into use.","whyCN":"拉丁动词意为「完全取走」，因此 consumption 起初指把某物一路用尽。"},{"no":"02","title":"Household and consumer spending","titleCN":"家庭与消费者的支出","definition":"the total spending by households on goods and services in an economy","definitionCN":"一个经济体中家庭用于商品与服务的总支出","example":"Consumer consumption rose after wages improved.","exampleCN":"工资改善后，消费者支出上升。","why":"Economics measures the using-up side of the economy as a money total.","whyCN":"经济学把经济中用掉的那一侧量成金额总量。"},{"no":"03","title":"Energy and fuel drawn down","titleCN":"能源与燃料的消耗量","definition":"the amount of power or fuel used by a device, building or region","definitionCN":"设备、建筑或地区所用的电力或燃料量","example":"During the hottest weeks of summer, electricity consumption in the old neighbourhood nearly doubled.","exampleCN":"夏天最热的那几周，老小区的用电量几乎翻倍。","why":"Electricity is taken from the grid and used up, which is the core image in a measurable form.","whyCN":"电从电网取出并用掉，这是核心意象可测量的形态。"},{"no":"04","title":"Food and drink intake","titleCN":"饮食摄入","definition":"the amount of food or drink taken into the body","definitionCN":"摄入体内的食物或饮料量","example":"The study tracked sugar consumption in schoolchildren.","exampleCN":"这项研究追踪学龄儿童的糖摄入量。","why":"Eating is the oldest way of taking something into oneself, which is the verb's literal sense.","whyCN":"吃是最古老的「取入自身」的方式，正是这个动词的字面义。"},{"no":"05","title":"Using up time or resources","titleCN":"时间或资源的耗用","definition":"the amount of time, money or material that an activity takes","definitionCN":"某项活动占用的时间、金钱或材料量","example":"The consumption of water by the plant was higher than expected.","exampleCN":"这座工厂的用水量高于预期。","why":"Anything that can be taken up and exhausted fits the word, including hours and materials.","whyCN":"凡能被取走、耗尽的东西都适用，包括工时与材料。"},{"no":"06","title":"Tuberculosis, the old name","titleCN":"旧称「肺痨」；肺结核","definition":"the historical name for tuberculosis, from the way the disease seemed to consume the body","definitionCN":"肺结核的旧称，得名于该病似乎把身体消耗掉","example":"In the nineteenth century consumption was the leading cause of death in cities.","exampleCN":"十九世纪，肺痨是城市里的主要死因。","why":"A wasting disease appeared to use the body up, so the word for using up became its name.","whyCN":"消耗性疾病看起来把身体耗掉，于是「用尽」这个词成了病名。"},{"no":"07","title":"Material meant for public view","titleCN":"供对外展示的材料","definition":"used in the phrase for public consumption, meaning intended to be seen or heard by outsiders","definitionCN":"用于「供对外宣传」这一说法，指有意让外界看到或听到","example":"The memo was written for public consumption, not for the staff.","exampleCN":"这份备忘录是写给外界看的，不是给员工看的。","why":"What is offered to the public is taken in by them, so the phrase describes material meant to be absorbed.","whyCN":"提供给公众的东西会被公众吸收，因此这一说法指有意让人接受的材料。"},{"no":"08","title":"Buying patterns studied in marketing","titleCN":"营销研究的消费行为","definition":"the habitual ways in which people buy and use goods","definitionCN":"人们购买与使用货物的习惯方式","example":"The survey mapped consumption patterns across age groups.","exampleCN":"该调查描绘了各年龄段的消费模式。","why":"Marketing follows the whole path from purchase to use, which is what the word covers here.","whyCN":"营销追踪从购买到使用的整条路径，这正是此处的词义。"}],"etymology":{"intro":{"en":"Consumption comes from Latin consumptio, 'a consuming, a wasting', from consumere 'to use up', built on com- 'thoroughly' and sumere 'to take up'. English adopted it in the sixteenth century.","cn":"consumption 来自拉丁 consumptio「消耗、耗尽」，源自动词 consumere「用尽」，由 com-「彻底」与 sumere「取起」构成，十六世纪进入英语。"},"items":[{"era":"LATIN EMERE","en":"Emere meant 'to take, buy'. With the prefix sub- it became sumere, 'to take up'.","cn":"emere 意为「取、买」，加前缀 sub- 成为 sumere「取起」。"},{"era":"LATIN SUMERE","en":"Sumere meant 'to take up, assume'. It also gives assume, resume and presume.","cn":"sumere 意为「取起、承担」，也衍生 assume、resume 与 presume。"},{"era":"LATIN CONSUMERE","en":"Com- 'thoroughly' plus sumere produced consumere, 'to take up completely, use up, destroy'.","cn":"com-「彻底」加 sumere 构成 consumere，意为「完全取走、用尽、毁掉」。"},{"era":"LATIN CONSUMPTIO","en":"Consumptio named the act of using up or wasting away; the medical sense grew from visible wasting.","cn":"consumptio 指用尽或耗损的行为；医学义从可见的身体消耗发展而来。"},{"era":"SIXTEENTH-CENTURY ENGLISH","en":"English adopted consumption in the 1500s for using up goods, and for the wasting disease soon after.","cn":"英语在十六世纪吸收 consumption，指用尽货物，不久也指那种消耗性疾病。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the first date of the economic sense is not precisely recorded, and the year is approximate.","cn":"来源不确定：经济义的最早年代没有确切记录，给出的年份只是约数。"}]},"similar":{"note":{"en":"Group one holds same-root words easily mistaken for consumption; group two holds near words for using things up.","cn":"第一组是同根且易与 consumption 混淆的词；第二组是表示「用掉」的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"consummation","ipa":"/ˌkɒnsəˈmeɪʃən/","tag":"different root","definition":"From consummare, built on summa 'sum, total', meaning completion or the final sealing of a marriage; it is not from sumere.","definitionCN":"来自 consummare，由 summa「总和」构成，指完成或婚姻的最终结合；并非出自 sumere。"},{"word":"assumption","ipa":"/əˈsʌmpʃən/","tag":"same take-root","definition":"From ad- plus sumere: something taken up as true without proof; it shares the root but not the idea of using up.","definitionCN":"来自 ad- 加 sumere：未经证明即取为真；同根但不含「用尽」之意。"},{"word":"resumption","ipa":"/rɪˈsʌmpʃən/","tag":"same take-root","definition":"From re- plus sumere: the act of taking something up again after a pause.","definitionCN":"来自 re- 加 sumere：停顿之后重新拾起某事的动作。"},{"word":"consumerism","ipa":"/kənˈsjuːmərɪzəm/","tag":"same root, movement","definition":"The social system or movement built around buying goods, formed from consumer rather than from the act itself.","definitionCN":"围绕购买货物形成的社会制度或运动，由 consumer 而非动作本身构成。"}]},{"heading":"NEAR MEANING","entries":[{"word":"use","ipa":"/juːz/","tag":"plain word","definition":"The everyday verb and noun for employing something; it does not imply the thing is exhausted.","definitionCN":"使用某物的日常动词与名词；不含「用尽」之意。"},{"word":"expenditure","ipa":"/ɪkˈspendɪtʃə/","tag":"money view","definition":"The spending of money, or the amount spent; it is the accounting side of consumption.","definitionCN":"花钱或花费的数额；是 consumption 的会计侧面。"},{"word":"depletion","ipa":"/dɪˈpliːʃən/","tag":"resource view","definition":"The reduction of a stock until little is left; it stresses exhaustion rather than ordinary use.","definitionCN":"存量减少到所剩无几；强调耗尽而非普通使用。"},{"word":"intake","ipa":"/ˈɪnteɪk/","tag":"body view","definition":"The amount taken into the body or a system; it matches the food sense without the economic ones.","definitionCN":"摄入身体或系统的量；与饮食义相符，但不含经济义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the take-up root, the fixed phrases and the mirrored pair with production.","cn":"正常联想：「取起」词根、固定搭配，以及与生产对称的配对。"},"normal":[{"en":"Com- 'thoroughly' plus sumere 'take up': consumption takes a thing all the way up.","cn":"com-「彻底」加 sumere「取起」：消费把某物一路取尽。"},{"en":"The family runs consume, consumer, consumerism, consumable and consumptive.","cn":"同族词有 consume、consumer、consumerism、consumable 与 consumptive。"},{"en":"Fixed phrases: energy consumption, household consumption, consumption tax, fuel consumption.","cn":"固定说法：能源消耗、家庭消费、消费税、油耗。"},{"en":"The same take-root appears in assume, resume and presume.","cn":"同一「取」词根出现在 assume、resume 与 presume 中。"},{"en":"Economics pairs it with production, the making side and the using side.","cn":"经济学把它与生产配对，一侧制造，一侧用掉。"}],"abstract":[{"en":"Picture a warehouse emptied crate by crate while empty boxes pile up outside.","cn":"想象仓库一箱箱被搬空，空箱子在外面堆起来。"},{"en":"Picture a meter wheel that spins faster as the house fills with light and heat.","cn":"想象屋子里灯与暖气越来越多，电表轮盘转得越来越快。"},{"en":"Picture food disappearing from a plate without anyone noticing the moment it goes.","cn":"想象盘里的食物不知不觉就没了。"}]},"examples":[{"en":"The country's energy consumption fell for the first time in a decade.","cn":"该国能源消费十年来首次下降。"},{"en":"Advertising aims to shape consumption rather than simply report it.","cn":"广告意在塑造消费，而不只是反映消费。"},{"en":"Clean water consumption per household dropped after the new tariffs.","cn":"新水价实施后，每户的清洁水用量下降了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「con（彻底）+ sum（取）+ ption」——把东西彻底取走用掉，就是消费与消耗","word":"consumption"},"root":"拉丁 consumptio「消耗、耗尽」，来自 consumere = com-（彻底）+ sumere「取起」，而 sumere = sub- + emere「取、买」。","sensesIntro":{"en":"Eight senses follow one taking-up: using goods, household spending, drawn-down energy, food intake, consumed time, the wasting disease, material meant for outsiders and studied buying habits.","cn":"八个义项围绕「取走用掉」：使用商品、家庭支出、能源耗用、饮食摄入、耗去的时间、消耗性疾病、供外界阅读的材料，以及被研究的购买习惯。"},"semanticMap":{"core":{"en":"CORE IMAGE: a warehouse emptied crate by crate until only empty boxes remain.","cn":"核心意象：仓库一箱箱被搬空，最后只剩空箱。"},"chain":["GOODS USED UP","HOUSEHOLD SPENDING","ENERGY DRAWN","INTAKE","TIME SPENT","WASTING DISEASE"],"branches":[{"senses":"01 · 02","en":"USE AND MONEY: using goods and the spending that pays for them are the same taking-up seen in kind and in cash.","cn":"使用与金钱：使用货物与为其付钱，是同一「取用」的实物形态与货币形态。"},{"senses":"03 · 05","en":"DRAWN DOWN: electricity and hours are both stocks that shrink as they are used.","cn":"被抽走：电与工时都是越用越少的存量。"},{"senses":"04 · 08","en":"INTAKE AND HABIT: what enters the body and what people routinely buy are both measured patterns.","cn":"摄入与习惯：进入身体的东西与人们常买的东西，都是可测量的模式。"},{"senses":"06","en":"WASTING: a disease that seems to use the body up takes the word literally.","cn":"消耗：一种仿佛把身体耗尽的疾病，把这个词用到了字面上。"},{"senses":"07","en":"FOR OUTSIDERS: material offered to the public is meant to be taken in by them.","cn":"对外：提供给公众的材料，本就是要被他们接受的。"}]},"affixes":{"intro":{"en":"Consumption is a Latin noun of taking up thoroughly, and both its prefix and its take-root build English families.","cn":"consumption 是表示「彻底取起」的拉丁名词，其前缀与「取」词根都构成英语词族。"},"latinIntro":{"en":"Latin sumere gives assume, resume, presume and consumption; com- adds completion to the taking.","cn":"拉丁 sumere 衍生 assume、resume、presume 与 consumption；com- 给「取」添上彻底之意。"},"items":[{"word":"com-","structure":"Latin prefix (assimilating to con-)","meaning":"together; thoroughly","meaningCN":"共同；彻底","example":"The prefix makes the taking complete.","exampleCN":"这个前缀使「取」变得彻底。"},{"word":"sumere","structure":"Latin verb, third conjugation","meaning":"to take up","meaningCN":"取起；拿起","example":"The root carries the act of taking.","exampleCN":"这个词根带着「取」的动作。"},{"word":"consumere","structure":"com- + sumere","meaning":"to use up, destroy","meaningCN":"用尽；毁掉","example":"The verb consumed the whole store.","exampleCN":"这个动词把整个储备用尽。"},{"word":"consume","structure":"consumere through French","meaning":"to use up","meaningCN":"消耗；消费","example":"The engine consumes little fuel.","exampleCN":"这台发动机耗油很少。"},{"word":"consumption","structure":"consume + -tion","meaning":"the act or amount of using up","meaningCN":"消费（行为或数量）","example":"Consumption rose in the spring.","exampleCN":"消费在春季上升。"},{"word":"consumer","structure":"consume + -er","meaning":"one who uses goods","meaningCN":"消费者","example":"Consumers paid more for imports.","exampleCN":"消费者为进口货付了更多钱。"},{"word":"consumable","structure":"consume + -able","meaning":"able to be used up; a supply item","meaningCN":"可消耗的；消耗品","example":"Printer ink is a consumable.","exampleCN":"打印机墨水是消耗品。"},{"word":"assume","structure":"ad- + sumere","meaning":"to take up as true","meaningCN":"假定；承担","example":"We assume demand stays stable.","exampleCN":"我们假定需求保持稳定。"},{"word":"resume","structure":"re- + sumere","meaning":"to take up again","meaningCN":"重新开始","example":"Talks resumed in June.","exampleCN":"会谈在六月恢复。"}],"latinEntries":[{"word":"sumere","structure":"sumere, sumpsi, sumptum (verb, third conjugation)","meaning":"to take up, assume","meaningCN":"取起；承担"},{"word":"consumere","structure":"consumere, consumpsi, consumptum (verb, third conjugation)","meaning":"to use up, waste away","meaningCN":"用尽；耗损"},{"word":"consumptio","structure":"consumptio, consumptionis (f., third declension)","meaning":"a consuming, a wasting","meaningCN":"消耗；耗损"}],"derivatives":[{"word":"consume","pos":"v.","zh":"消费；消耗"},{"word":"consumer","pos":"n.","zh":"消费者"},{"word":"consumerism","pos":"n.","zh":"消费主义"},{"word":"consumable","pos":"adj./n.","zh":"可消耗的；消耗品"},{"word":"consumptive","pos":"adj./n.","zh":"（旧）患肺痨的；肺痨患者"}]}}]);
